_MIGRATION_V18 = """
-- V18 (2026-09-04): the usage event — one row per completed model turn.
--
-- Everything the analytics console reports about REQUESTS, TOKENS, TTFT and
-- throughput comes from here. It exists because none of that was persisted:
-- `messages.meta` carried the prompt size and the route, vLLM's Prometheus
-- metrics carried latency and token totals for the SERVER, and nothing joined
-- the two to a person. Prometheus cannot answer "who" — a user id as a label
-- is unbounded cardinality — so the per-person half lives in PostgreSQL and
-- the per-engine half stays in Prometheus, which is what each is good at.
--
-- Metadata only. No prompt, no completion, no retrieved text: the console
-- answers who/how much/how fast, and reading content is a different
-- capability (workspace_content.read) with its own audit trail.
CREATE TABLE IF NOT EXISTS usage_events (
    id              bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at      timestamptz NOT NULL,
    -- Nullable for the same reason web_searches.user_id is: /chat still
    -- serves unauthenticated calls, and those must not be dropped or faked.
    user_id         integer     REFERENCES users(id) ON DELETE CASCADE,
    -- Denormalised on purpose. A membership can be removed; the usage it
    -- generated still belongs in the workspace's history.
    workspace_id    text,
    conversation_id text,
    generation_id   text,
    -- Which engine answered (chat, search, deep_research, sql, vision, ...),
    -- the effort tier, and the model that served it.
    route           text        NOT NULL DEFAULT 'chat',
    effort          text        NOT NULL DEFAULT '',
    model           text        NOT NULL DEFAULT '',
    mode            text        NOT NULL DEFAULT '',
    -- Exact when vLLM reported it (prompt tokens come from POST /tokenize,
    -- completion tokens from the stream's usage chunk); NULL when a turn
    -- ended before the engine reported, never an estimate dressed as a fact.
    input_tokens    integer,
    output_tokens   integer,
    reasoning_tokens integer,
    -- Orchestrator-side, which is the number the person waiting experiences:
    -- it includes retrieval, reranking and every pre-pass, unlike vLLM's own.
    ttft_ms         integer,
    duration_ms     integer,
    status          text        NOT NULL DEFAULT 'ok'
                    CONSTRAINT usage_events_status CHECK
                    (status IN ('ok', 'error', 'cancelled')),
    error_kind      text        NOT NULL DEFAULT '',
    meta            jsonb       NOT NULL DEFAULT '{}'::jsonb
);
-- Every analytics query is "a window, then a grouping", so time leads each
-- index and the grouping column follows it.
CREATE INDEX IF NOT EXISTS idx_usage_events_time
    ON usage_events (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_usage_events_workspace_time
    ON usage_events (workspace_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_usage_events_user_time
    ON usage_events (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_usage_events_model_time
    ON usage_events (model, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_usage_events_route_time
    ON usage_events (route, created_at DESC);
-- One row per generation. Two clients attached to the same detached answer
-- both reach the meta emitter; the second must not double-count the turn.
CREATE UNIQUE INDEX IF NOT EXISTS idx_usage_events_generation
    ON usage_events (generation_id) WHERE generation_id IS NOT NULL;
"""


_MIGRATION_V19 = """
-- V19 (2026-09-04): voice dictation, as METADATA.
--
-- One row per transcription ATTEMPT — including the ones that failed, because
-- an error rate computed from successes alone is not an error rate, and
-- "dictation never works for me" is a claim the console should be able to
-- check.
--
-- WHAT IS NOT HERE, AND WILL NOT BE. No audio. No transcript. No conversation
-- id. A recording is a DRAFT: it becomes a message only when the person
-- presses Send, and then it is stored exactly like anything they typed, in
-- `messages`, under their own conversation. This table cannot reconstruct a
-- single word anybody said, and that is the point of it.
CREATE TABLE IF NOT EXISTS voice_transcriptions (
    id             bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at     timestamptz NOT NULL,
    user_id        integer     REFERENCES users(id) ON DELETE CASCADE,
    -- How long they spoke, as the browser measured it. NULL when the client
    -- did not report it — not 0, which would drag every average down.
    duration_ms    integer,
    -- The language the model IDENTIFIED, in its own vocabulary, or NULL when
    -- identification did not survive. Never a guess.
    language       text,
    -- Orchestrator-side wall clock: upload, queue and engine together, which
    -- is the wait the person actually experienced.
    processing_ms  integer,
    status         text        NOT NULL DEFAULT 'ok'
                   CONSTRAINT voice_transcriptions_status CHECK
                   (status IN ('ok', 'busy', 'rejected', 'unavailable', 'error')),
    -- True when the primary engine path failed and the fallback answered, so
    -- a quietly degraded deployment is visible before anyone complains.
    degraded       boolean     NOT NULL DEFAULT false
);
CREATE INDEX IF NOT EXISTS idx_voice_transcriptions_time
    ON voice_transcriptions (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_voice_transcriptions_user_time
    ON voice_transcriptions (user_id, created_at DESC);
"""


_MIGRATION_V20 = """
-- V20 (2026-09-05): conversation sharing — a link anyone can open.
--
-- A SNAPSHOT, NOT A WINDOW ONTO THE LIVE CHAT. The public page renders a
-- frozen, sanitised copy taken at an instant the owner chose. That is the
-- whole security model: the private conversation keeps moving, and nothing
-- the owner says tomorrow can appear on a link they shared today. Two tables
-- rather than one because the snapshot has a LIFETIME of its own — an owner
-- may re-publish, and the version that was live when someone opened the link
-- has to remain a thing that existed.
--
-- THE TOKEN IS NEVER STORED. `public_id` addresses the row; the secret half
-- of the URL is kept only as sha256, exactly as auth_sessions keeps session
-- secrets (authn/sessions.py). A database dump yields no working link, and
-- neither does this table in a backup. Revocation is a column, not a key
-- rotation, so stopping a share is one UPDATE and takes effect on the next
-- request.
CREATE TABLE IF NOT EXISTS conversation_shares (
    id              bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    conversation_id text        NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
    workspace_id    text        NOT NULL,
    created_by      integer     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    -- The half of the URL that is safe to store and to log.
    public_id       text        NOT NULL UNIQUE,
    -- sha256 of the secret half. Never the secret itself.
    secret_hash     text        NOT NULL,
    visibility      text        NOT NULL DEFAULT 'public'
                    CONSTRAINT conversation_shares_visibility CHECK
                    (visibility IN ('public', 'workspace')),
    status          text        NOT NULL DEFAULT 'active'
                    CONSTRAINT conversation_shares_status CHECK
                    (status IN ('active', 'revoked')),
    -- Off by default. A shared link says what was said, not who said it.
    show_owner_name boolean     NOT NULL DEFAULT false,
    current_version bigint,
    expires_at      timestamptz,
    created_at      timestamptz NOT NULL,
    updated_at      timestamptz NOT NULL,
    revoked_at      timestamptz,
    revoked_by      integer     REFERENCES users(id) ON DELETE SET NULL,
    last_viewed_at  timestamptz,
    view_count      bigint      NOT NULL DEFAULT 0
);

-- ONE ACTIVE SHARE PER CONVERSATION. A partial unique index rather than
-- application logic: two clicks on "Create link" are two requests, and the
-- second must lose in the DATABASE or both succeed and the owner has two
-- live links they can only revoke one of.
CREATE UNIQUE INDEX IF NOT EXISTS idx_conversation_shares_one_active
    ON conversation_shares (conversation_id) WHERE status = 'active';
-- The anonymous read path: one index-only hop from URL to row.
CREATE INDEX IF NOT EXISTS idx_conversation_shares_public
    ON conversation_shares (public_id) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_conversation_shares_owner
    ON conversation_shares (created_by, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_conversation_shares_workspace
    ON conversation_shares (workspace_id, status, created_at DESC);
-- The expiry sweep, and the admin console's "expiring soon".
CREATE INDEX IF NOT EXISTS idx_conversation_shares_expiry
    ON conversation_shares (expires_at) WHERE status = 'active' AND expires_at IS NOT NULL;

-- One row per PUBLISH. Immutable once written: the payload is the answer to
-- "what did this link show", and rewriting it would make that unanswerable.
CREATE TABLE IF NOT EXISTS conversation_share_versions (
    id              bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    share_id        bigint      NOT NULL REFERENCES conversation_shares(id) ON DELETE CASCADE,
    version_number  integer     NOT NULL,
    -- The sanitised public DTO, whole. The public page reads THIS and never
    -- touches messages: no join to private data means no join to leak.
    payload         jsonb       NOT NULL,
    content_hash    text        NOT NULL,
    -- The high-water mark. "New messages have not been shared" is a
    -- comparison against this, not a guess.
    last_message_id bigint,
    message_count   integer     NOT NULL DEFAULT 0,
    created_by      integer     REFERENCES users(id) ON DELETE SET NULL,
    created_at      timestamptz NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_share_versions_number
    ON conversation_share_versions (share_id, version_number);
CREATE INDEX IF NOT EXISTS idx_share_versions_share
    ON conversation_share_versions (share_id, created_at DESC);

-- Deferred so the two tables can reference each other.
ALTER TABLE conversation_shares
    DROP CONSTRAINT IF EXISTS conversation_shares_current_version_fkey;
ALTER TABLE conversation_shares
    ADD CONSTRAINT conversation_shares_current_version_fkey
    FOREIGN KEY (current_version) REFERENCES conversation_share_versions(id)
    ON DELETE SET NULL;

-- Per-workspace policy. Additive with a DEFAULT, so an existing row keeps
-- working and the safe answer is the one a workspace gets by doing nothing:
-- sharing within the workspace yes, to the open internet only once a super
-- admin says so.
ALTER TABLE workspaces ADD COLUMN IF NOT EXISTS
    sharing_policy jsonb NOT NULL DEFAULT '{}'::jsonb;
"""


_MIGRATION_V21 = """
-- V21 (2026-09-05): which extractor produced a page's stored text.
--
-- RESTORED HISTORY, NOT NEW WORK. This migration was applied to the live
-- database on 2026-09-05 04:59:59Z by a build that was later rolled back.
-- Restoring source cannot un-apply a migration, so production kept these
-- objects while the code that created them left the tree, and `schema_
-- migrations` recorded a 21 that no source file explained.
--
-- The definition below is recovered VERBATIM from commits 34a7e3c / 829f17c
-- (identical in both), not reconstructed from a schema diff — which matters,
-- because a column-level diff of the live database missed the index entirely.
-- Restoring the authentic text under its own identifier is what keeps the
-- ledger honest: a database that already ran it skips it (the row is present),
-- a fresh database now gets exactly what production has, and no identifier is
-- ever reused for different content.
--
-- The original comment, preserved as written:
--
--   The readable-text pass dropped every row of a ranking page (the GPT-5.2
--   regression); core/structured.py now appends tables, card lists and
--   embedded records. Pages stored before that carry the OLD text, and the
--   vector index chunks built from it. Rather than a one-off mass recrawl,
--   every page records the extractor version that filled it; the refresh
--   worker re-reads pages below the current version most-retrieved first,
--   inside its ordinary per-cycle budget (see web_worker._due_pages).
--   0 = unknown/legacy; the constant lives in core/extract.EXTRACT_VERSION.
--
-- That reasoning still holds, and this phase's extraction change recreates the
-- same situation, which is why the column is adopted deliberately rather than
-- dropped. `core/structured.py` does not exist in this tree; the equivalent
-- augmentation now lives inside core/extract.py.
ALTER TABLE web_pages ADD COLUMN IF NOT EXISTS
    extract_version smallint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS idx_web_pages_extract_version
    ON web_pages (extract_version) WHERE extract_version < 2;
"""


_MIGRATION_V22 = """
-- V22 (2026-09-06): make the stale-extractor index version-agnostic.
--
-- V21's index hardcodes the then-current extractor version in its predicate
-- (`WHERE extract_version < 2`). Every bump of core/extract.EXTRACT_VERSION
-- therefore silently stops indexing the rows the refresh worker needs to find:
-- at EXTRACT_VERSION 3, pages sitting at 2 are exactly the ones due for
-- re-reading and are the ones the partial index excludes.
--
-- The replacement carries no version literal, so it never needs revisiting,
-- and its column order matches the query the worker actually runs — pages
-- below the current version, most-retrieved first (web_worker._due_pages).
DROP INDEX IF EXISTS idx_web_pages_extract_version;
CREATE INDEX IF NOT EXISTS idx_web_pages_extract_stale
    ON web_pages (extract_version, retrieval_count DESC);
"""


_MIGRATION_V23 = """
-- V23 (2026-09-06): heal the pages that could never be refreshed.
--
-- V21 is restored history and V22 modernises its index; this is the new work.
--
-- V13 added next_refresh_at and seeded it for every row that existed at the
-- time, but `upsert_web_page` never listed the column, so every page stored
-- AFTER that migration was written with NULL and `_due_pages` (which requires
-- `next_refresh_at IS NOT NULL`) could never see it again. Measured on the
-- live corpus 2026-09-06: origin 'research' 123/123 NULL, 'crawl' 214/214
-- NULL, 'search' 1265/1871 NULL — 1602 of 2208 pages, 73%, permanently
-- stranded. The 606 rows that were scheduled are exactly the V13 survivors.
--
-- The upsert now seeds the column, so this backfill only has to catch the
-- rows already stranded. Staggered across 24h for the same reason V13
-- staggered: healing 1600 pages must not queue 1600 simultaneous fetches on
-- the first worker cycle. Only pages with text are scheduled, matching the
-- `text <> ''` filter the scheduler itself applies.
UPDATE web_pages
   SET next_refresh_at = now() + (random() * interval '24 hours')
 WHERE next_refresh_at IS NULL AND text <> '';
"""


_MIGRATION_V24 = """
-- V24 (2026-09-06): which CHUNKER produced a page's vectors.
--
-- V21/V22 gave every page the extractor version that produced its TEXT. This
-- is the same idea one stage later, and it is a genuinely different fact: the
-- chunker can change while the extractor does not (chunk width, overlap, or —
-- as in this phase — repeating a table's header row into every chunk that
-- holds its data, so a retrieved chunk is not bare numbers with no columns).
--
-- Without this the only signal was `indexed_at`, which answers "were these
-- vectors ever built" and not "were they built by the CURRENT chunker". So a
-- page whose text never changes keeps chunks from an obsolete chunker forever,
-- and the only remedy was an operator-run full reindex. `chunker_version` in
-- the LanceDB sidecar is per-INDEX, not per-page, so it cannot drive an
-- incremental repair either.
--
-- 0 = unknown/legacy, exactly as extract_version. The constant lives in
-- web_index.CHUNKER_VERSION and is passed in by the caller — db.py must not
-- import web_index, which imports db.
--
-- The index carries no version literal (see V22 for why that was a trap) and
-- orders by demand, so the repair drains most-retrieved-first inside the
-- worker's ordinary per-cycle budget.
ALTER TABLE web_pages ADD COLUMN IF NOT EXISTS
    chunk_version smallint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS idx_web_pages_chunk_stale
    ON web_pages (chunk_version, retrieval_count DESC);
"""


_MIGRATION_V25 = """
-- V25 (2026-09-07): the crawl frontier becomes durable (K12).
--
-- WHAT WAS WRONG. `engines/crawl._crawl_site` held its whole work queue in
-- two Python locals: `frontier: List[Tuple[str, int]]` and
-- `_CrawlState.visited: Set[str]`. Nothing was persisted, so a restart, a
-- deploy, a closed tab or an OOM threw the queue away. Progress appeared to
-- survive only by accident: the requeued job re-derived the frontier from the
-- sitemap and `process()` skipped pages still fresh in `web_pages` within
-- `web_page_ttl_s` (24h). Two cases got no protection from that accident at
-- all -- a LINK-WALK crawl of a site with no usable sitemap restarted from
-- the root and had to re-walk its way back to where it stopped, and ANY crawl
-- resumed after the 24h TTL re-fetched every page it had already read.
--
-- WHY A TABLE AND NOT A COLUMN. The queue is a set of URLs with depths, not a
-- scalar, and it must survive a process that is not running. It is keyed by
-- `scope_prefix`, NOT by `web_crawls.id`, because a crawl CAMPAIGN outlives
-- any one row: a foreground "continue crawling" opens a brand-new web_crawls
-- row (engines/crawl.run_crawl_engine -> db.create_web_crawl) for the same
-- site, so a crawl_id key would have made every foreground resume start from
-- an empty frontier -- exactly the defect this migration exists to remove.
-- `scope_prefix` is already the project's identity for "a crawl of this
-- site": db.enqueue_web_crawl dedupes queued and running jobs by it.
--
-- `crawl_id` therefore records WHICH run last touched a row (provenance for
-- the operator, and a real FK so deleting crawl history cannot leave rows
-- pointing at nothing) and is deliberately NOT part of the key. ON DELETE SET
-- NULL: removing a crawl's history must never destroy the progress of a
-- campaign that is still open.
--
-- STATE MACHINE, and why 'visited' is stamped AFTER the page settles rather
-- than when it is claimed. The in-memory code added a URL to `visited` BEFORE
-- fetching it. Persisting that shape would have converted "interrupted
-- mid-fetch" into "permanently skipped": the row would say visited and the
-- page would never have been read. A row leaves 'pending' only once the page
-- has actually settled, so the worst an interruption can cost is re-fetching
-- the handful of pages that were in flight -- duplication of bounded, polite
-- work, never a silent hole in the crawl.
--
-- `failures` bounds the other direction. A page that fails to fetch stays
-- pending so a transient blip is retried, but only until the counter reaches
-- the caller's cap (engines/crawl._FRONTIER_MAX_FAILURES); after that it is
-- marked visited/'failed' so a resume cannot spend its whole page budget
-- re-attempting the same dead URL on every restart -- the "stopped at the
-- same spot every time" failure the V9 review already recorded once.
--
-- No index predicate carries a literal that can move (see V22 for the trap
-- V21 fell into): the ordering index is a plain composite over the columns
-- the claim query actually orders by.
CREATE TABLE IF NOT EXISTS web_crawl_frontier (
    id           bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- The campaign this URL belongs to: web_crawls.scope_prefix, i.e. the
    -- normalized "host/path" prefix every page of the crawl must start with.
    scope_prefix text        NOT NULL,
    -- The store key (engines.search._normalize_url), so the frontier and
    -- web_pages agree on what "the same page" means.
    url_key      text        NOT NULL,
    url          text        NOT NULL,
    depth        smallint    NOT NULL DEFAULT 0,
    state        text        NOT NULL DEFAULT 'pending'
                 CONSTRAINT web_crawl_frontier_state CHECK
                 (state IN ('pending', 'visited')),
    -- How the page settled: fetched | store | failed | refused | blocked |
    -- offsite. '' while pending. Kept so "did the crawl skip anything, and
    -- why" is answerable from the database instead of from log archaeology.
    outcome      text        NOT NULL DEFAULT '',
    failures     smallint    NOT NULL DEFAULT 0,
    crawl_id     bigint      REFERENCES web_crawls (id) ON DELETE SET NULL,
    enqueued_at  timestamptz NOT NULL DEFAULT now(),
    visited_at   timestamptz
);
-- Identity of a frontier entry, and the ON CONFLICT target that makes
-- re-seeding a resumed campaign idempotent: a URL already visited must not be
-- reset to pending by the next run re-reading the same sitemap.
CREATE UNIQUE INDEX IF NOT EXISTS idx_web_crawl_frontier_key
    ON web_crawl_frontier (scope_prefix, url_key);
-- The claim query: the shallowest unvisited pages of one campaign, in
-- discovery order (breadth-first, exactly as the in-memory list behaved).
CREATE INDEX IF NOT EXISTS idx_web_crawl_frontier_next
    ON web_crawl_frontier (scope_prefix, state, depth, id);
"""


_MIGRATION_V26 = """
-- V26 (2026-09-07): stop `last_changed_at` claiming changes nobody observed.
--
-- WHAT THE COLUMN MEANS. V13 defined it precisely -- "stamped by the upsert
-- only when content_hash actually moves, so a page re-fetched daily with
-- identical bytes does not look freshly authored". The UPDATE path has always
-- honoured that. Two other writes did not:
--
--   * `upsert_web_page` passed `now` for it on every FIRST insert, so a page
--     seen once carried a change timestamp for a change that never happened;
--   * V13's own backfill ran `SET last_changed_at = fetched_at WHERE
--     last_changed_at IS NULL`, describing fetched_at as "the best known
--     lower bound" -- an honest approximation that the column's stated
--     meaning cannot express, because a lower bound is not an observation.
--
-- Measured on the live corpus 2026-09-06: 1,338 of 2,208 rows (61%) hold
-- last_changed_at EXACTLY equal to fetched_at. The write-path half is fixed
-- above (the INSERT now writes NULL); this migration decides what to do with
-- the rows already written.
--
-- WHY NOT BACKFILL A BETTER GUESS. There is nothing to back-fill FROM. The
-- moment a page's content moved was never recorded, and no column in this
-- schema is a proxy for it: published_at and modified_at are what the PAGE
-- claims about itself (frequently absent, frequently a build timestamp), and
-- web_page_versions only exists from the second observed change onwards.
-- Inventing a date here is the exact mistake being corrected.
--
-- WHY NOT A SECOND COLUMN. The obvious alternative -- leave this column alone
-- and add a new, honest one beside it -- was rejected on evidence. Nothing
-- READS last_changed_at for ranking today: web_memory._page_meta selects it
-- (web_memory.py:1180) and never copies it onto Evidence, which has no field
-- for it; the only consumer of the concept is web_worker._mark_changed, which
-- WRITES it. So a second column would add a fourth thing for four call sites
-- to maintain, in service of no reader, and would leave this column
-- permanently ambiguous instead of converging on one meaning. Fixing the
-- meaning in place is cheaper and leaves one column that means one thing.
--
-- WHAT IS CLEARED, AND WHY IT IS A PROOF RATHER THAN A GUESS. Only rows we
-- have fetched EXACTLY ONCE:
--
--     fetch_count = 1 AND first_seen_at = fetched_at AND last_changed_at = fetched_at
--
-- A change is observed by comparing two fetches. A page that has been fetched
-- once has no second observation to compare against, so its stored
-- "last changed" CANNOT be an observation -- whatever wrote it, it wrote a
-- default. fetch_count is bumped by both writers that see a page again
-- (`upsert_web_page`'s ON CONFLICT and `touch_web_page_unchanged`'s 304
-- path), and first_seen_at is set on insert and never updated, so the three
-- conditions together are decidable from the row alone.
--
-- WHAT IS DELIBERATELY LEFT ALONE. Rows with fetch_count > 1 whose
-- last_changed_at happens to equal fetched_at. Some are V13 backfill
-- survivors (invented) and some are pages that genuinely changed on their
-- most recent fetch -- `upsert_web_page` writes both timestamps from a single
-- `now`, so a real change makes them exactly equal too. The two are not
-- distinguishable from the data, and "probably invented" is not a reason to
-- destroy a value that may be real. They stay, and they will correct
-- themselves the next time the refresh worker observes an actual change.
--
-- AFTER THIS, NULL MEANS ONE THING: we have never observed this page's
-- content move. A reader wanting a lower bound should fall back to
-- first_seen_at explicitly -- which is what the old value was silently
-- pretending to be.
--
-- Idempotent: re-running matches nothing, because the rows it touched no
-- longer satisfy `last_changed_at = fetched_at`.
UPDATE web_pages
   SET last_changed_at = NULL
 WHERE last_changed_at IS NOT NULL
   AND last_changed_at = fetched_at
   AND first_seen_at = fetched_at
   AND fetch_count = 1;
"""


_MIGRATION_V27 = """
-- V27 (2026-09-07): raise the chunk cap WITHOUT re-embedding the whole corpus.
--
-- `web_index._MAX_CHUNKS_PER_PAGE` rose 64 -> 256 and `CHUNKER_VERSION` 2 -> 3,
-- which by itself would put all 2,063 indexable pages into the V24 re-chunk
-- queue: ~16,000 chunks, ~6 minutes of embedding at full tilt, and — measured —
-- 1.65x to 4x the time-to-first-token for anyone using the platform while it
-- drains. Almost all of that work would be wasted.
--
-- IT IS PROVABLY UNNECESSARY FOR MOST PAGES. `chunk_page` stops on
-- `start + CHUNK >= len(text)`, not on the cap, so the cap only binds for a
-- page needing more than 64 chunks. A page whose text fits in the OLD ceiling
-- (179,600 chars) therefore chunks BYTE-IDENTICALLY at either cap: same
-- windows, same header carry, same text. Its vectors are already correct for
-- chunker 3 and re-embedding them would produce the same numbers.
--
-- Measured on the live corpus 2026-09-07: 59 of 2,208 stored pages exceed
-- 179,600 characters. Only those need re-chunking; the other ~2,004 indexable
-- pages are stamped here.
--
-- The literal 179600 is deliberate and must NOT be replaced with
-- `INDEXED_CHARS_PER_PAGE`: that constant now reads 717,200, and this migration
-- is a statement about the ceiling that was in force when those rows were
-- indexed. (V22 exists because a version literal in a predicate went stale;
-- this is the opposite case — a historical constant that must stay pinned.)
UPDATE web_pages
   SET chunk_version = 3
 WHERE indexed_at IS NOT NULL
   AND chunk_version = 2
   AND length(text) <= 179600;
"""


_MIGRATION_V28 = """
-- V28 (2026-09-09): video understanding.
--
-- `video_analyses` is one row per DISTINCT VIDEO — keyed by the sha256 of
-- the bytes, like web_pages is keyed by URL — so a file attached twice, by
-- anyone, is analysed once. Nothing here says WHO attached it WHERE; that is
-- `video_attachments`, which has no FK on conversation_id for the same reason
-- uploads and documents have none (bare /chat calls carry no conversations
-- row) and is cleared by delete_conversation through _SIDE_TABLES.
--
-- Per-stage state is one jsonb (`stages`: {stage: {status, ms, detail}}),
-- not nine column triples: the stages are a pipeline the code owns, and a
-- new stage must not need a migration. The stage OUTPUTS are files under
-- VIDEO_DATA_DIR/<hash>/; a stage is 'done' here only after its file is
-- durable, so a restart resumes at the first stage without one.
CREATE TABLE IF NOT EXISTS video_analyses (
    id                bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    content_hash      text        NOT NULL UNIQUE,
    bytes             bigint      NOT NULL,
    media_type        text        NOT NULL DEFAULT '',
    filename          text        NOT NULL DEFAULT '',
    status            text        NOT NULL DEFAULT 'queued'
                      CONSTRAINT video_analyses_status CHECK
                      (status IN ('queued', 'running', 'done', 'failed')),
    stage             text        NOT NULL DEFAULT 'probe',
    stages            jsonb       NOT NULL DEFAULT '{}'::jsonb,
    error             text        NOT NULL DEFAULT '',
    attempt           integer     NOT NULL DEFAULT 0,
    pipeline_version  smallint    NOT NULL DEFAULT 1,
    duration_ms       integer,
    width             integer,
    height            integer,
    has_audio         boolean,
    has_video         boolean,
    language          text,
    probe             jsonb       NOT NULL DEFAULT '{}'::jsonb,
    counts            jsonb       NOT NULL DEFAULT '{}'::jsonb,
    summary           text        NOT NULL DEFAULT '',
    understanding     jsonb       NOT NULL DEFAULT '{}'::jsonb,
    artifacts         jsonb       NOT NULL DEFAULT '[]'::jsonb,
    indexed_at        timestamptz,
    chunk_version     smallint    NOT NULL DEFAULT 0,
    created_at        timestamptz NOT NULL,
    updated_at        timestamptz NOT NULL,
    started_at        timestamptz,
    finished_at       timestamptz
);
CREATE INDEX IF NOT EXISTS idx_video_analyses_queue
    ON video_analyses (status, id) WHERE status IN ('queued', 'running');

CREATE TABLE IF NOT EXISTS video_attachments (
    id              bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    analysis_id     bigint      NOT NULL REFERENCES video_analyses(id) ON DELETE CASCADE,
    conversation_id text        NOT NULL,
    user_id         integer     REFERENCES users(id) ON DELETE CASCADE,
    upload_id       text        NOT NULL DEFAULT '',
    filename        text        NOT NULL,
    created_at      timestamptz NOT NULL,
    UNIQUE (conversation_id, analysis_id)
);
CREATE INDEX IF NOT EXISTS idx_video_attachments_conv
    ON video_attachments (conversation_id, id);
CREATE INDEX IF NOT EXISTS idx_video_attachments_analysis
    ON video_attachments (analysis_id, id);
"""


_MIGRATION_V29 = """
-- V29 (2026-09-10): upload reliability — durable upload sessions, durable
-- chat intents, and a lease on analysis runs.
--
-- `upload_sessions` is the chunked rail's state, in the database instead of
-- a marker file: who owns it, what is expected, which parts have ARRIVED
-- (with their sizes and, when the client sent one, their sha256), when it
-- expires, and — once finalised — the exact response `complete` returned, so
-- a retried `complete` after a lost acknowledgement replays it instead of
-- answering 404. Nothing here holds bytes; the parts stay on disk under the
-- workspace, and `expires_at` is what the sweep reads before it removes them.
--
-- `chat_requests` is one row per SEND INTENT (a browser-minted id): what was
-- asked, for which conversation, under which generation_id. It exists so a
-- request the server accepted survives the process that accepted it. A
-- restart marks every open row `interrupted`; re-attaching to the
-- conversation resumes it from the stored request under a NEW attempt, and a
-- second POST /chat with a known intent_id attaches or replays rather than
-- starting a second generation. `request` is the snapshot to resume from;
-- rows that cannot be resumed (inline bytes the server did not keep) say so
-- in `resumable`.
--
-- `video_analyses.lease_*`: a run holds a lease with a heartbeat. Startup
-- reconciliation requeues only rows whose lease has EXPIRED, so a second
-- process (or a restart that was really a rolling recreate next to a healthy
-- worker) cannot steal a run that is still going.
CREATE TABLE IF NOT EXISTS upload_sessions (
    id              text        PRIMARY KEY,
    user_id         integer     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    conversation_id text        NOT NULL,
    filename        text        NOT NULL,
    purpose         text        NOT NULL
                    CONSTRAINT upload_sessions_purpose CHECK
                    (purpose IN ('dataset', 'document', 'video')),
    expected_bytes  bigint,
    expected_parts  integer,
    part_size       bigint,
    accepted_parts  jsonb       NOT NULL DEFAULT '{}'::jsonb,
    bytes_received  bigint      NOT NULL DEFAULT 0,
    status          text        NOT NULL DEFAULT 'uploading'
                    CONSTRAINT upload_sessions_status CHECK
                    (status IN ('uploading', 'finalizing', 'complete', 'expired', 'rejected', 'cancelled')),
    error           text        NOT NULL DEFAULT '',
    result          jsonb,
    created_at      timestamptz NOT NULL,
    updated_at      timestamptz NOT NULL,
    expires_at      timestamptz NOT NULL,
    completed_at    timestamptz
);
CREATE INDEX IF NOT EXISTS idx_upload_sessions_conv
    ON upload_sessions (conversation_id, created_at);
CREATE INDEX IF NOT EXISTS idx_upload_sessions_open
    ON upload_sessions (expires_at) WHERE status IN ('uploading', 'finalizing');

CREATE TABLE IF NOT EXISTS chat_requests (
    intent_id       text        PRIMARY KEY,
    user_id         integer     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    conversation_id text        NOT NULL,
    generation_id   text        NOT NULL UNIQUE,
    status          text        NOT NULL DEFAULT 'accepted'
                    CONSTRAINT chat_requests_status CHECK
                    (status IN ('accepted', 'running', 'completed', 'failed', 'cancelled', 'interrupted')),
    attempt         integer     NOT NULL DEFAULT 1,
    resumable       boolean     NOT NULL DEFAULT true,
    request         jsonb       NOT NULL,
    error           text        NOT NULL DEFAULT '',
    created_at      timestamptz NOT NULL,
    updated_at      timestamptz NOT NULL,
    finished_at     timestamptz
);
CREATE INDEX IF NOT EXISTS idx_chat_requests_conv
    ON chat_requests (conversation_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_chat_requests_open
    ON chat_requests (status) WHERE status IN ('accepted', 'running', 'interrupted');

ALTER TABLE video_analyses ADD COLUMN IF NOT EXISTS lease_owner text NOT NULL DEFAULT '';
ALTER TABLE video_analyses ADD COLUMN IF NOT EXISTS lease_expires_at timestamptz;
"""


_MIGRATION_V30 = """
-- V30 (2026-09-11): durable, generation-correlated query tracing.
--
-- A trace is deliberately keyed by the existing generation_id. SSE events,
-- stored message metadata, usage telemetry and these diagnostic checkpoints
-- can therefore be joined without inventing another correlation identifier.
CREATE TABLE IF NOT EXISTS query_traces (
    trace_id          text        PRIMARY KEY,
    conversation_id  text        NOT NULL,
    user_id           integer     REFERENCES users(id) ON DELETE SET NULL,
    workspace_id      text,
    original_question text        NOT NULL DEFAULT '',
    requested_mode    text        NOT NULL DEFAULT '',
    resolved_mode     text        NOT NULL DEFAULT '',
    selected_route    text        NOT NULL DEFAULT '',
    final_status      text        NOT NULL DEFAULT 'running'
                      CONSTRAINT query_traces_status CHECK
                      (final_status IN ('running', 'ok', 'error', 'cancelled')),
    started_at        timestamptz NOT NULL,
    completed_at      timestamptz,
    total_duration_ms integer,
    error_stage       text        NOT NULL DEFAULT '',
    error_type        text        NOT NULL DEFAULT '',
    error_message     text        NOT NULL DEFAULT '',
    meta              jsonb       NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX IF NOT EXISTS idx_query_traces_conversation
    ON query_traces (conversation_id, started_at DESC);
CREATE INDEX IF NOT EXISTS idx_query_traces_workspace
    ON query_traces (workspace_id, started_at DESC);

CREATE TABLE IF NOT EXISTS query_trace_events (
    id              bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    trace_id        text        NOT NULL REFERENCES query_traces(trace_id) ON DELETE CASCADE,
    sequence_number integer     NOT NULL,
    stage           text        NOT NULL,
    status          text        NOT NULL DEFAULT 'success'
                    CONSTRAINT query_trace_events_status CHECK
                    (status IN ('running', 'success', 'failed', 'info', 'skipped')),
    created_at      timestamptz NOT NULL,
    duration_ms     integer,
    component       text        NOT NULL DEFAULT '',
    details         jsonb       NOT NULL DEFAULT '{}'::jsonb,
    error_type      text        NOT NULL DEFAULT '',
    error_message   text        NOT NULL DEFAULT '',
    UNIQUE (trace_id, sequence_number)
);
CREATE INDEX IF NOT EXISTS idx_query_trace_events_trace
    ON query_trace_events (trace_id, sequence_number);
CREATE INDEX IF NOT EXISTS idx_query_trace_events_stage
    ON query_trace_events (stage, created_at DESC);
"""


_MIGRATION_V31 = """
-- V31 (2026-09-11): Artifact Studio — documents, decks and workbooks made in
-- chat, as DURABLE, VERSIONED, OWNER-SCOPED things.
--
-- `artifacts` is the identity a person edits, converts and reopens: one row
-- per artifact, keyed by a server-minted uuid4 hex, owned by a user (CASCADE:
-- a removed account takes its files' rows with it, as report_files does).
-- `conversation_id` is informational and has no FK, for the same reason
-- report_files has none and for the same reason the table is NOT in
-- _SIDE_TABLES: deleting a chat must not take the person's deliverables with
-- it. An artifact is addressable by id from GET /artifacts without its
-- conversation, and a file a person downloaded last week is theirs whether
-- or not the chat that produced it still exists.
--
-- `artifact_versions` is immutable once published: what was asked
-- (operation, instruction, parent_version), what came out (files with
-- sizes and sha256s, warnings, validation), and which template/renderer
-- produced it so a later renderer never silently re-renders an old version
-- differently. `files` is jsonb rather than a fourth table because a version
-- has at most three files and the API reads them as one unit.
--
-- `artifact_jobs` is the unit of work: exactly one job produces exactly one
-- version. It follows video_analyses (V28/V29) line by line — CHECK-
-- constrained status, `stage` for the position within running, `progress`
-- jsonb for the per-stage map (a new stage must not need a migration),
-- `attempt`, and the V29 lease (`lease_owner`, `lease_expires_at`) renewed by
-- a heartbeat so startup requeues only rows whose owner is dead — but is
-- keyed by OWNER + artifact + version, not by content hash: two people asking
-- for the same document get two artifacts. `idempotency_key` is what a chat
-- turn retried after a lost acknowledgement presents: the same acceptance
-- answers with the same job instead of a second one. `error` is a sentence
-- for a person and `diagnostic_ref` the log correlation id; a stack trace,
-- DSN, host or path never lands in either.
CREATE TABLE IF NOT EXISTS artifacts (
    id               text        PRIMARY KEY,
    user_id          integer     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    conversation_id  text        NOT NULL DEFAULT '',
    title            text        NOT NULL DEFAULT '',
    kind             text        NOT NULL
                     CONSTRAINT artifacts_kind CHECK
                     (kind IN ('document', 'presentation', 'workbook')),
    current_version  integer     NOT NULL DEFAULT 0,
    created_at       timestamptz NOT NULL,
    updated_at       timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_artifacts_user
    ON artifacts (user_id, conversation_id, updated_at DESC);

CREATE TABLE IF NOT EXISTS artifact_versions (
    artifact_id      text        NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,
    version          integer     NOT NULL,
    job_id           text        NOT NULL DEFAULT '',
    parent_version   integer,
    operation        text        NOT NULL DEFAULT 'create'
                     CONSTRAINT artifact_versions_operation CHECK
                     (operation IN ('create', 'edit', 'convert')),
    instruction      text        NOT NULL DEFAULT '',
    status           text        NOT NULL DEFAULT 'queued'
                     CONSTRAINT artifact_versions_status CHECK
                     (status IN ('queued', 'running', 'completed', 'completed_with_warnings', 'failed', 'cancelled')),
    formats          jsonb       NOT NULL DEFAULT '[]'::jsonb,
    files            jsonb       NOT NULL DEFAULT '[]'::jsonb,
    spec_version     integer     NOT NULL DEFAULT 1,
    template_id      text        NOT NULL DEFAULT 'generic',
    template_version text        NOT NULL DEFAULT '',
    renderer_version text        NOT NULL DEFAULT '',
    warnings         jsonb       NOT NULL DEFAULT '[]'::jsonb,
    validation       jsonb       NOT NULL DEFAULT '{}'::jsonb,
    assumptions      jsonb       NOT NULL DEFAULT '[]'::jsonb,
    preview_kind     text        NOT NULL DEFAULT 'none',
    preview_pages    integer     NOT NULL DEFAULT 0,
    created_at       timestamptz NOT NULL,
    completed_at     timestamptz,
    PRIMARY KEY (artifact_id, version)
);

CREATE TABLE IF NOT EXISTS artifact_jobs (
    id                text        PRIMARY KEY,
    user_id           integer     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    conversation_id   text        NOT NULL DEFAULT '',
    artifact_id       text        NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,
    version           integer     NOT NULL,
    idempotency_key   text        NOT NULL UNIQUE,
    generation_id     text        NOT NULL DEFAULT '',
    operation         text        NOT NULL DEFAULT 'create'
                      CONSTRAINT artifact_jobs_operation CHECK
                      (operation IN ('create', 'edit', 'convert')),
    requested_formats jsonb       NOT NULL DEFAULT '[]'::jsonb,
    selected_formats  jsonb       NOT NULL DEFAULT '[]'::jsonb,
    format_reason     text        NOT NULL DEFAULT '',
    effort            text        NOT NULL DEFAULT 'fast',
    mode              text        NOT NULL DEFAULT 'assistant',
    template_id       text        NOT NULL DEFAULT 'generic',
    instruction       text        NOT NULL DEFAULT '',
    status            text        NOT NULL DEFAULT 'queued'
                      CONSTRAINT artifact_jobs_status CHECK
                      (status IN ('queued', 'running', 'completed', 'completed_with_warnings', 'failed', 'cancelled')),
    stage             text        NOT NULL DEFAULT 'intent',
    progress          jsonb       NOT NULL DEFAULT '{}'::jsonb,
    attempt           integer     NOT NULL DEFAULT 0,
    input_hash        text        NOT NULL DEFAULT '',
    failure_category  text        NOT NULL DEFAULT '',
    error             text        NOT NULL DEFAULT '',
    diagnostic_ref    text        NOT NULL DEFAULT '',
    lease_owner       text        NOT NULL DEFAULT '',
    lease_expires_at  timestamptz,
    created_at        timestamptz NOT NULL,
    started_at        timestamptz,
    heartbeat_at      timestamptz,
    updated_at        timestamptz NOT NULL,
    completed_at      timestamptz
);
CREATE INDEX IF NOT EXISTS idx_artifact_jobs_user
    ON artifact_jobs (user_id, conversation_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_artifact_jobs_open
    ON artifact_jobs (status, lease_expires_at) WHERE status IN ('queued', 'running');
-- The FKs the cascade walks and the join the API makes (job -> version by
-- job_id), indexed as V29 indexes every FK it cascades through: a user
-- deletion is users -> artifacts -> artifact_jobs, and without these each
-- artifact costs a sequential scan of artifact_jobs.
CREATE INDEX IF NOT EXISTS idx_artifact_jobs_artifact
    ON artifact_jobs (artifact_id, version);
CREATE INDEX IF NOT EXISTS idx_artifact_versions_job
    ON artifact_versions (job_id);
"""


_MIGRATION_V32 = """
-- V32 (2026-09-12): evaluator correlation and reproducible trace envelopes.
-- V30 is already shipped, so these additions are append-only.
ALTER TABLE query_traces
    ADD COLUMN IF NOT EXISTS request_id text NOT NULL DEFAULT '';
ALTER TABLE query_traces
    ADD COLUMN IF NOT EXISTS test_case_id text;
ALTER TABLE query_traces
    ADD COLUMN IF NOT EXISTS versions jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE UNIQUE INDEX IF NOT EXISTS idx_query_traces_request
    ON query_traces (request_id) WHERE request_id <> '';
CREATE INDEX IF NOT EXISTS idx_query_traces_test_case
    ON query_traces (test_case_id, started_at DESC) WHERE test_case_id IS NOT NULL;

ALTER TABLE query_trace_events
    ADD COLUMN IF NOT EXISTS started_at timestamptz;
ALTER TABLE query_trace_events
    ADD COLUMN IF NOT EXISTS completed_at timestamptz;
ALTER TABLE query_trace_events
    ADD COLUMN IF NOT EXISTS component_version text NOT NULL DEFAULT '';

-- Existing V30 point events happened at created_at. Preserve that truth
-- rather than fabricating elapsed spans during migration.
UPDATE query_trace_events
   SET started_at = COALESCE(started_at, created_at),
       completed_at = COALESCE(completed_at, created_at)
 WHERE started_at IS NULL OR completed_at IS NULL;
ALTER TABLE query_trace_events ALTER COLUMN started_at SET NOT NULL;
ALTER TABLE query_trace_events ALTER COLUMN completed_at SET NOT NULL;
"""


_MIGRATION_V33 = """
-- V33 (2026-09-12): availability programme, strict one-model mode
-- (docs/availability/CONTRACT.md §8.3). A chat request the main model cannot
-- take right now — its breaker is OPEN, or the controller reports it
-- STARTING / WEDGED / RECOVERING / DOWN — is neither failed nor answered by
-- another model: the row goes `queued`, the person reads one truthful line,
-- and the SAME generation resumes when the model is READY. A row a process
-- parked (the wait outran LLM_QUEUE_MAX_WAIT_S) or lost stays `queued` until
-- the resume sweep (app/continuity.py) or the browser's re-attach picks it
-- up. Same shape as V14's `web_crawls_status` widening: drop and re-add the
-- CHECK, and let the open-rows index see the new state.
ALTER TABLE chat_requests DROP CONSTRAINT IF EXISTS chat_requests_status;
ALTER TABLE chat_requests ADD CONSTRAINT chat_requests_status CHECK
    (status IN ('accepted', 'running', 'queued', 'completed', 'failed', 'cancelled', 'interrupted'));
DROP INDEX IF EXISTS idx_chat_requests_open;
CREATE INDEX IF NOT EXISTS idx_chat_requests_open
    ON chat_requests (status) WHERE status IN ('accepted', 'running', 'queued', 'interrupted');
"""


_MIGRATION_V34 = """
-- V34 (2026-09-12): the developer platform — API projects, service accounts,
-- keys, responses, idempotency claims, the usage ledgers, webhooks, the
-- public-model overrides and the platform secret store
-- (docs/developer-platform/SCHEMA-V34.md, CONTRACT-3 §5, §12-§15).
--
-- TENANCY IS EXPLICIT, and that is the point of the shape below. Every row a
-- caller can address by id carries `workspace_id` NEXT TO the foreign key it
-- could have been derived from. The 2026-09-12 audit found that workspace
-- scoping in this codebase is reconstructed by join at read time, which is
-- fine for a page that forgets to do it (it shows nothing) and fatal for a
-- key resolver that forgets to do it (it authorises the wrong tenant). A
-- stored column lets every accessor put the tenant in the WHERE clause, so
-- the check can only be written wrongly, never left out. The ledgers
-- (`api_usage_minute`, `api_usage_daily`), the idempotency claims and the
-- deliveries hang off `project_id` instead: they are never addressed by a
-- caller-supplied id, they are read only through a project the resolver has
-- already proved, and their primary keys are what make the atomic
-- counter upsert possible. `platform_secrets` is deployment-wide and has no
-- tenant at all. `public_models` USED to be deployment-wide too, and the
-- 2026-09-13 review showed why that was wrong: the console's model switch is
-- held by a super admin of ONE workspace, and flipping it wrote a row every
-- workspace's `/v1/models` read — one tenant's administrator could switch a
-- model off for every other customer. It is keyed by workspace now.
--
-- EVERY FOREIGN KEY A CASCADE WALKS GETS AN INDEX. V29 and V30 forgot it and
-- V31 wrote it down as the rule: deleting a workspace here walks workspaces
-- -> api_projects -> api_service_accounts / api_keys / api_responses ->
-- api_idempotency, and without these indexes each parent row costs a
-- sequential scan of every child table. The rule covers ON DELETE SET NULL
-- as well as ON DELETE CASCADE, because the nulling UPDATE has to find the
-- child rows by exactly the same scan — deleting one departing colleague's
-- user row rewrites `created_by` across every project, key, service account,
-- webhook endpoint and model override in the deployment.
--
-- This paragraph stated the rule from the day it was written and the DDL
-- below broke it in five places; the independent verifier of 2026-09-12 found
-- them by asking PostgreSQL rather than by reading the list
-- (`pg_constraint contype = 'f'` joined to `pg_index` on `indkey[0]`), which
-- is now how `test_api_platform_db.py` asks too. The five that were missing:
-- `api_webhook_deliveries.project_id` and `api_webhook_endpoints.workspace_id`
-- (both CASCADE), and `api_service_accounts.created_by`,
-- `api_webhook_endpoints.created_by` and `public_models.updated_by` (SET
-- NULL). A hardcoded list of index names cannot notice a sixth.
--
-- NO COLUMN HOLDS A PLAINTEXT KEY. `key_hash` is HMAC-SHA256 under a pepper
-- (CONTRACT-3 §5) and `last_four` exists only so a person can recognise which
-- key a row is about. The one piece of generated text stored anywhere is
-- `api_responses.output_text`, which exists so a BACKGROUND response can be
-- collected after the connection that asked for it has gone, and which
-- `prune_api_platform` clears on the project's retention day.
--
-- A JSONB COLUMN AN AUTHORIZATION DECISION IS READ FROM DECLARES ITS SHAPE.
-- `allowed_models`, `allowed_origins`, `ip_allowlist`, `scopes` and `events`
-- are allow-lists: each of them is the thing that says "no" on a request
-- path, and bare `jsonb` accepts a string, a number or an object just as
-- happily as the array the reader expects. The 2026-09-12 verifier measured
-- exactly that — `update_api_project(pid, ws, allowed_models='techsara-35b')`
-- stored `{"raw": "techsara-35b"}` and `create_api_project(...,
-- allowed_models='abc')` stored `["a","b","c"]` — and a reader written as
-- `model in row["allowed_models"]` answers both of those wrongly, in the
-- permissive direction for the second. The accessors refuse a non-list before
-- they ever get here; the CHECK is what makes the rule true for every writer
-- that reaches this table, psql included. The object-shaped columns
-- (`metadata`, `payload`) get the same declaration, because a list stored in
-- `metadata` is a KeyError in whichever console page reads it next.
--
-- A LIMIT IS A NUMBER THAT CANNOT BE NEGATIVE. Same review: a
-- `retention_days` of -5 was accepted, and every response created afterwards
-- was born already expired — `create_api_response` computes `now() +
-- make_interval(days => p.retention_days)` — so a background response
-- vanished on the next `prune_api_platform` sweep before the caller that
-- started it could ever fetch it. Zero is legal for all of these and means
-- frozen (no requests, no tokens, nothing retained); below zero is not a
-- tighter limit, it is a corrupted one. The nullable ceilings are the
-- exception only in that NULL is legal there, and NULL means "inherit". ZERO
-- MEANS ZERO EVERYWHERE, the ceilings included: an earlier draft of this
-- paragraph made `max_input_tokens` and `max_output_tokens` refuse 0 as
-- "configuration that looks like refusal", and the 2026-09-13 review found the
-- resolver reading that same argument the other way round for `rpm` — a stored
-- 0 silently became the 60 default and let 60 requests through a project an
-- operator had frozen. One rule, stated once, for every limit column: NULL
-- inherits, 0 allows nothing, below 0 is refused by the schema.
--
-- A LEDGER COUNTER CANNOT GO BELOW ZERO EITHER (2026-09-13). The columns the
-- quota is actually decided from — `api_usage_minute.*` and
-- `api_usage_daily.*` — had no CHECK, and `bump_usage_daily(requests=-100,
-- input_tokens=-1_000_000)` was measured leaving the day at -90 requests: a
-- quota refund one careless caller away, guarded only by a `max(0, ...)` in
-- `quotas.py`. The accessors refuse a negative increment (a CHECK on a running
-- total cannot see a partial refund that leaves it positive); the CHECK is the
-- backstop for every writer that is not those accessors.
--
-- AN ALLOW-LIST IS BOUNDED (2026-09-13). 5,000 entries of 1,000 characters
-- were accepted into `allowed_models`, and the resolver reads the whole
-- project row on every `/v1` request. 256 entries is far beyond any real
-- model, origin, network or scope list; `_json_array` also caps each entry at
-- 512 characters, which a CHECK cannot express cheaply. The CASE is not
-- decoration: PostgreSQL does not promise to evaluate `a AND b` left to right,
-- and `jsonb_array_length` RAISES on a non-array, so the plain conjunction
-- could answer a scalar with an error instead of a constraint violation.
--
-- All of these rule families were added to V34 IN PLACE on 2026-09-13 rather than as
-- a V35. V34 exists in no commit on `main` and in no database outside this
-- branch's test runs, so amending it is the honest record rather than a
-- rewrite of history. The day after it ships, the same change costs an ALTER
-- TABLE ... ADD CONSTRAINT with a validation scan of every tenant's rows.
--
-- Statement timeout is 15 s per connection and the whole migration runs in
-- one transaction, but every index below is on a table created empty in the
-- same statement batch, so there is nothing for it to time out on.
CREATE TABLE IF NOT EXISTS api_projects (
    id                text        PRIMARY KEY,
    workspace_id      text        NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name              text        NOT NULL,
    environment       text        NOT NULL
                      CONSTRAINT api_projects_environment CHECK
                      (environment IN ('test', 'live')),
    status            text        NOT NULL DEFAULT 'active'
                      CONSTRAINT api_projects_status CHECK
                      (status IN ('active', 'disabled')),
    allowed_models    jsonb       NOT NULL DEFAULT '[]'::jsonb
                      CONSTRAINT api_projects_allowed_models CHECK
                      (CASE WHEN jsonb_typeof(allowed_models) = 'array' THEN jsonb_array_length(allowed_models) <= 256 ELSE false END),
    allowed_origins   jsonb       NOT NULL DEFAULT '[]'::jsonb
                      CONSTRAINT api_projects_allowed_origins CHECK
                      (CASE WHEN jsonb_typeof(allowed_origins) = 'array' THEN jsonb_array_length(allowed_origins) <= 256 ELSE false END),
    ip_allowlist      jsonb       NOT NULL DEFAULT '[]'::jsonb
                      CONSTRAINT api_projects_ip_allowlist CHECK
                      (CASE WHEN jsonb_typeof(ip_allowlist) = 'array' THEN jsonb_array_length(ip_allowlist) <= 256 ELSE false END),
    rpm               integer     NOT NULL DEFAULT 60
                      CONSTRAINT api_projects_rpm CHECK (rpm >= 0),
    input_tpm         bigint      NOT NULL DEFAULT 200000
                      CONSTRAINT api_projects_input_tpm CHECK (input_tpm >= 0),
    output_tpm        bigint      NOT NULL DEFAULT 60000
                      CONSTRAINT api_projects_output_tpm CHECK (output_tpm >= 0),
    max_concurrency   integer     NOT NULL DEFAULT 4
                      CONSTRAINT api_projects_max_concurrency CHECK (max_concurrency >= 0),
    daily_token_quota bigint      NOT NULL DEFAULT 2000000
                      CONSTRAINT api_projects_daily_token_quota CHECK (daily_token_quota >= 0),
    max_input_tokens  integer
                      CONSTRAINT api_projects_max_input_tokens CHECK
                      (max_input_tokens IS NULL OR max_input_tokens >= 0),
    max_output_tokens integer
                      CONSTRAINT api_projects_max_output_tokens CHECK
                      (max_output_tokens IS NULL OR max_output_tokens >= 0),
    retention_days    integer     NOT NULL DEFAULT 30
                      CONSTRAINT api_projects_retention_days CHECK (retention_days >= 0),
    metadata          jsonb       NOT NULL DEFAULT '{}'::jsonb
                      CONSTRAINT api_projects_metadata CHECK
                      (jsonb_typeof(metadata) = 'object'),
    created_by        integer     REFERENCES users(id) ON DELETE SET NULL,
    created_at        timestamptz NOT NULL DEFAULT now(),
    disabled_at       timestamptz,
    -- THE CONSOLE PLAYGROUND'S ALLOWANCE ROW (2026-09-13). The playground is
    -- metered as a per-workspace project that no person created and no
    -- person may edit, list or key. It used to be recognised by an id prefix
    -- and a `metadata.system` mark, and it had to take a NAME under the
    -- per-workspace unique index below — so an admin who created projects
    -- called "Console playground" and "Console playground <suffix>" (the id
    -- is derivable from the workspace id /overview returns) made every
    -- playground run in the workspace a 500. A column no accessor lets a
    -- request body write is the mark; the name index ignores marked rows,
    -- and a second index allows exactly one marked row per workspace, so a
    -- concurrent first run races on that index instead of on a name.
    is_playground     boolean     NOT NULL DEFAULT false
);
CREATE INDEX IF NOT EXISTS idx_api_projects_workspace
    ON api_projects (workspace_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_api_projects_created_by
    ON api_projects (created_by);
-- One project name per workspace, folded. The console offers a project by
-- name and the database is the only place that can make that unambiguous
-- while two admins are creating one at the same moment. The playground row is
-- outside it: it is never offered by name, and a customer's name must not be
-- able to block it (see `is_playground`).
CREATE UNIQUE INDEX IF NOT EXISTS idx_api_projects_name
    ON api_projects (workspace_id, lower(name)) WHERE NOT is_playground;
CREATE UNIQUE INDEX IF NOT EXISTS idx_api_projects_one_playground
    ON api_projects (workspace_id) WHERE is_playground;

CREATE TABLE IF NOT EXISTS api_service_accounts (
    id             text        PRIMARY KEY,
    project_id     text        NOT NULL REFERENCES api_projects(id) ON DELETE CASCADE,
    workspace_id   text        NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    name           text        NOT NULL,
    description    text        NOT NULL DEFAULT '',
    status         text        NOT NULL DEFAULT 'active'
                   CONSTRAINT api_service_accounts_status CHECK
                   (status IN ('active', 'disabled')),
    scopes         jsonb       NOT NULL DEFAULT '[]'::jsonb
                   CONSTRAINT api_service_accounts_scopes CHECK
                   (CASE WHEN jsonb_typeof(scopes) = 'array' THEN jsonb_array_length(scopes) <= 256 ELSE false END),
    allowed_models jsonb       NOT NULL DEFAULT '[]'::jsonb
                   CONSTRAINT api_service_accounts_allowed_models CHECK
                   (CASE WHEN jsonb_typeof(allowed_models) = 'array' THEN jsonb_array_length(allowed_models) <= 256 ELSE false END),
    created_by     integer     REFERENCES users(id) ON DELETE SET NULL,
    created_at     timestamptz NOT NULL DEFAULT now(),
    last_used_at   timestamptz,
    disabled_at    timestamptz
);
CREATE INDEX IF NOT EXISTS idx_api_service_accounts_project
    ON api_service_accounts (project_id);
CREATE INDEX IF NOT EXISTS idx_api_service_accounts_workspace
    ON api_service_accounts (workspace_id);
CREATE INDEX IF NOT EXISTS idx_api_service_accounts_created_by
    ON api_service_accounts (created_by);

CREATE TABLE IF NOT EXISTS api_keys (
    id                  text        PRIMARY KEY,
    public_id           text        NOT NULL UNIQUE,
    key_hash            text        NOT NULL,
    last_four           text        NOT NULL,
    project_id          text        NOT NULL REFERENCES api_projects(id) ON DELETE CASCADE,
    service_account_id  text        REFERENCES api_service_accounts(id) ON DELETE CASCADE,
    workspace_id        text        NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    environment         text        NOT NULL
                        CONSTRAINT api_keys_environment CHECK
                        (environment IN ('test', 'live')),
    name                text        NOT NULL,
    scopes              jsonb       NOT NULL DEFAULT '[]'::jsonb
                        CONSTRAINT api_keys_scopes CHECK
                        (CASE WHEN jsonb_typeof(scopes) = 'array' THEN jsonb_array_length(scopes) <= 256 ELSE false END),
    allowed_models      jsonb       NOT NULL DEFAULT '[]'::jsonb
                        CONSTRAINT api_keys_allowed_models CHECK
                        (CASE WHEN jsonb_typeof(allowed_models) = 'array' THEN jsonb_array_length(allowed_models) <= 256 ELSE false END),
    -- NULL means "inherit the project's limit", which is not the same as 0:
    -- 0 is a key that may make no request at all, which is a legitimate way
    -- to park an integration without revoking its credential.
    rpm                 integer
                        CONSTRAINT api_keys_rpm CHECK (rpm IS NULL OR rpm >= 0),
    max_concurrency     integer
                        CONSTRAINT api_keys_max_concurrency CHECK
                        (max_concurrency IS NULL OR max_concurrency >= 0),
    status              text        NOT NULL DEFAULT 'active'
                        CONSTRAINT api_keys_status CHECK
                        (status IN ('active', 'revoked')),
    expires_at          timestamptz,
    created_by          integer     REFERENCES users(id) ON DELETE SET NULL,
    created_at          timestamptz NOT NULL DEFAULT now(),
    last_used_at        timestamptz,
    last_used_ip        text,
    revoked_at          timestamptz,
    revoked_by          integer     REFERENCES users(id) ON DELETE SET NULL,
    -- ROTATION, and which row each column is about (settled 2026-09-13).
    -- `rotated_from` sits on the NEW key and names the public id of the key it
    -- replaced — history, read by the console, never by an authorization
    -- decision. `rotation_expires_at` sits on the OLD key and is the moment
    -- THAT key stops working; the resolver refuses a key whose own deadline
    -- has passed and `expire_rotated_keys` revokes it. An earlier draft put
    -- the deadline on the successor and had the sweep join successor to
    -- predecessor by `rotated_from = public_id` across the whole table, which
    -- let a key minted in workspace B name workspace A's public id and get A's
    -- live key revoked; it also disagreed with the resolver, so no overlap was
    -- ever enforced. A column that is about its own row cannot reach another
    -- tenant's, and `create_api_key` refuses a `rotated_from` that is not a
    -- key of the same project.
    rotated_from        text,
    rotation_expires_at timestamptz
);
CREATE INDEX IF NOT EXISTS idx_api_keys_project
    ON api_keys (project_id);
CREATE INDEX IF NOT EXISTS idx_api_keys_workspace
    ON api_keys (workspace_id);
CREATE INDEX IF NOT EXISTS idx_api_keys_service_account
    ON api_keys (service_account_id);
CREATE INDEX IF NOT EXISTS idx_api_keys_created_by
    ON api_keys (created_by);
CREATE INDEX IF NOT EXISTS idx_api_keys_revoked_by
    ON api_keys (revoked_by);
-- The resolver's index: every /v1 request looks a key up by public_id, and
-- the overwhelming majority of rows it will ever read are active ones.
CREATE INDEX IF NOT EXISTS idx_api_keys_active
    ON api_keys (public_id) WHERE status = 'active';
-- The rotation sweep's index: only live keys that carry a deadline, which is
-- a handful of rows in a table that grows with every key ever issued.
CREATE INDEX IF NOT EXISTS idx_api_keys_rotation_due
    ON api_keys (rotation_expires_at)
    WHERE status = 'active' AND rotation_expires_at IS NOT NULL;

CREATE TABLE IF NOT EXISTS api_responses (
    id                   text        PRIMARY KEY,
    project_id           text        NOT NULL REFERENCES api_projects(id) ON DELETE CASCADE,
    key_id               text        REFERENCES api_keys(id) ON DELETE SET NULL,
    workspace_id         text        NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    model                text        NOT NULL,
    status               text        NOT NULL DEFAULT 'queued'
                         CONSTRAINT api_responses_status CHECK
                         (status IN ('queued', 'in_progress', 'completed', 'failed', 'cancelled')),
    background           boolean     NOT NULL DEFAULT false,
    streamed             boolean     NOT NULL DEFAULT false,
    request_id           text        NOT NULL,
    fingerprint          text        NOT NULL DEFAULT '',
    instructions_present boolean     NOT NULL DEFAULT false,
    -- NULL means NOT MEASURED, never zero: llm.get_usage() returns None when
    -- the engine reported no counts, and a zero there is both a lie and an
    -- under-charge (CONTRACT-3 §9). Below zero is neither: these two are what
    -- the daily ledger is bumped from, so a negative count is a quota refund
    -- nobody authorised.
    input_tokens         integer
                         CONSTRAINT api_responses_input_tokens CHECK
                         (input_tokens IS NULL OR input_tokens >= 0),
    output_tokens        integer
                         CONSTRAINT api_responses_output_tokens CHECK
                         (output_tokens IS NULL OR output_tokens >= 0),
    ttft_ms              integer,
    duration_ms          integer,
    error_code           text,
    error_message        text,
    output_text          text,
    cancel_requested     boolean     NOT NULL DEFAULT false,
    metadata             jsonb       NOT NULL DEFAULT '{}'::jsonb
                         CONSTRAINT api_responses_metadata CHECK
                         (jsonb_typeof(metadata) = 'object'),
    created_at           timestamptz NOT NULL DEFAULT now(),
    started_at           timestamptz,
    completed_at         timestamptz,
    expires_at           timestamptz
);
CREATE INDEX IF NOT EXISTS idx_api_responses_project
    ON api_responses (project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_api_responses_workspace
    ON api_responses (workspace_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_api_responses_key
    ON api_responses (key_id);
-- The two sweeps: what is still running (a restart has to finish or fail it)
-- and what retention is due to remove.
CREATE INDEX IF NOT EXISTS idx_api_responses_open
    ON api_responses (status, created_at) WHERE status IN ('queued', 'in_progress');
CREATE INDEX IF NOT EXISTS idx_api_responses_expires
    ON api_responses (expires_at) WHERE expires_at IS NOT NULL;

CREATE TABLE IF NOT EXISTS api_idempotency (
    id          bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id  text        NOT NULL REFERENCES api_projects(id) ON DELETE CASCADE,
    endpoint    text        NOT NULL,
    idem_key    text        NOT NULL,
    fingerprint text        NOT NULL,
    response_id text        REFERENCES api_responses(id) ON DELETE CASCADE,
    state       text        NOT NULL DEFAULT 'in_flight'
                CONSTRAINT api_idempotency_state CHECK
                (state IN ('in_flight', 'completed')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    expires_at  timestamptz NOT NULL
);
-- The claim. `INSERT ... ON CONFLICT DO NOTHING RETURNING id` against this
-- unique index is the race-free primitive the whole idempotency contract
-- rests on (CONTRACT-3 §13): zero rows back means somebody else claimed it,
-- with no window between a SELECT and an INSERT for a second request to
-- squeeze the model call through.
CREATE UNIQUE INDEX IF NOT EXISTS idx_api_idempotency_claim
    ON api_idempotency (project_id, endpoint, idem_key);
CREATE INDEX IF NOT EXISTS idx_api_idempotency_expires
    ON api_idempotency (expires_at);
CREATE INDEX IF NOT EXISTS idx_api_idempotency_response
    ON api_idempotency (response_id);

CREATE TABLE IF NOT EXISTS api_usage_minute (
    project_id    text        NOT NULL REFERENCES api_projects(id) ON DELETE CASCADE,
    key_id        text        NOT NULL,
    bucket        timestamptz NOT NULL,
    requests      integer     NOT NULL DEFAULT 0
                  CONSTRAINT api_usage_minute_requests CHECK (requests >= 0),
    input_tokens  bigint      NOT NULL DEFAULT 0
                  CONSTRAINT api_usage_minute_input_tokens CHECK (input_tokens >= 0),
    output_tokens bigint      NOT NULL DEFAULT 0
                  CONSTRAINT api_usage_minute_output_tokens CHECK (output_tokens >= 0),
    PRIMARY KEY (project_id, key_id, bucket)
);
-- Pruning reads by bucket alone; the primary key cannot serve that.
CREATE INDEX IF NOT EXISTS idx_api_usage_minute_bucket
    ON api_usage_minute (bucket);

CREATE TABLE IF NOT EXISTS api_usage_daily (
    project_id    text        NOT NULL REFERENCES api_projects(id) ON DELETE CASCADE,
    day           date        NOT NULL,
    requests      integer     NOT NULL DEFAULT 0
                  CONSTRAINT api_usage_daily_requests CHECK (requests >= 0),
    input_tokens  bigint      NOT NULL DEFAULT 0
                  CONSTRAINT api_usage_daily_input_tokens CHECK (input_tokens >= 0),
    output_tokens bigint      NOT NULL DEFAULT 0
                  CONSTRAINT api_usage_daily_output_tokens CHECK (output_tokens >= 0),
    errors        integer     NOT NULL DEFAULT 0
                  CONSTRAINT api_usage_daily_errors CHECK (errors >= 0),
    rate_limited  integer     NOT NULL DEFAULT 0
                  CONSTRAINT api_usage_daily_rate_limited CHECK (rate_limited >= 0),
    PRIMARY KEY (project_id, day)
);
CREATE INDEX IF NOT EXISTS idx_api_usage_daily_day
    ON api_usage_daily (day);

CREATE TABLE IF NOT EXISTS api_webhook_endpoints (
    id                         text        PRIMARY KEY,
    project_id                 text        NOT NULL REFERENCES api_projects(id) ON DELETE CASCADE,
    workspace_id               text        NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    url                        text        NOT NULL,
    events                     jsonb       NOT NULL DEFAULT '[]'::jsonb
                               CONSTRAINT api_webhook_endpoints_events CHECK
                               (CASE WHEN jsonb_typeof(events) = 'array' THEN jsonb_array_length(events) <= 256 ELSE false END),
    status                     text        NOT NULL DEFAULT 'active'
                               CONSTRAINT api_webhook_endpoints_status CHECK
                               (status IN ('active', 'disabled')),
    -- The signing secret is stored, not hashed, because the SERVER computes
    -- the signature on every delivery and therefore needs the value back. It
    -- is shown once in the console and returned by no API.
    secret                     text        NOT NULL,
    previous_secret            text,
    previous_secret_expires_at timestamptz,
    include_output             boolean     NOT NULL DEFAULT false,
    created_by                 integer     REFERENCES users(id) ON DELETE SET NULL,
    created_at                 timestamptz NOT NULL DEFAULT now(),
    last_delivery_at           timestamptz,
    last_delivery_status       text,
    consecutive_failures       integer     NOT NULL DEFAULT 0
                               CONSTRAINT api_webhook_endpoints_consecutive_failures CHECK
                               (consecutive_failures >= 0),
    disabled_at                timestamptz
);
CREATE INDEX IF NOT EXISTS idx_api_webhook_endpoints_project
    ON api_webhook_endpoints (project_id);
-- `workspace_id` here is not only the cascade path from `workspaces`: it is
-- the tenancy predicate of `list_webhook_endpoints`, `update_webhook_endpoint`
-- and `delete_webhook_endpoint`, so every console read of this table uses it.
CREATE INDEX IF NOT EXISTS idx_api_webhook_endpoints_workspace
    ON api_webhook_endpoints (workspace_id);
CREATE INDEX IF NOT EXISTS idx_api_webhook_endpoints_created_by
    ON api_webhook_endpoints (created_by);

CREATE TABLE IF NOT EXISTS api_webhook_deliveries (
    id              text        PRIMARY KEY,
    event_id        text        NOT NULL,
    endpoint_id     text        NOT NULL REFERENCES api_webhook_endpoints(id) ON DELETE CASCADE,
    project_id      text        NOT NULL REFERENCES api_projects(id) ON DELETE CASCADE,
    event_type      text        NOT NULL,
    response_id     text,
    payload         jsonb       NOT NULL DEFAULT '{}'::jsonb
                    CONSTRAINT api_webhook_deliveries_payload CHECK
                    (jsonb_typeof(payload) = 'object'),
    status          text        NOT NULL DEFAULT 'pending'
                    CONSTRAINT api_webhook_deliveries_status CHECK
                    (status IN ('pending', 'delivered', 'failed', 'dropped')),
    attempt         integer     NOT NULL DEFAULT 0
                    CONSTRAINT api_webhook_deliveries_attempt CHECK (attempt >= 0),
    -- At least one: `due_webhook_deliveries` selects on `attempt <
    -- max_attempts`, so a delivery queued with 0 is never due and never
    -- fails — it is silently dropped, which is the one outcome a delivery
    -- history exists to make impossible (CONTRACT-3 §14).
    max_attempts    integer     NOT NULL DEFAULT 6
                    CONSTRAINT api_webhook_deliveries_max_attempts CHECK (max_attempts >= 1),
    http_status     integer,
    error           text,
    next_attempt_at timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now(),
    delivered_at    timestamptz
);
CREATE INDEX IF NOT EXISTS idx_api_webhook_deliveries_endpoint
    ON api_webhook_deliveries (endpoint_id, created_at DESC);
-- Deleting a project cascades to its deliveries, and this is the only index
-- that leads with `project_id` — the endpoint index above cannot serve it.
CREATE INDEX IF NOT EXISTS idx_api_webhook_deliveries_project
    ON api_webhook_deliveries (project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_api_webhook_deliveries_due
    ON api_webhook_deliveries (next_attempt_at) WHERE status = 'pending';
-- `event_id` is what makes a consumer able to be idempotent, so the same
-- event must never be queued to the same endpoint twice — a retry that lost
-- its acknowledgement enqueues nothing rather than a duplicate.
CREATE UNIQUE INDEX IF NOT EXISTS idx_api_webhook_deliveries_event
    ON api_webhook_deliveries (endpoint_id, event_id);

-- The database may only NARROW the code-level model registry (CONTRACT-3
-- §15). A row here can disable a model the code declares; a row for an id the
-- code does not declare is ignored by `public_model_overrides`, so no amount
-- of database access can publish an internal model.
--
-- PER WORKSPACE (2026-09-13). `id` alone was the primary key, so the one row
-- for `techsara-35b` was every workspace's row, and a super admin whose
-- authority is one workspace's could disable the model for all of them. The
-- workspace leads the primary key, which is also the index the ON DELETE
-- CASCADE from `workspaces` walks. `id` keeps its name because it is the
-- public model id the registry declares, not a surrogate key.
CREATE TABLE IF NOT EXISTS public_models (
    workspace_id text        NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    id           text        NOT NULL,
    enabled      boolean     NOT NULL DEFAULT true,
    updated_by   integer     REFERENCES users(id) ON DELETE SET NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE INDEX IF NOT EXISTS idx_public_models_updated_by
    ON public_models (updated_by);

-- Holds the generated API-key pepper when API_KEY_PEPPER is not configured,
-- so a fresh install works without a deploy-time secret. This is documented
-- as the WEAKER of the two options: the pepper then lives in the same
-- database as the digests it protects, which buys nothing against an
-- attacker who has the whole database (CONTRACT-3 §5, STANDARDS.md).
CREATE TABLE IF NOT EXISTS platform_secrets (
    name       text        PRIMARY KEY,
    value      text        NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
"""


_MIGRATIONS: tuple = (
    (1, _MIGRATION_V1),
    (2, _MIGRATION_V2),
    (3, _MIGRATION_V3),
    (4, _MIGRATION_V4),
    (5, _MIGRATION_V5),
    (6, _MIGRATION_V6),
    (7, _MIGRATION_V7),
    (8, _MIGRATION_V8),
    (9, _MIGRATION_V9),
    (10, _MIGRATION_V10),
    (11, _MIGRATION_V11),
    (12, _MIGRATION_V12),
    (13, _MIGRATION_V13),
    (14, _MIGRATION_V14),
    (15, _MIGRATION_V15),
    (16, _MIGRATION_V16),
    (17, _MIGRATION_V17),
    (18, _MIGRATION_V18),
    (19, _MIGRATION_V19),
    (20, _MIGRATION_V20),
    (21, _MIGRATION_V21),
    (22, _MIGRATION_V22),
    (23, _MIGRATION_V23),
    (24, _MIGRATION_V24),
    (25, _MIGRATION_V25),
    (26, _MIGRATION_V26),
    (27, _MIGRATION_V27),
    (28, _MIGRATION_V28),
    (29, _MIGRATION_V29),
    (30, _MIGRATION_V30),
    (31, _MIGRATION_V31),
    (32, _MIGRATION_V32),
    (33, _MIGRATION_V33),
    (34, _MIGRATION_V34),
)

#: The version `init_schema` brings a database up to. Exported so callers (and
#: tests) can assert "fully migrated" without hardcoding a number that has to be
#: edited every time a migration is appended — which is exactly how a schema
#: assertion stops being a check and becomes a chore.
LATEST_SCHEMA_VERSION: int = max(version for version, _ddl in _MIGRATIONS)

_MIGRATION_TABLE = """
CREATE TABLE IF NOT EXISTS schema_migrations (
    version    integer     PRIMARY KEY,
    applied_at timestamptz NOT NULL DEFAULT now()
);
"""

#: Any 64-bit constant; it only has to be stable and not collide with another
#: advisory lock in this database. Two orchestrators starting together take it
#: in turn instead of racing to CREATE the same index.
_MIGRATION_LOCK_KEY = 0x5346_4149_4442


# ---------------------------------------------------------------------------
# Connection pool
# ---------------------------------------------------------------------------

_pool: Optional[ConnectionPool] = None
_pool_lock = threading.Lock()
_pool_dsn: Optional[str] = None


def _server_options() -> str:
    """libpq `options`, applied to every connection the pool opens.

    - `timezone=UTC` is load-bearing, not hygiene: a `timestamptz` renders in
      the session time zone, and every timestamp this module returns is
      `datetime.isoformat()`. Any other zone would silently change the strings
      the frontend and the tests have always seen.
    - `statement_timeout` is the bound SQLite never had; an unbounded query
      used to hold a request open indefinitely.
    - `idle_in_transaction_session_timeout` stops a leaked transaction from
      pinning a pooled connection (and holding back vacuum) forever.
    """
    return (
        "-c timezone=UTC"
        f" -c statement_timeout={int(settings.app_db_statement_timeout_ms)}"
        " -c idle_in_transaction_session_timeout=60000"
    )


def dsn() -> str:
    """The configured DSN, or a loud failure.

    No localhost default on purpose: a silent fallback is how a deploy ends up
    writing history into a database nobody can find.
    """
    configured = (settings.app_database_url or "").strip()
    if not configured:
        raise RuntimeError(
            "APP_DATABASE_URL is not set — the app-state database is PostgreSQL "
            "since 2026-08-10. Example: "
            "postgresql://techsara:<password>@postgres:5432/techsara"
        )
    return configured


def pool() -> ConnectionPool:
    """The process-wide connection pool, opened on first use.

    Rebuilt when `settings.app_database_url` changes, which is what lets the
    test suite point each test at its own database.
    """
    global _pool, _pool_dsn
    wanted = dsn()
    if _pool is not None and _pool_dsn == wanted and not _pool.closed:
        return _pool
    with _pool_lock:
        if _pool is not None and _pool_dsn == wanted and not _pool.closed:
            return _pool
        if _pool is not None:
            _close_pool_locked()
        created = ConnectionPool(
            conninfo=wanted,
            min_size=max(0, int(settings.app_db_pool_min)),
            max_size=max(1, int(settings.app_db_pool_max)),
            timeout=float(settings.app_db_pool_timeout),
            # A pooled connection outlives the server it was opened against.
            # Without a liveness check the first request after a `docker
            # compose restart postgres` fails; with it, the pool quietly
            # replaces the dead connection.
            check=ConnectionPool.check_connection,
            kwargs={
                "row_factory": dict_row,
                "autocommit": False,
                "options": _server_options(),
            },
            name="app-state",
            open=False,
        )
        created.open(wait=True, timeout=float(settings.app_db_pool_timeout))
        _pool, _pool_dsn = created, wanted
        return _pool


def _close_pool_locked() -> None:
    global _pool, _pool_dsn
    if _pool is not None:
        try:
            _pool.close()
        except Exception:  # noqa: BLE001 — shutdown must not raise
            pass
    _pool, _pool_dsn = None, None


def close_pool() -> None:
    """Release every pooled connection (app shutdown, and between tests)."""
    with _pool_lock:
        _close_pool_locked()


@contextmanager
def connection() -> Iterator[psycopg.Connection]:
    """A pooled connection wrapped in one transaction.

    Commits on a clean exit, rolls back on an exception, and returns the
    connection to the pool either way — the direct replacement for the old
    `with closing(connect()) as con, con:` idiom, minus the 0.24 ms of schema
    replay that used to precede it.
    """
    with pool().connection() as con:
        yield con


T = TypeVar("T")


async def run_in_thread(fn: Callable[..., T], *args: Any, **kwargs: Any) -> T:
    """Await a blocking accessor from `async def` without stalling the loop.

    Every function in this module is synchronous by design: `history.py`'s
    routes are plain `def` and FastAPI already runs those in the threadpool,
    and making the module async would have coloured all 39 functions plus
    every test. The handful of genuinely async callers (`main.py`,
    `compaction.py`, the engines) use this instead — one `await` per call site
    rather than a rewrite, and the event loop stays free to pump the other
    in-flight SSE streams.
    """
    import anyio  # local: keeps this module importable without a running loop

    return await anyio.to_thread.run_sync(functools.partial(fn, *args, **kwargs))


# ---------------------------------------------------------------------------
# Schema application
# ---------------------------------------------------------------------------


def wait_for_database(timeout: Optional[float] = None) -> None:
    """Block until PostgreSQL accepts a connection, or give up after `timeout`.

    THIS EXISTS FOR REBOOTS. `depends_on: service_healthy` only orders
    `docker compose up`; when the Docker daemon brings containers back after a
    power cut it starts them all at once and honours no such ordering. Without
    this, the orchestrator raced PostgreSQL, failed its lifespan, exited, and
    was restarted by `restart: unless-stopped` — measured at 8 crash-restarts
    in one simulated power cut. It always recovered, but Docker's restart
    backoff grows with each failure, so on a real boot (five vLLM services
    competing for the same disk) recovery is delayed by exactly the time the
    machine is busiest.

    Waiting instead of dying keeps ONE container start, a readable log line
    while it waits, and recovery the moment the database is ready.

    It still gives up eventually: a DSN pointing at a database that will never
    exist is a deploy error, and it should be loud rather than a container that
    hangs "starting" forever. Exceeding the deadline raises, the process exits,
    and Docker restarts it — so even then it self-heals, just noisily.
    """
    import logging
    import time

    deadline = time.monotonic() + (
        float(settings.app_db_startup_timeout) if timeout is None else timeout
    )
    log = logging.getLogger(__name__)
    target = dsn().rsplit("@", 1)[-1]  # never log the password
    attempt = 0
    while True:
        attempt += 1
        try:
            with psycopg.connect(dsn(), connect_timeout=5) as con:
                con.execute("SELECT 1")
            if attempt > 1:
                log.warning(
                    "postgres at %s is up (after %d attempts)", target, attempt
                )
            return
        except psycopg.OperationalError as exc:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise RuntimeError(
                    f"postgres at {target} did not accept a connection within "
                    f"{settings.app_db_startup_timeout:.0f}s ({attempt} attempts). "
                    f"Last error: {exc}"
                ) from exc
            # Back off gently, capped, so a slow boot does not spin the CPU and
            # a fast one still gets going within a second.
            time.sleep(min(3.0, 0.25 * attempt, max(0.1, remaining)))
            if attempt in (1, 5) or attempt % 20 == 0:
                log.warning(
                    "waiting for postgres at %s (attempt %d, %.0fs left): %s",
                    target, attempt, remaining, str(exc).strip().splitlines()[0],
                )


def init_schema() -> None:
    """Apply any unapplied migrations. Idempotent; safe to call concurrently.

    Called once from the FastAPI lifespan so a broken migration fails the
    deploy rather than the first request that happens to touch the database.
    `pg_advisory_xact_lock` serialises two instances starting together, and
    releases automatically when the transaction ends — including on failure,
    where PostgreSQL's transactional DDL also rolls the partial schema back.
    """
    with connection() as con:
        with con.transaction():
            con.execute("SELECT pg_advisory_xact_lock(%s)", (_MIGRATION_LOCK_KEY,))
            con.execute(_MIGRATION_TABLE)
            applied = {
                int(row["version"])
                for row in con.execute("SELECT version FROM schema_migrations").fetchall()
            }
            for version, ddl in _MIGRATIONS:
                if version in applied:
                    continue
                con.execute(ddl)
                con.execute(
                    "INSERT INTO schema_migrations (version) VALUES (%s)", (version,)
                )


def schema_version() -> int:
    """Highest applied migration version, or 0 on an empty database.

    "Empty" includes a database with no schema AT ALL. Before the first
    `init_schema()` the `schema_migrations` table does not exist, and asking a
    never-migrated database for its version is a fair question whose answer is
    0 -- but the bare SELECT raised `UndefinedTable` instead, so the first call
    against a fresh database was an error rather than a zero. CI's
    fresh-install check hit exactly that, and `health.py` would have too on a
    database that had never started up.

    ONLY `UndefinedTable` is swallowed. A connection failure, a permission
    error or a wrong-database DSN still propagates, so this cannot quietly
    report 0 for a database it simply could not read.
    """
    try:
        with connection() as con:
            row = con.execute(
                "SELECT COALESCE(MAX(version), 0) AS v FROM schema_migrations"
            ).fetchone()
    except psycopg.errors.UndefinedTable:
        return 0
    return int(row["v"]) if row else 0


# ---------------------------------------------------------------------------
# Row helpers
# ---------------------------------------------------------------------------


def _now() -> datetime:
    return datetime.now(timezone.utc)


def utcnow() -> str:
    """ISO-8601 UTC, the string shape this app has always emitted."""
    return _now().isoformat()


def _iso(value: Any) -> Any:
    """`timestamptz` -> the same ISO-8601 string SQLite stored verbatim.

    The session runs in UTC (see `_server_options`), so this reproduces
    `datetime.now(timezone.utc).isoformat()` exactly, offset included.
    """
    return value.isoformat() if isinstance(value, datetime) else value


def _row(row: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """Row -> plain JSON-friendly dict (timestamps become ISO strings)."""
    if row is None:
        return None
    return {key: _iso(value) for key, value in row.items()}


def _text(value: Optional[str]) -> Optional[str]:
    """Strip NUL characters, which PostgreSQL `text` cannot store.

    SQLite accepted `\\x00` inside a TEXT value; PostgreSQL rejects it outright
    ("unsupported Unicode escape sequence" / "invalid byte sequence"). Almost
    everything written here is untrusted text — model output, extracted PDF and
    OCR transcripts, scraped pages, source files — and any one of those can
    carry a stray NUL. Without this, a single bad byte turns a completed answer
    into a 500 and loses it.

    The membership test keeps the common path allocation-free; documents can be
    several MB and copying every one of them to remove nothing would be waste.
    """
    if value is None or "\x00" not in value:
        return value
    return value.replace("\x00", "")


def _dumps_jsonb(obj: Any) -> str:
    """`json.dumps` for jsonb: tolerant of odd types, free of NUL escapes.

    `default=str` mirrors the old call — `meta` carries whatever the engines put
    in it, and a stray datetime must not turn a stored answer into a 500.
    `json.dumps` always escapes NUL as the six characters `\\u0000`, which jsonb
    rejects, so the escape is removed from the serialised form.
    """
    text = json.dumps(obj, ensure_ascii=False, default=str)
    return text.replace("\\u0000", "") if "\\u0000" in text else text


def _json_param(value: Optional[Any]) -> Optional[Jsonb]:
    """Adapt a dict — or a pre-serialised JSON string — to a jsonb parameter."""
    if value is None:
        return None
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except (TypeError, ValueError):
            # Not JSON after all — keep it addressable rather than dropping it.
            value = {"raw": value}
    return Jsonb(value, dumps=_dumps_jsonb)


# ---------------------------------------------------------------------------
# Users
# ---------------------------------------------------------------------------


def create_user(username: str, password_hash: str) -> int:
    """Insert a user; raises db.IntegrityError on a duplicate username
    (unique on lower(username) — SQLite's COLLATE NOCASE)."""
    with connection() as con:
        row = con.execute(
            "INSERT INTO users (username, password_hash, created_at) "
            "VALUES (%s, %s, %s) RETURNING id",
            (_text(username), password_hash, _now()),
        ).fetchone()
    return int(row["id"])


def get_user_by_username(username: str) -> Optional[Dict[str, Any]]:
    with connection() as con:
        row = con.execute(
            "SELECT * FROM users WHERE lower(username) = lower(%s)", (username,)
        ).fetchone()
    return _row(row)


def get_user_by_id(user_id: int) -> Optional[Dict[str, Any]]:
    with connection() as con:
        row = con.execute("SELECT * FROM users WHERE id = %s", (user_id,)).fetchone()
    return _row(row)


def oldest_user() -> Optional[Dict[str, Any]]:
    """The first account ever created — the one whose history to adopt.

    Lives here rather than in `auth.py` so nothing outside this module has to
    open a connection of its own (the old `auth._oldest_user` opened one and
    never closed it, leaking a handle per resolution).
    """
    with connection() as con:
        row = con.execute("SELECT * FROM users ORDER BY id LIMIT 1").fetchone()
    return _row(row)


# ---------------------------------------------------------------------------
# Conversations + messages — every accessor is scoped to a user_id (§3c):
# a conversation owned by someone else is indistinguishable from a missing
# one (the caller turns None/False into 404).
# ---------------------------------------------------------------------------


def _conversation_dict(row: Dict[str, Any]) -> dict:
    """Row → JSON-friendly dict. The flags are real booleans now; the coercion
    stays so a caller that stored 0/1 through some other path still reads back
    `true`/`false` in the API."""
    out = _row(row) or {}
    for flag in ("pinned", "archived"):
        if flag in out:
            out[flag] = bool(out[flag])
    return out


def list_conversations(user_id: int, archived: bool = False) -> List[dict]:
    """The user's conversations, active by default (V3-DESIGN §1).

    `archived=True` returns the archived ones instead — the two sets are
    disjoint, so the sidebar's Archived section is a separate fetch. Pinned
    conversations float to the top, then most-recent activity.
    """
    with connection() as con:
        rows = con.execute(
            "SELECT id, title, updated_at, pinned, archived FROM conversations "
            "WHERE user_id = %s AND archived = %s "
            "ORDER BY pinned DESC, updated_at DESC, seq DESC",
            (user_id, bool(archived)),
        ).fetchall()
    return [_conversation_dict(r) for r in rows]


def create_conversation(user_id: int, conversation_id: str, title: str) -> dict:
    """Insert a conversation; raises db.IntegrityError when the id exists."""
    now = _now()
    with connection() as con:
        con.execute(
            "INSERT INTO conversations (id, user_id, title, created_at, updated_at) "
            "VALUES (%s, %s, %s, %s, %s)",
            (conversation_id, user_id, _text(title), now, now),
        )
    return {
        "id": conversation_id,
        "title": title,
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
        "pinned": False,
        "archived": False,
    }


def get_conversation(user_id: int, conversation_id: str) -> Optional[dict]:
    with connection() as con:
        row = con.execute(
            "SELECT id, title, created_at, updated_at, pinned, archived "
            "FROM conversations WHERE id = %s AND user_id = %s",
            (conversation_id, user_id),
        ).fetchone()
    return _conversation_dict(row) if row else None


def update_conversation(
    user_id: int,
    conversation_id: str,
    title: Optional[str] = None,
    pinned: Optional[bool] = None,
    archived: Optional[bool] = None,
) -> Optional[dict]:
    """Update any subset of {title, pinned, archived}; None means "leave alone".

    Only a rename counts as activity: pinning or archiving sets the flag and
    nothing else, so a chat keeps its place in the updated_at ordering when it
    comes back out of the archive (V3-DESIGN §1). Returns None when the
    conversation is missing or owned by someone else.
    """
    assignments: List[str] = []
    values: List[object] = []
    if title is not None:
        # A rename is an act of ownership: mark the title 'user' so the
        # auto-titler can never overwrite it, on this device or any other.
        assignments += ["title = %s", "title_source = 'user'", "updated_at = %s"]
        values += [_text(title), _now()]
    if pinned is not None:
        assignments.append("pinned = %s")
        values.append(bool(pinned))
    if archived is not None:
        assignments.append("archived = %s")
        values.append(bool(archived))
    if not assignments:  # nothing to change — just an ownership-scoped read
        return get_conversation(user_id, conversation_id)
    with connection() as con:
        # RETURNING makes this one round trip instead of an UPDATE followed by
        # a SELECT, and closes the window where another tab could change the
        # row between the two.
        row = con.execute(
            f"UPDATE conversations SET {', '.join(assignments)} "
            "WHERE id = %s AND user_id = %s "
            "RETURNING id, title, created_at, updated_at, pinned, archived",
            (*values, conversation_id, user_id),
        ).fetchone()
    return _conversation_dict(row) if row else None


#: Conversation-keyed tables with no foreign key (see the note on _MIGRATIONS).
#: Deleting a conversation has to clear these by hand.
_SIDE_TABLES = (
    # V30 query tracing. Bare /chat calls can have no conversations row, so
    # the trace owns events by FK while conversation deletion clears roots.
    "query_traces",
    "uploads",
    "url_documents",
    "documents",
    "repos",
    "repo_chunks",
    # Salesforce Intelligence Mode. A deleted conversation must not leave a
    # pending clarification behind: the unique partial index below allows one
    # per conversation, so an orphan would block the id from ever being reused.
    "sf_clarifications",
    "sf_intents",
    "sf_conversation_state",
    # V8 web-search memory: the per-conversation search log. web_results rows
    # cascade from it; web_pages is GLOBAL shared content and is never deleted
    # with a conversation.
    "web_searches",
    # V9 crawls: the run record is conversational; the pages are global.
    "web_crawls",
    # V11 Deep Research: the run record (and the report text inside it) is
    # conversational. The user_id FK would cascade, but a run started by an
    # anonymous API call has user_id NULL and would otherwise survive forever.
    "research_runs",
    # V28 video: the link between a conversation and a content-addressed
    # analysis. The analysis itself is shared and outlives the conversation
    # until video.pipeline.reap_orphans finds nobody refers to it.
    "video_attachments",
    # V29: a conversation's upload sessions and send intents are its own.
    "upload_sessions",
    "chat_requests",
    # V31 artifacts, artifact_versions and artifact_jobs are DELIBERATELY
    # absent, for the reason report_files is: they are the person's
    # deliverables, addressed by id from GET /artifacts without their
    # conversation, and a file downloaded last week stays theirs whether or
    # not the chat that produced it does. They leave with the account (the
    # users FK cascades), never with a chat.
)


# ---------------------------------------------------------------------------
# V8: web-search memory
# ---------------------------------------------------------------------------
def log_web_search(
    user_id: Optional[int],
    conversation_id: str,
    message: str,
    queries: List[str],
    provider: str,
    effort: str,
    results: List[dict],
) -> int:
    """One row per search run, plus every link its queries returned.

    `results` rows carry {query, rank, url, url_key, title, snippet}. The log
    is why a later "what did we find about X last week?" is answerable at all:
    the page store is global and says nothing about WHO asked or WHEN.
    """
    now = _now()
    with connection() as con:
        row = con.execute(
            "INSERT INTO web_searches (user_id, conversation_id, message, "
            "queries, provider, effort, requested_at) "
            "VALUES (%s, %s, %s, %s, %s, %s, %s) RETURNING id",
            (
                user_id,
                _text(conversation_id),
                _text(message),
                _json_param(list(queries)),
                _text(provider),
                _text(effort),
                now,
            ),
        ).fetchone()
        search_id = int(row["id"])
        for r in results:
            con.execute(
                "INSERT INTO web_results (search_id, query, rank, url, url_key, "
                "title, snippet) VALUES (%s, %s, %s, %s, %s, %s, %s)",
                (
                    search_id,
                    _text(r.get("query", "")),
                    int(r.get("rank", 0)),
                    _text(r.get("url", "")),
                    _text(r.get("url_key", "")),
                    _text(r.get("title", "")),
                    _text(r.get("snippet", "")),
                ),
            )
        return search_id


#: Versions kept per page. Enough to see a fact change hands twice; small
#: enough that a daily-changing news front page cannot grow without bound.
_MAX_PAGE_VERSIONS = 5


def _initial_refresh_deadline(now: datetime, text: str) -> Optional[datetime]:
    """When a newly stored page first becomes eligible for re-fetch.

    Without this the column stayed NULL and `web_worker._due_pages`, which
    requires `next_refresh_at IS NOT NULL`, could never see the page again:
    73% of the live corpus was stranded that way (see _MIGRATION_V23).

    Staggered across 24h rather than stamped with a single deadline, so a
    burst of stored pages does not come due as a burst of fetches. The worker
    replaces this with a volatility-derived TTL (`web_worker._ttl_for`) the
    first time it actually refreshes the page — this only has to get the row
    into the queue. Pages with no text are left unscheduled, matching the
    scheduler's own `text <> ''` filter.
    """
    if not (text or "").strip():
        return None
    return now + timedelta(seconds=random.uniform(0, 24 * 3600))


def upsert_web_page(
    url_key: str,
    url: str,
    canonical_url: str,
    title: str,
    text: str,
    content_type: str,
    fetch_status: int,
    content_hash: str,
    links: Optional[List[str]] = None,
    *,
    published_at: Optional[datetime] = None,
    modified_at: Optional[datetime] = None,
    source_type: str = "",
    authority: int = 0,
    etag: str = "",
    last_modified: str = "",
    origin: str = "search",
    introduced_by_user_id: Optional[int] = None,
    introduced_in_conversation_id: Optional[str] = None,
    extract_version: int = 0,
) -> dict:
    """Store (or refresh) one fetched page, globally deduped by `url_key`.

    `origin` (V16) is how the page entered the shared corpus — search,
    refresh, crawl, share, research. The first introducer is kept for the
    life of the row; the origin is only ever UPGRADED (a page a member
    shared that a later search finds independently becomes 'search' — trust
    earned by independent discovery), never downgraded.

    Returns {"id", "changed", "previous_hash"}. `changed` is the re-store
    signal the owner asked for: the same URL fetched again with a DIFFERENT
    content hash means the site moved on, so the vector index must re-chunk it
    (indexed_at is reset to NULL exactly then). An unchanged hash only bumps
    the freshness clock — no re-embedding, no index churn.

    V14: provenance rides in (dates the page states about itself, its
    structural source class, the cached authority) and a CHANGED page's
    previous text is preserved in web_page_versions before it is replaced —
    a change over time stays distinguishable from a contradiction.

    V22: `extract_version` records WHICH extractor filled `text`, so a later
    extractor improvement can re-read the pages that predate it in priority
    order instead of triggering a mass recrawl. It only ever moves up.

    V23: `next_refresh_at` is seeded here. It was missing from the column
    list, so every page stored after V13 was written NULL and could never be
    picked up by the refresh scheduler again. On conflict the stored deadline
    wins whenever it is set, so healing an old NULL row never overwrites a
    deadline the worker chose.

    V26: `last_changed_at` means "when we OBSERVED this page's content move",
    and a first insert observes nothing — it is NULL until a later fetch comes
    back with a different hash. It used to be stamped with `now` on insert,
    which made "when we first saw it" and "when it last changed" the same
    column for any page fetched once, i.e. most of the corpus.
    """
    now = _now()
    from .core.provenance import domain_of as _domain_of

    domain = _domain_of(url) or ""
    with connection() as con:
        prev = con.execute(
            "SELECT id, content_hash, title, text, published_at, fetched_at "
            "FROM web_pages WHERE url_key = %s",
            (url_key,),
        ).fetchone()
        previous_hash = prev["content_hash"] if prev else None
        changed = previous_hash is not None and previous_hash != content_hash
        if changed and (prev.get("text") or "").strip():
            # Keep what the page USED to say. Written before the update so a
            # crash between the two leaves the old version, never nothing.
            con.execute(
                "INSERT INTO web_page_versions (page_id, content_hash, title, "
                "text, published_at, fetched_at, superseded_at) "
                "VALUES (%s, %s, %s, %s, %s, %s, %s)",
                (
                    int(prev["id"]),
                    _text(previous_hash or ""),
                    _text(prev.get("title") or ""),
                    _text(prev.get("text") or ""),
                    prev.get("published_at"),
                    prev.get("fetched_at") or now,
                    now,
                ),
            )
            con.execute(
                "DELETE FROM web_page_versions WHERE page_id = %s AND id NOT IN ("
                "SELECT id FROM web_page_versions WHERE page_id = %s "
                "ORDER BY superseded_at DESC, id DESC LIMIT %s)",
                (int(prev["id"]), int(prev["id"]), _MAX_PAGE_VERSIONS),
            )
        row = con.execute(
            "INSERT INTO web_pages (url_key, url, canonical_url, title, text, "
            "content_type, fetch_status, content_hash, links, fetch_count, "
            "first_seen_at, fetched_at, indexed_at, published_at, modified_at, "
            "last_changed_at, source_type, authority, domain, etag, last_modified, "
            "origin, introduced_by_user_id, introduced_in_conversation_id, "
            "next_refresh_at, extract_version) "
            "VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, 1, %s, %s, NULL, "
            "%s, %s, NULL, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s) "
            "ON CONFLICT (url_key) DO UPDATE SET "
            # Provenance (V16): the first introducer stays; origin may only
            # move towards more trust ('share' → anything found independently).
            "origin = CASE WHEN web_pages.origin = 'share' AND EXCLUDED.origin <> 'share' "
            "THEN EXCLUDED.origin ELSE web_pages.origin END, "
            "introduced_by_user_id = COALESCE(web_pages.introduced_by_user_id, EXCLUDED.introduced_by_user_id), "
            "introduced_in_conversation_id = COALESCE(web_pages.introduced_in_conversation_id, "
            "EXCLUDED.introduced_in_conversation_id), "
            "url = EXCLUDED.url, canonical_url = EXCLUDED.canonical_url, "
            "title = EXCLUDED.title, text = EXCLUDED.text, "
            "content_type = EXCLUDED.content_type, "
            "fetch_status = EXCLUDED.fetch_status, "
            "content_hash = EXCLUDED.content_hash, "
            "links = EXCLUDED.links, "
            "fetch_count = web_pages.fetch_count + 1, "
            "fetched_at = EXCLUDED.fetched_at, "
            # A changed page must be re-indexed; an unchanged one keeps its
            # vectors exactly as they are.
            "indexed_at = CASE WHEN web_pages.content_hash = EXCLUDED.content_hash "
            "THEN web_pages.indexed_at ELSE NULL END, "
            # Dates are facts the page states; a page that stops stating one
            # does not un-publish itself, so a known value is never erased.
            "published_at = COALESCE(EXCLUDED.published_at, web_pages.published_at), "
            "modified_at = COALESCE(EXCLUDED.modified_at, web_pages.modified_at), "
            # K8 (2026-09-07): "when did this page's content MOVE" — and
            # nothing else. The CASE was already right: an unchanged re-fetch
            # keeps the stored value. What was wrong sat on the INSERT side,
            # which stamped `now` on a page being seen for the FIRST time and
            # so recorded a change that was never observed (61% of the live
            # corpus; see _MIGRATION_V26). The INSERT now writes NULL and the
            # timestamp is supplied HERE, where the SQL itself has just proved
            # the hash moved — not from a `changed` flag computed in Python
            # from an earlier SELECT, which a concurrent writer could have
            # made stale between the two statements.
            "last_changed_at = CASE WHEN web_pages.content_hash = EXCLUDED.content_hash "
            "THEN web_pages.last_changed_at ELSE %s END, "
            "source_type = CASE WHEN EXCLUDED.source_type <> '' "
            "THEN EXCLUDED.source_type ELSE web_pages.source_type END, "
            "authority = CASE WHEN EXCLUDED.authority > 0 "
            "THEN EXCLUDED.authority ELSE web_pages.authority END, "
            "domain = CASE WHEN EXCLUDED.domain <> '' THEN EXCLUDED.domain ELSE web_pages.domain END, "
            "etag = CASE WHEN EXCLUDED.etag <> '' THEN EXCLUDED.etag ELSE web_pages.etag END, "
            "last_modified = CASE WHEN EXCLUDED.last_modified <> '' "
            "THEN EXCLUDED.last_modified ELSE web_pages.last_modified END, "
            # Heal a row stranded with NULL (see V23) without ever
            # overriding a deadline the refresh worker has set.
            "next_refresh_at = COALESCE(web_pages.next_refresh_at, EXCLUDED.next_refresh_at), "
            # Never downgrade. A page re-read by a newer extractor records the
            # newer version; a write from an older path (or one that does not
            # set it at all) must not make the row look stale again and put it
            # back in the re-extraction queue forever.
            "extract_version = GREATEST(web_pages.extract_version, EXCLUDED.extract_version) "
            "RETURNING id",
            (
                _text(url_key),
                _text(url),
                _text(canonical_url),
                _text(title),
                # The one param that skipped _text() — and the largest
                # untrusted one. A NUL survives utf-8 decoding (text/plain,
                # PDF text layers), PostgreSQL rejects it, and the DataError
                # aborted whole crawls (review round, 2026-08-30).
                _text(text or ""),
                _text(content_type),
                int(fetch_status),
                _text(content_hash),
                [_text(l) for l in (links or [])][:500],
                now,
                now,
                published_at,
                modified_at,
                _text(source_type or ""),
                int(authority or 0),
                _text(domain),
                _text(etag or "")[:200],
                _text(last_modified or "")[:100],
                _text(origin or "search")[:20],
                int(introduced_by_user_id) if introduced_by_user_id is not None else None,
                _text(introduced_in_conversation_id or "")[:64] or None,
                _initial_refresh_deadline(now, text),
                int(extract_version or 0),
                # The ON CONFLICT clause's own parameter — last in the SQL
                # text, so last in this tuple: the moment a hash change was
                # OBSERVED. Never reached on a first insert.
                now,
            ),
        ).fetchone()
        bump_web_corpus_generation()
        return {"id": int(row["id"]), "changed": changed, "previous_hash": previous_hash}


def touch_web_page_unchanged(url_key: str, etag: str = "", last_modified: str = "") -> None:
    """Record a 304: advance the freshness clock and NOTHING else.

    A conditional re-fetch that comes back 304 proves the stored copy is still
    current. `text`, `content_hash`, `links`, `indexed_at`, `last_changed_at`
    and `extract_version` are therefore all still correct — and `indexed_at` in
    particular must not move, or the page would be re-chunked and re-embedded
    for a body that was never downloaded. `fetched_at` is the one genuinely new
    fact: we confirmed the copy is current just now, which is what the TTL and
    every recency score actually ask about.

    Deliberately not routed through `upsert_web_page`: that call needs a body.
    Passing an empty `text` would blank the stored page, and passing the old
    text back would rewrite the row — and append to its version history — to
    say something happened when nothing did.

    Fresh validators are stored when the server re-sent them (RFC 9110 allows a
    304 to carry an updated ETag) and left alone when it did not.
    """
    with connection() as con:
        con.execute(
            """UPDATE web_pages
                  SET fetched_at = now(),
                      fetch_count = fetch_count + 1,
                      etag = CASE WHEN %s <> '' THEN %s ELSE etag END,
                      last_modified = CASE WHEN %s <> '' THEN %s ELSE last_modified END
                WHERE url_key = %s""",
            (
                _text(etag or ""),
                _text(etag or ""),
                _text(last_modified or ""),
                _text(last_modified or ""),
                _text(url_key),
            ),
        )
    bump_web_corpus_generation()


def servable_web_page_ids(page_ids: Sequence[int]) -> set:
    """Of these page ids, the ones a retrieval result may actually show.

    The vector index is DERIVED state and can outlive its rows: a purge that
    dropped the page (or an operator quarantine) leaves chunks behind, and
    `engines/crawl.site_hits_for` renders `web_index.retrieve` output straight
    into an answer with no database round trip of its own. Before this existed
    a quarantined page was still being answered from and a purged one still
    cited — the row was gone and its text still reached the user.

    Cheap on purpose: one indexed `id = ANY(...)` over the ids a query is about
    to return, called after the distance floor so only returnable hits are
    looked up, and never on the event loop.
    """
    ids = [int(i) for i in page_ids]
    if not ids:
        return set()
    with connection() as con:
        rows = con.execute(
            "SELECT id FROM web_pages WHERE id = ANY(%s) AND quarantined_at IS NULL",
            (ids,),
        ).fetchall()
    return {int(r["id"]) for r in rows}


def set_web_page_quarantine(page_ids: Sequence[int], *, quarantined: bool) -> int:
    """Withhold (or restore) pages from every retrieval path. Returns rows hit.

    Quarantine is a column rather than a delete so the decision is reversible
    and auditable — the page's text, provenance and history stay put. The
    corpus generation is bumped so a cached retrieval computed before the
    change cannot outlive it.
    """
    ids = [int(i) for i in page_ids]
    if not ids:
        return 0
    with connection() as con:
        rows = con.execute(
            "UPDATE web_pages SET quarantined_at = %s WHERE id = ANY(%s) RETURNING id",
            (_now() if quarantined else None, ids),
        ).fetchall()
    bump_web_corpus_generation()
    return len(rows)


def web_page_ids_for_urls(urls: Sequence[str]) -> dict:
    """{url as given: page id} for urls matching either `url` or `canonical_url`.

    The handle an operator actually holds is a link out of a citation panel,
    and that may be either spelling — a page fetched through a redirect is
    stored under both. Unmatched urls are simply absent from the result.
    """
    wanted = [_text(u) for u in urls if (u or "").strip()]
    if not wanted:
        return {}
    with connection() as con:
        rows = con.execute(
            "SELECT id, url, canonical_url FROM web_pages "
            "WHERE url = ANY(%s) OR canonical_url = ANY(%s)",
            (wanted, wanted),
        ).fetchall()
    out: dict = {}
    for row in rows:
        for spelling in (row["url"], row["canonical_url"]):
            if spelling in wanted:
                out[spelling] = int(row["id"])
    return out


#: Bumped on every write to the shared corpus (page upsert, index write,
#: quarantine). The evidence cache (web_memory) keys on it, so a cached
#: retrieval can never outlive the corpus it was computed from — the Fast
#: lookup's read-back after fetching two pages sees those pages.
_web_corpus_generation = 0


def bump_web_corpus_generation() -> None:
    global _web_corpus_generation
    _web_corpus_generation += 1


def web_corpus_generation() -> int:
    return _web_corpus_generation


def record_voice_transcription(
    *,
    user_id: int,
    duration_ms: Optional[int],
    language: Optional[str],
    processing_ms: Optional[int],
    status: str,
    degraded: bool = False,
) -> None:
    """One metadata row per dictation attempt (V19).

    Metadata ONLY — see the migration. Never raises: a missing telemetry row
    is a gap in a report, an exception here would be a failed transcription
    for a person who is waiting to speak.
    """
    try:
        with connection() as con:
            con.execute(
                """INSERT INTO voice_transcriptions
                       (created_at, user_id, duration_ms, language,
                        processing_ms, status, degraded)
                   VALUES (%s, %s, %s, %s, %s, %s, %s)""",
                (
                    _now(),
                    user_id,
                    duration_ms,
                    (language or None),
                    processing_ms,
                    status,
                    bool(degraded),
                ),
            )
    except Exception:  # noqa: BLE001
        import logging

        logging.getLogger(__name__).debug(
            "voice transcription row not written", exc_info=True
        )


def get_web_pages(url_keys: List[str]) -> List[dict]:
    """Stored pages for these normalized URLs — the fetch layer's warm cache."""
    if not url_keys:
        return []
    with connection() as con:
        rows = con.execute(
            "SELECT id, url_key, url, canonical_url, title, text, content_type, "
            "fetch_status, content_hash, fetched_at, links, published_at, "
            "modified_at, source_type, authority, domain FROM web_pages "
            "WHERE url_key = ANY(%s)",
            (list(url_keys),),
        ).fetchall()
    return [dict(r) for r in rows]


def get_web_page_versions(page_id: int, limit: int = _MAX_PAGE_VERSIONS) -> List[dict]:
    """Earlier versions of a page, newest first — what it USED to say."""
    with connection() as con:
        rows = con.execute(
            "SELECT id, content_hash, title, text, published_at, fetched_at, "
            "superseded_at FROM web_page_versions WHERE page_id = %s "
            "ORDER BY superseded_at DESC, id DESC LIMIT %s",
            (int(page_id), int(limit)),
        ).fetchall()
    return [dict(r) for r in rows]


# ---------------------------------------------------------------------------
# V14: research claims — public, shared, dated
# ---------------------------------------------------------------------------
def insert_web_claims(rows: List[dict]) -> int:
    """Persist resolved claims from one research run. Returns rows written.

    V16 columns: `quote` is the sentence of the source the claim was taken
    from (the engine only writes a row it could find such a sentence for);
    `origin_user_id` / `origin_conversation_id` say whose run produced the
    row, so it is attributable and can be purged with the conversation. Both
    origin columns are NULL, not '', when the caller has no identity — a
    conversation id of '' would never match a delete and would outlive it.
    """
    if not rows:
        return 0
    now = _now()
    written = 0
    with connection() as con:
        for r in rows:
            claim = _text(str(r.get("claim") or "")).strip()
            if not claim:
                continue
            origin_user = r.get("origin_user_id")
            origin_conversation = _text(str(r.get("origin_conversation_id") or "")).strip()
            con.execute(
                "INSERT INTO web_claims (research_id, page_id, url, subquestion, "
                "claim, value, as_of, kind, confidence, created_at, "
                "quote, origin_user_id, origin_conversation_id) "
                "VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)",
                (
                    _text(str(r.get("research_id") or "")),
                    r.get("page_id"),
                    _text(str(r.get("url") or ""))[:2000],
                    _text(str(r.get("subquestion") or ""))[:1000],
                    claim[:2000],
                    _text(str(r.get("value") or ""))[:1000],
                    r.get("as_of"),
                    _text(str(r.get("kind") or "unknown"))[:20],
                    float(r.get("confidence") or 0.0),
                    now,
                    _text(str(r.get("quote") or ""))[:2000],
                    int(origin_user) if origin_user is not None else None,
                    origin_conversation[:200] or None,
                ),
            )
            written += 1
    return written


def search_web_claims(terms: str, limit: int = 5, kinds: Optional[List[str]] = None) -> List[dict]:
    """Claims whose text matches the question's words, best match first.

    `websearch_to_tsquery` takes what a person types and never raises on
    punctuation; ranking prefers the closer match, then the newer claim."""
    query = (terms or "").strip()
    if not query:
        return []
    wanted = list(kinds or ["current"])
    with connection() as con:
        rows = con.execute(
            """SELECT c.id, c.research_id, c.url, c.subquestion, c.claim, c.value,
                      c.as_of, c.kind, c.confidence, c.created_at,
                      p.domain, p.authority, p.published_at,
                      ts_rank_cd(c.search_tsv, websearch_to_tsquery('english', %s)) AS rank
                 FROM web_claims c
                 LEFT JOIN web_pages p ON p.id = c.page_id
                WHERE c.search_tsv @@ websearch_to_tsquery('english', %s)
                  AND c.kind = ANY(%s)
                ORDER BY rank DESC, c.created_at DESC
                LIMIT %s""",
            (query, query, wanted, int(limit)),
        ).fetchall()
    return [dict(r) for r in rows]


def reset_web_index_watermark() -> int:
    """Queue every stored page for re-indexing. Returns rows affected.

    The vector index is DERIVED state; this is how it is rebuilt from
    PostgreSQL after the LanceDB directory is lost or a chunker changes."""
    with connection() as con:
        cur = con.execute(
            "UPDATE web_pages SET indexed_at = NULL WHERE indexed_at IS NOT NULL AND text <> ''"
        )
        return int(cur.rowcount or 0)


def get_unindexed_web_pages(
    limit: int = 20,
    page_ids: Optional[List[int]] = None,
    chunk_version: int = 0,
) -> List[dict]:
    """Pages whose vectors are missing OR were built by an obsolete chunker.

    Two distinct reasons a page needs indexing, and conflating them was the
    bug (V24): `indexed_at IS NULL` means "no vectors for this text", while
    `chunk_version < CHUNKER_VERSION` means "vectors exist and are shaped
    wrong". A page whose text never changes only ever hits the second, so
    before this it kept obsolete chunks forever.

    `chunk_version` is the CURRENT chunker version, passed in because db.py
    must not import web_index (which imports db). 0 keeps the old behaviour.

    New/changed pages come first (a user is likely waiting on those), then the
    stale-chunker repair, most-retrieved-first so the pages behind the most
    answers are fixed first.

    `page_ids` restricts the pass to those pages — the Fast lookup indexes
    the two pages it just fetched instead of draining the global queue
    inside its deadline."""
    stale = "(indexed_at IS NULL OR chunk_version < %s)"
    order = "ORDER BY (indexed_at IS NULL) DESC, retrieval_count DESC, fetched_at DESC"
    with connection() as con:
        if page_ids:
            rows = con.execute(
                "SELECT id, url_key, url, title, text, fetched_at FROM web_pages "
                f"WHERE {stale} AND text <> '' AND id = ANY(%s) "
                f"{order} LIMIT %s",
                (int(chunk_version), [int(i) for i in page_ids], int(limit)),
            ).fetchall()
        else:
            rows = con.execute(
                "SELECT id, url_key, url, title, text, fetched_at FROM web_pages "
                f"WHERE {stale} AND text <> '' "
                f"{order} LIMIT %s",
                (int(chunk_version), int(limit)),
            ).fetchall()
    return [dict(r) for r in rows]


def count_stale_chunk_pages(chunk_version: int) -> int:
    """How many stored pages still carry vectors from an older chunker."""
    with connection() as con:
        return int(
            con.execute(
                "SELECT count(*) AS n FROM web_pages "
                "WHERE text <> '' AND indexed_at IS NOT NULL AND chunk_version < %s",
                (int(chunk_version),),
            ).fetchone()["n"]
        )


def mark_web_pages_indexed(page_ids: List[int], chunk_version: int = 0) -> None:
    """Stamp the watermark AND the chunker that produced these vectors.

    Recording the version is what stops a repaired page from being picked up
    again on the next cycle; without it the stale-chunker scan would return the
    same pages forever (the same spin `extract_version` needed GREATEST for).
    """
    if not page_ids:
        return
    with connection() as con:
        con.execute(
            "UPDATE web_pages SET indexed_at = %s, "
            "chunk_version = GREATEST(chunk_version, %s) WHERE id = ANY(%s)",
            (_now(), int(chunk_version), list(page_ids)),
        )
    bump_web_corpus_generation()


# ---------------------------------------------------------------------------
# V9: site crawls
# ---------------------------------------------------------------------------
def create_web_crawl(conversation_id: str, root_url: str, scope_prefix: str) -> int:
    with connection() as con:
        row = con.execute(
            "INSERT INTO web_crawls (conversation_id, root_url, scope_prefix, "
            "status, started_at) VALUES (%s, %s, %s, 'running', %s) RETURNING id",
            (_text(conversation_id), _text(root_url), _text(scope_prefix), _now()),
        ).fetchone()
        return int(row["id"])


def finish_web_crawl(
    crawl_id: int,
    status: str,
    pages_found: int,
    pages_fetched: int,
    pages_from_store: int,
    pages_failed: int,
    detail: str = "",
) -> None:
    with connection() as con:
        con.execute(
            "UPDATE web_crawls SET status = %s, pages_found = %s, "
            "pages_fetched = %s, pages_from_store = %s, pages_failed = %s, "
            "detail = %s, finished_at = %s WHERE id = %s",
            (
                _text(status), int(pages_found), int(pages_fetched),
                int(pages_from_store), int(pages_failed), _text(detail),
                _now(), int(crawl_id),
            ),
        )


def create_research_run(
    conversation_id: str,
    user_id: Optional[int],
    question: str,
    research_id: str,
) -> int:
    """Open a Deep Research run record; returns its row id."""
    now = _now()
    with connection() as con:
        row = con.execute(
            "INSERT INTO research_runs (research_id, conversation_id, user_id, "
            "question, status, started_at) VALUES (%s, %s, %s, %s, 'running', %s) "
            "RETURNING id",
            (
                _text(research_id),
                _text(conversation_id),
                user_id,
                _text(question),
                now,
            ),
        ).fetchone()
    return int(row["id"])


def finish_research_run(
    run_id: int,
    status: str,
    iterations: int,
    queries_run: int,
    sources_found: int,
    sources_cited: int,
    report: str,
    sources: Optional[List[dict]] = None,
    detail: str = "",
) -> None:
    """Close a run with its counts, its report and its citation registry."""
    with connection() as con:
        con.execute(
            "UPDATE research_runs SET status = %s, iterations = %s, "
            "queries_run = %s, sources_found = %s, sources_cited = %s, "
            "report = %s, sources = %s, detail = %s, finished_at = %s "
            "WHERE id = %s",
            (
                _text(status),
                int(iterations),
                int(queries_run),
                int(sources_found),
                int(sources_cited),
                _text(report or ""),
                _json_param(list(sources or [])),
                _text(detail),
                _now(),
                int(run_id),
            ),
        )


def close_interrupted_research_runs() -> int:
    """At startup: close research runs a restart left claiming to be running.

    `web_crawls` has had this since V14 (`requeue_interrupted_web_crawls`);
    `research_runs` never did, so a run interrupted by a restart stayed
    'running' forever — inflating the admin research analytics and hiding
    that the run had died.

    These are closed rather than requeued, unlike a background crawl. A crawl
    resumes nearly free because its fetched pages are already stored, but a
    research run keeps its plan, claims and resolutions only in process
    memory: there is nothing on disk to resume from, and silently restarting
    someone's 10-minute investigation without them asking would be worse than
    telling them it stopped. Any pages it fetched are already in the shared
    corpus regardless.
    """
    with connection() as con:
        closed = con.execute(
            "UPDATE research_runs SET status = 'failed', "
            "detail = 'interrupted by a restart', finished_at = %s "
            "WHERE status = 'running' RETURNING id",
            (_now(),),
        ).fetchall()
    return len(closed)


def get_research_runs(conversation_id: str, limit: int = 10) -> List[dict]:
    """Research runs in this conversation, newest first."""
    with connection() as con:
        rows = con.execute(
            "SELECT id, research_id, question, status, iterations, queries_run, "
            "sources_found, sources_cited, report, sources, detail, started_at, "
            "finished_at FROM research_runs WHERE conversation_id = %s "
            "ORDER BY id DESC LIMIT %s",
            (_text(conversation_id), int(limit)),
        ).fetchall()
    return [dict(r) for r in rows]


def get_conversation_crawl_sites(conversation_id: str) -> List[dict]:
    """Sites crawled in this conversation — the follow-up Q&A scope."""
    with connection() as con:
        rows = con.execute(
            "SELECT id, root_url, scope_prefix, status, pages_fetched, "
            "pages_from_store FROM web_crawls WHERE conversation_id = %s "
            "AND status IN ('done', 'capped') ORDER BY id DESC LIMIT 5",
            (conversation_id,),
        ).fetchall()
    return [dict(r) for r in rows]


# ---------------------------------------------------------------------------
# V14: the background crawl queue
# ---------------------------------------------------------------------------
def enqueue_web_crawl(
    conversation_id: str,
    root_url: str,
    scope_prefix: str,
    kind: str = "share",
    max_pages: int = 0,
    max_minutes: float = 0.0,
    priority: int = 0,
    recent_hours: float = 24.0,
) -> Optional[int]:
    """Queue a bounded background crawl of one site. → the job id, or None
    when the same scope is already queued/running or was crawled within
    `recent_hours` (a shared link is not a reason to re-read a site read this
    morning)."""
    with connection() as con:
        existing = con.execute(
            "SELECT id FROM web_crawls WHERE scope_prefix = %s AND ("
            "status IN ('queued', 'running') OR (status IN ('done', 'capped') "
            "AND finished_at IS NOT NULL AND finished_at > now() - make_interval(secs => %s)))"
            " ORDER BY id DESC LIMIT 1",
            (_text(scope_prefix), float(recent_hours) * 3600.0),
        ).fetchone()
        if existing:
            return None
        row = con.execute(
            "INSERT INTO web_crawls (conversation_id, root_url, scope_prefix, "
            "status, started_at, kind, max_pages, max_minutes, priority) "
            "VALUES (%s, %s, %s, 'queued', %s, %s, %s, %s, %s) RETURNING id",
            (
                _text(conversation_id or ""),
                _text(root_url),
                _text(scope_prefix),
                _now(),
                _text(kind or "share")[:20],
                int(max_pages or 0),
                float(max_minutes or 0.0),
                int(priority or 0),
            ),
        ).fetchone()
        return int(row["id"])


def next_queued_web_crawl() -> Optional[dict]:
    """Claim the next queued job (highest priority, oldest first) and mark it
    running. SKIP LOCKED keeps two workers from claiming the same row."""
    with connection() as con:
        row = con.execute(
            "WITH picked AS (SELECT id FROM web_crawls WHERE status = 'queued' "
            "ORDER BY priority DESC, id LIMIT 1 FOR UPDATE SKIP LOCKED) "
            "UPDATE web_crawls w SET status = 'running', started_at = %s "
            "FROM picked WHERE w.id = picked.id "
            "RETURNING w.id, w.conversation_id, w.root_url, w.scope_prefix, "
            "w.kind, w.max_pages, w.max_minutes, w.priority",
            (_now(),),
        ).fetchone()
    return dict(row) if row else None


def requeue_interrupted_web_crawls() -> int:
    """At startup: a background job left 'running' by a restart goes back to
    the queue (stored pages make the resume nearly free); a foreground crawl
    cut off the same way is closed as 'capped' — its conversation's follow-up
    Q&A only trusts done/capped crawls, and 'running' forever hid its pages."""
    with connection() as con:
        requeued = con.execute(
            "UPDATE web_crawls SET status = 'queued' "
            "WHERE status = 'running' AND kind <> 'manual' RETURNING id"
        ).fetchall()
        con.execute(
            "UPDATE web_crawls SET status = 'capped', finished_at = %s, "
            "detail = 'interrupted by a restart' "
            "WHERE status = 'running' AND kind = 'manual'",
            (_now(),),
        )
    return len(requeued)


def web_crawl_queue_counts() -> dict:
    with connection() as con:
        row = con.execute(
            "SELECT count(*) FILTER (WHERE status = 'queued') AS queued, "
            "count(*) FILTER (WHERE status = 'running') AS running FROM web_crawls"
        ).fetchone()
    return {"queued": int(row["queued"]) if row else 0, "running": int(row["running"]) if row else 0}


def get_web_crawl(crawl_id: int) -> Optional[dict]:
    with connection() as con:
        row = con.execute(
            "SELECT id, conversation_id, root_url, scope_prefix, status, kind, "
            "pages_found, pages_fetched, pages_from_store, pages_failed, detail, "
            "started_at, finished_at FROM web_crawls WHERE id = %s",
            (int(crawl_id),),
        ).fetchone()
    return dict(row) if row else None


# ---------------------------------------------------------------------------
# V25: the durable crawl frontier (K12)
#
# The crawl's work queue, keyed by CAMPAIGN (`scope_prefix`) rather than by
# `web_crawls.id`, so a foreground "continue crawling" — which opens a new
# web_crawls row for the same site — resumes the same frontier a background
# job left behind. See _MIGRATION_V25 for why the shape is what it is.
#
# Every function here is synchronous and belongs on the `run_in_thread` pool,
# like the rest of this module; the crawler never blocks its event loop on one.
# ---------------------------------------------------------------------------


#: A btree index entry cannot exceed roughly a third of an 8 KB page, and the
#: frontier's identity index covers (scope_prefix, url_key). Anything near that
#: bound is a query-parameter artifact rather than a page, so it is declined at
#: enqueue instead of being truncated into a key that would never match again.
_MAX_FRONTIER_KEY_BYTES = 2000


def add_crawl_frontier(
    scope_prefix: str,
    entries: Sequence[Tuple[str, str, int]],
    crawl_id: Optional[int] = None,
) -> int:
    """Enqueue `(url_key, url, depth)` triples for one campaign. → rows added.

    Idempotent by construction: a URL already in the frontier keeps the state
    it has. That is what makes re-seeding a resumed campaign from the same
    sitemap safe — a page the last run already read must not be reset to
    pending, and a page it left pending must not be duplicated.

    `crawl_id` is provenance only (which run put this here); it never takes
    part in the key.
    """
    rows = []
    seen: set = set()
    skipped_long = 0
    for url_key, url, depth in entries:
        key = _text(url_key or "")
        if not key:
            continue
        if len(key.encode("utf-8")) > _MAX_FRONTIER_KEY_BYTES:
            # SKIPPED, never truncated. A btree entry has a hard size limit, so
            # this cannot simply be stored — and truncating it would produce a
            # row key the crawler could never match when it settles the page,
            # leaving the URL pending forever. A URL this long is a parameter
            # artifact, not a page, so declining it (loudly) is the honest
            # outcome. Nothing else in the crawl is affected.
            skipped_long += 1
            continue
        if key in seen:
            # Deduped in Python as well as in the index: ON CONFLICT cannot
            # resolve two conflicting rows inside ONE statement, and a sitemap
            # that lists the same page twice would otherwise abort the insert
            # with "ON CONFLICT DO UPDATE command cannot affect row a second
            # time" — taking the whole crawl down with it.
            continue
        seen.add(key)
        rows.append((_text(scope_prefix), key, _text(url or ""), int(depth)))
    if skipped_long:
        import logging  # local, like every other logger in this module

        logging.getLogger(__name__).info(
            "crawl frontier: skipped %d URL(s) over %d bytes for scope %s",
            skipped_long, _MAX_FRONTIER_KEY_BYTES, _text(scope_prefix)[:120],
        )
    if not rows:
        return 0
    added = 0
    with connection() as con:
        for chunk_start in range(0, len(rows), 1000):
            chunk = rows[chunk_start : chunk_start + 1000]
            result = con.execute(
                "INSERT INTO web_crawl_frontier "
                "(scope_prefix, url_key, url, depth, crawl_id) "
                "SELECT s, k, u, d, %s FROM unnest(%s::text[], %s::text[], "
                "%s::text[], %s::int[]) AS t(s, k, u, d) "
                "ON CONFLICT (scope_prefix, url_key) DO NOTHING",
                (
                    int(crawl_id) if crawl_id else None,
                    [r[0] for r in chunk],
                    [r[1] for r in chunk],
                    [r[2] for r in chunk],
                    [r[3] for r in chunk],
                ),
            )
            added += int(result.rowcount or 0)
    return added


def take_crawl_frontier(
    scope_prefix: str,
    limit: int,
    after_depth: int = -1,
    after_id: int = 0,
) -> List[dict]:
    """The next `limit` unvisited URLs of one campaign, breadth-first.

    Deliberately NOT a claim: rows stay 'pending' until the page has actually
    settled (see mark_crawl_frontier / defer_crawl_frontier), because a row
    claimed-then-lost would be a page silently skipped. Two crawlers on one
    scope would duplicate a batch of polite fetches at worst — and they cannot
    normally coexist anyway: db.next_queued_web_crawl claims jobs FOR UPDATE
    SKIP LOCKED, enqueue_web_crawl refuses a scope that is queued or running,
    and engines.crawl._QUEUE_LOCK is single-flight per process.

    Because nothing is claimed, "the next pending row" alone would hand back a
    URL this run has already attempted and deferred, forever. `(after_depth,
    after_id)` is a keyset cursor over the same (depth, id) order the index
    carries: within a run it never returns a row twice, and a run that starts
    fresh — a resume — sees every pending row again, deferred ones included.
    New rows are always appended with a higher id at a depth at or below the
    one being read, so the cursor cannot skip work that is discovered later.
    """
    if limit <= 0:
        return []
    with connection() as con:
        rows = con.execute(
            "SELECT id, url_key, url, depth, failures FROM web_crawl_frontier "
            "WHERE scope_prefix = %s AND state = 'pending' "
            "AND (depth, id) > (%s, %s) "
            "ORDER BY depth, id LIMIT %s",
            (_text(scope_prefix), int(after_depth), int(after_id), int(limit)),
        ).fetchall()
    return [dict(r) for r in rows]


def mark_crawl_frontier(
    scope_prefix: str,
    url_keys: Sequence[str],
    outcome: str,
    crawl_id: Optional[int] = None,
) -> int:
    """Settle URLs: 'pending' → 'visited', with why. → rows updated.

    Terminal for this campaign. `outcome` is one of fetched | store | failed |
    refused | blocked | offsite; it is recorded rather than discarded so the
    question the durability work exists to answer — "did the resume skip
    anything, and which" — is answerable from the table.
    """
    keys = [_text(k) for k in url_keys if k]
    if not keys:
        return 0
    with connection() as con:
        result = con.execute(
            "UPDATE web_crawl_frontier SET state = 'visited', outcome = %s, "
            "visited_at = %s, crawl_id = COALESCE(%s, crawl_id) "
            "WHERE scope_prefix = %s AND url_key = ANY(%s) AND state = 'pending'",
            (
                _text(outcome or "")[:20],
                _now(),
                int(crawl_id) if crawl_id else None,
                _text(scope_prefix),
                keys,
            ),
        )
        return int(result.rowcount or 0)


def defer_crawl_frontier(
    scope_prefix: str,
    url_keys: Sequence[str],
    max_failures: int,
    crawl_id: Optional[int] = None,
) -> int:
    """A fetch failed: count it, and retire the URL once it has failed enough.

    → the number of rows that were RETIRED (marked visited/'failed'); the rest
    stay pending for a later attempt. A transient network blip must not cost a
    page for the life of the campaign, and a permanently dead URL must not be
    re-attempted by every resume forever — this is the bound between the two.
    """
    keys = [_text(k) for k in url_keys if k]
    if not keys:
        return 0
    with connection() as con:
        rows = con.execute(
            "UPDATE web_crawl_frontier SET failures = failures + 1, "
            "crawl_id = COALESCE(%s, crawl_id), "
            "state = CASE WHEN failures + 1 >= %s THEN 'visited' ELSE state END, "
            "outcome = CASE WHEN failures + 1 >= %s THEN 'failed' ELSE outcome END, "
            "visited_at = CASE WHEN failures + 1 >= %s THEN %s ELSE visited_at END "
            "WHERE scope_prefix = %s AND url_key = ANY(%s) AND state = 'pending' "
            "RETURNING state",
            (
                int(crawl_id) if crawl_id else None,
                int(max_failures),
                int(max_failures),
                int(max_failures),
                _now(),
                _text(scope_prefix),
                keys,
            ),
        ).fetchall()
    return sum(1 for r in rows if r["state"] == "visited")


def crawl_frontier_counts(scope_prefix: str) -> dict:
    """{"pending", "visited", "total"} for one campaign."""
    with connection() as con:
        row = con.execute(
            "SELECT count(*) FILTER (WHERE state = 'pending') AS pending, "
            "count(*) FILTER (WHERE state = 'visited') AS visited, "
            "count(*) AS total FROM web_crawl_frontier WHERE scope_prefix = %s",
            (_text(scope_prefix),),
        ).fetchone()
    if not row:
        return {"pending": 0, "visited": 0, "total": 0}
    return {
        "pending": int(row["pending"] or 0),
        "visited": int(row["visited"] or 0),
        "total": int(row["total"] or 0),
    }


def clear_crawl_frontier(scope_prefix: str, older_than_s: Optional[float] = None) -> int:
    """Close a campaign: drop its frontier rows. → rows removed.

    Called with no age when a crawl DRAINS its frontier — the campaign is
    finished, and the next crawl of that site must start from a clean sheet
    rather than inherit a complete set of 'visited' rows that would make it a
    no-op. Called WITH an age before seeding, to retire a campaign that was
    capped and then abandoned: without that, a site crawled halfway a year ago
    could never be crawled from scratch again.
    """
    with connection() as con:
        if older_than_s is None:
            result = con.execute(
                "DELETE FROM web_crawl_frontier WHERE scope_prefix = %s",
                (_text(scope_prefix),),
            )
        else:
            result = con.execute(
                "DELETE FROM web_crawl_frontier WHERE scope_prefix = %s AND NOT EXISTS ("
                "SELECT 1 FROM web_crawl_frontier f2 WHERE f2.scope_prefix = %s "
                "AND greatest(f2.enqueued_at, coalesce(f2.visited_at, f2.enqueued_at)) "
                "> now() - make_interval(secs => %s))",
                (_text(scope_prefix), _text(scope_prefix), float(older_than_s)),
            )
        return int(result.rowcount or 0)


def count_unindexed_web_pages() -> int:
    with connection() as con:
        row = con.execute(
            "SELECT count(*) AS n FROM web_pages "
            "WHERE indexed_at IS NULL AND text <> ''"
        ).fetchone()
    return int(row["n"])


def set_generated_title(user_id: int, conversation_id: str, title: str) -> Optional[dict]:
    """Write an AI-generated title, but ONLY over an auto-derived one.

    `title_source = 'auto'` in the WHERE clause is the entire rename guard, and
    it is inside the statement rather than around it on purpose: a
    check-then-write leaves a window where a rename lands between the two and
    is silently reverted — the user watching their own title flip back. Here a
    rename simply makes this UPDATE match zero rows.

    Returns the updated row, or None when the title is already 'user' or
    'generated', the conversation is missing, or it belongs to someone else.
    Callers treat None as "leave it alone", never as an error.
    """
    with connection() as con:
        row = con.execute(
            "UPDATE conversations SET title = %s, title_source = 'generated' "
            " WHERE id = %s AND user_id = %s AND title_source = 'auto' "
            "RETURNING id, title, title_source",
            (_text(title), conversation_id, user_id),
        ).fetchone()
    return _row(row) if row else None


def conversation_title_state(user_id: int, conversation_id: str) -> Optional[dict]:
    """{title, title_source} for one conversation, or None when not theirs.

    Lets a caller skip the model for a conversation that is already named —
    the cheapest LLM call is the one never made.
    """
    with connection() as con:
        row = con.execute(
            "SELECT title, title_source FROM conversations "
            "WHERE id = %s AND user_id = %s",
            (conversation_id, user_id),
        ).fetchone()
    return _row(row) if row else None


def delete_conversation(user_id: int, conversation_id: str) -> bool:
    """Delete a conversation and everything keyed to it.

    Fixes DATA-03. Under SQLite this issued exactly one statement, and only
    `messages`, `conversation_summaries` and `conversation_chunks` had a
    cascading foreign key — so a delete permanently orphaned the conversation's
    uploads, fetched page text, cloned-repo records and every code chunk. That
    is the largest content in the database and nothing could ever reach it
    again. The side tables are cleared explicitly here, in the same
    transaction, so the delete is all-or-nothing.

    Ownership is still checked in the same statement that deletes, so a
    conversation belonging to someone else is a no-op returning False — and
    the side-table deletes only run once that check has passed.
    """
    with connection() as con:
        cur = con.execute(
            "DELETE FROM conversations WHERE id = %s AND user_id = %s",
            (conversation_id, user_id),
        )
        if cur.rowcount == 0:
            return False
        for table in _SIDE_TABLES:
            con.execute(
                f"DELETE FROM {table} WHERE conversation_id = %s", (conversation_id,)
            )
        return True


def list_messages(conversation_id: str) -> List[dict]:
    """The thread, oldest first.

    `id` is included so the client has a STABLE server-side identity for each
    message. It had none before: a live message is keyed by a browser-minted
    uuid and a rehydrated one positionally as `srv-<conversation>-<index>`, so
    anything attached to a message client-side (thumbs) was lost on reload.
    """
    with connection() as con:
        rows = con.execute(
            "SELECT id, role, content, meta, feedback FROM messages "
            "WHERE conversation_id = %s ORDER BY id",
            (conversation_id,),
        ).fetchall()
    # `meta` arrives already parsed — it is jsonb, not a JSON string.
    return [
        {
            "id": int(r["id"]),
            "role": r["role"],
            "content": r["content"],
            "meta": r["meta"],
            "feedback": r["feedback"],
        }
        for r in rows
    ]


#: The only values `messages.feedback` accepts (mirrored by a CHECK constraint).
FEEDBACK_VALUES = ("up", "down")


def set_message_feedback(
    user_id: int, conversation_id: str, message_id: int, feedback: Optional[str]
) -> Optional[dict]:
    """Record (or clear, with None) a thumb on one message.

    Returns the updated {id, feedback, feedback_at}, or None when the message
    does not exist, is not in that conversation, or the conversation belongs to
    someone else — the same "missing and forbidden are indistinguishable" rule
    every other accessor here follows, so a caller cannot probe for ids.

    Ownership is enforced in the STATEMENT, not by a check-then-write: a
    separate lookup would be a race, and this way a message in another
    account's conversation simply matches no row.
    """
    if feedback is not None and feedback not in FEEDBACK_VALUES:
        raise ValueError(f"feedback must be one of {FEEDBACK_VALUES} or None")
    with connection() as con:
        row = con.execute(
            "UPDATE messages m SET feedback = %s, feedback_at = %s "
            "  FROM conversations c "
            " WHERE m.conversation_id = c.id "
            "   AND m.id = %s AND m.conversation_id = %s AND c.user_id = %s "
            "RETURNING m.id, m.feedback, m.feedback_at",
            (
                feedback,
                _now() if feedback is not None else None,
                message_id,
                conversation_id,
                user_id,
            ),
        ).fetchone()
    if row is None:
        return None
    return {
        "id": int(row["id"]),
        "feedback": row["feedback"],
        "feedback_at": _iso(row["feedback_at"]),
    }


def list_confirmed_sql_examples(limit: int = 200) -> List[dict]:
    """(question, sql) pairs a user confirmed with a thumbs-up, newest first.

    The learning loop (core/learned_examples.py) replays these as few-shot
    examples when a similar question arrives. Two safety rules live in the
    query itself:
      * only assistant messages whose meta actually carries the executed SQL
        count — a thumb on a prose answer teaches nothing about SQL;
      * any SQL text that ALSO received a thumbs-down anywhere is excluded
        outright. A query one user liked and another flagged is contested,
        and a contested example is worse than none.
    The question is the nearest earlier user turn in the same conversation —
    messages are keyed by position because offline sync rewrites their ids
    (see replace_messages).
    """
    with connection() as con:
        rows = con.execute(
            """
            WITH rated AS (
                SELECT m.id, m.conversation_id, m.meta->>'sql' AS sql
                  FROM messages m
                 WHERE m.feedback = 'up' AND m.role = 'assistant'
                   AND m.meta->>'sql' IS NOT NULL
                 ORDER BY m.feedback_at DESC NULLS LAST
                 LIMIT %s
            )
            SELECT r.sql,
                   (SELECT q.content FROM messages q
                     WHERE q.conversation_id = r.conversation_id
                       AND q.id < r.id AND q.role = 'user'
                     ORDER BY q.id DESC LIMIT 1) AS question
              FROM rated r
             WHERE NOT EXISTS (
                    SELECT 1 FROM messages b
                     WHERE b.feedback = 'down'
                       AND b.meta->>'sql' = r.sql
                   )
            """,
            (limit,),
        ).fetchall()
    examples = []
    for row in rows:
        question = (row["question"] or "").strip()
        sql = (row["sql"] or "").strip()
        if question and sql:
            examples.append({"question": question, "sql": sql})
    return examples


def conversation_owner(conversation_id: str) -> Optional[int]:
    """user_id owning this conversation, or None when no such row exists.

    Used to authorize the per-conversation stores (url_documents, repo_chunks,
    live generations) that are keyed by conversation id alone.
    """
    with connection() as con:
        row = con.execute(
            "SELECT user_id FROM conversations WHERE id = %s", (conversation_id,)
        ).fetchone()
    return int(row["user_id"]) if row else None


class MessageCountWouldShrink(Exception):
    """A sync tried to replace a thread with a SHORTER one.

    The client's offline sync used to reconcile a diverged tail by deleting
    the conversation and recreating it from its local copy. When that local
    copy was empty or stale (a chat listed by the server but never opened in
    this browser, or one evicted by a localStorage quota purge) the rebuild
    destroyed every earlier turn. Shrinking is never a legitimate sync
    outcome — only an explicit DELETE of the whole conversation is.
    """

    def __init__(self, existing: int, incoming: int) -> None:
        super().__init__(f"refusing to replace {existing} messages with {incoming}")
        self.existing = existing
        self.incoming = incoming


# ---------------------------------------------------------------------------
# Phase A/B: rolling summary + folded-turn chunks
# ---------------------------------------------------------------------------


def get_summary(conversation_id: str) -> Optional[dict]:
    with connection() as con:
        row = con.execute(
            "SELECT summary, covers_through, token_estimate, updated_at "
            "FROM conversation_summaries WHERE conversation_id = %s",
            (conversation_id,),
        ).fetchone()
    if row is None:
        return None
    return {
        "summary": row["summary"],
        "covers_through": int(row["covers_through"]),
        "token_estimate": int(row["token_estimate"]),
        "updated_at": _iso(row["updated_at"]),
    }


def save_summary(
    conversation_id: str, summary: str, covers_through: int, token_estimate: int
) -> None:
    with connection() as con:
        con.execute(
            "INSERT INTO conversation_summaries "
            "(conversation_id, summary, covers_through, token_estimate, updated_at) "
            "VALUES (%s, %s, %s, %s, %s) "
            "ON CONFLICT (conversation_id) DO UPDATE SET "
            "summary = excluded.summary, covers_through = excluded.covers_through, "
            "token_estimate = excluded.token_estimate, updated_at = excluded.updated_at",
            (conversation_id, _text(summary), covers_through, token_estimate, _now()),
        )


def clear_summary(conversation_id: str) -> None:
    """Drop the summary and folded chunks for a conversation.

    Used when the thread is truncated (a confirmed regenerate of an older
    answer): the summary describes turns that no longer exist, so keeping it
    would let the model assert things the user deliberately removed.
    """
    with connection() as con:
        con.execute(
            "DELETE FROM conversation_summaries WHERE conversation_id = %s",
            (conversation_id,),
        )
        con.execute(
            "DELETE FROM conversation_chunks WHERE conversation_id = %s",
            (conversation_id,),
        )


def add_conversation_chunks(conversation_id: str, chunks: List[dict]) -> None:
    """Store embedded chunks of folded turns (ordinal = index in the thread)."""
    if not chunks:
        return
    now = _now()
    with connection() as con:
        con.cursor().executemany(
            "INSERT INTO conversation_chunks "
            "(conversation_id, ordinal, role, text, embedding, created_at) "
            "VALUES (%s, %s, %s, %s, %s, %s) "
            "ON CONFLICT (conversation_id, ordinal) DO UPDATE SET "
            "role = excluded.role, text = excluded.text, "
            "embedding = excluded.embedding, created_at = excluded.created_at",
            [
                (
                    conversation_id,
                    int(c["ordinal"]),
                    _text(c["role"]),
                    _text(c["text"]),
                    c["embedding"],
                    now,
                )
                for c in chunks
            ],
        )


def get_conversation_chunks(conversation_id: str) -> List[dict]:
    """Every folded chunk for ONE conversation — the isolation boundary."""
    with connection() as con:
        rows = con.execute(
            "SELECT ordinal, role, text, embedding FROM conversation_chunks "
            "WHERE conversation_id = %s ORDER BY ordinal",
            (conversation_id,),
        ).fetchall()
    return [
        {
            "ordinal": int(r["ordinal"]),
            "role": r["role"],
            "text": r["text"],
            # bytea comes back as `memoryview`; recall.unpack_vector wants
            # something array.frombytes accepts, and callers may hold it past
            # the cursor, so materialise it.
            "embedding": bytes(r["embedding"]),
        }
        for r in rows
    ]


# ---------------------------------------------------------------------------
# Phase 4: uploaded datasets (profile stored, bytes expire separately)
# ---------------------------------------------------------------------------


def save_upload(
    upload_id: str,
    conversation_id: str,
    filename: str,
    size: int,
    status: str,
    profile: Optional[str] = None,
    notes: Optional[str] = None,
) -> None:
    with connection() as con:
        con.execute(
            "INSERT INTO uploads (id, conversation_id, filename, bytes, status, "
            "profile, notes, created_at) VALUES (%s, %s, %s, %s, %s, %s, %s, %s) "
            "ON CONFLICT (id) DO UPDATE SET status = excluded.status, "
            "profile = excluded.profile, notes = excluded.notes",
            (
                upload_id,
                conversation_id,
                _text(filename),
                size,
                status,
                _json_param(profile),
                _text(notes),
                _now(),
            ),
        )


def get_uploads(conversation_id: str) -> List[dict]:
    """Uploads for ONE conversation — the isolation boundary."""
    with connection() as con:
        rows = con.execute(
            "SELECT id, filename, bytes, status, profile, notes, created_at "
            "FROM uploads WHERE conversation_id = %s ORDER BY created_at",
            (conversation_id,),
        ).fetchall()
    return [
        {
            "id": r["id"],
            "filename": r["filename"],
            "bytes": int(r["bytes"]),
            "status": r["status"],
            "profile": r["profile"],
            "notes": r["notes"],
            "created_at": _iso(r["created_at"]),
        }
        for r in rows
    ]


def get_upload(upload_id: str) -> Optional[dict]:
    with connection() as con:
        row = con.execute(
            "SELECT id, conversation_id, filename, bytes, status, profile, notes "
            "FROM uploads WHERE id = %s",
            (upload_id,),
        ).fetchone()
    if row is None:
        return None
    return {
        "id": row["id"],
        "conversation_id": row["conversation_id"],
        "filename": row["filename"],
        "bytes": int(row["bytes"]),
        "status": row["status"],
        "profile": row["profile"],
        "notes": row["notes"],
    }


class ConversationChanged(Exception):
    """The stored thread is not the one the caller was looking at."""

    def __init__(self, expected: int, actual: int) -> None:
        super().__init__(f"expected {expected} messages, found {actual}")
        self.expected = expected
        self.actual = actual


def truncate_messages(
    user_id: int, conversation_id: str, keep: int, expected_total: int
) -> Optional[dict]:
    """Drop every message after the first `keep` — the ONE sanctioned shrink.

    This exists so a user-confirmed "regenerate an older answer" (which really
    does discard the turns after that point) does not need the sync path to be
    able to shrink. The separation is the safety property: the sync path can
    never reduce a thread, and this endpoint can only ever delete a tail — it
    cannot write content, so a bug here cannot rewrite history, only shorten
    it, and only when the caller proves it knows the current length.

    `expected_total` is optimistic concurrency: if another tab appended turns
    since the caller last looked, this raises instead of destroying them.

    FOR UPDATE on the owning row is new: SQLite's single-writer lock made the
    count-then-delete atomic for free, and MVCC does not. Without it two
    concurrent truncates can both read the same count and both pass the check.
    """
    with connection() as con:
        owned = con.execute(
            "SELECT 1 FROM conversations WHERE id = %s AND user_id = %s FOR UPDATE",
            (conversation_id, user_id),
        ).fetchone()
        if not owned:
            return None
        actual = int(
            con.execute(
                "SELECT COUNT(*) AS n FROM messages WHERE conversation_id = %s",
                (conversation_id,),
            ).fetchone()["n"]
        )
        if actual != expected_total:
            raise ConversationChanged(expected_total, actual)
        if keep >= actual:
            return {"id": conversation_id, "count": actual}
        # Find the id of the last message to KEEP, then range-delete past it.
        # The SQLite original used `id NOT IN (SELECT … LIMIT keep)`, which
        # PostgreSQL also accepts — but that re-scans every surviving row,
        # while this does one index probe and a range delete whose cost scales
        # with the rows actually removed. `keep == 0` has no boundary row, so
        # it deletes the lot.
        boundary = None
        if keep > 0:
            row = con.execute(
                "SELECT id FROM messages WHERE conversation_id = %s "
                "ORDER BY id OFFSET %s LIMIT 1",
                (conversation_id, keep - 1),
            ).fetchone()
            boundary = row["id"] if row else None
        if boundary is None:
            con.execute(
                "DELETE FROM messages WHERE conversation_id = %s", (conversation_id,)
            )
        else:
            con.execute(
                "DELETE FROM messages WHERE conversation_id = %s AND id > %s",
                (conversation_id, boundary),
            )
        con.execute(
            "UPDATE conversations SET updated_at = %s WHERE id = %s",
            (_now(), conversation_id),
        )
    return {"id": conversation_id, "count": keep}


class ThreadMoved(Exception):
    """The thread moved since the client last loaded it (V29 conditional
    replace): the server's `updated_at` is not the one the client expected.

    Deliberately NOT `ConversationChanged` — that name is taken, by the
    truncate guard above, which counts messages rather than comparing a
    version and whose handler reads `.expected`/`.actual`. Two exceptions
    with one name meant the truncate handler read this one's attributes and
    turned a 409 into a 500.
    """

    def __init__(self, updated_at: Any, count: int) -> None:
        super().__init__("conversation changed")
        self.updated_at = updated_at
        self.count = count


def replace_messages(
    user_id: int,
    conversation_id: str,
    messages: List[dict],
    *,
    expected_updated_at: Optional[str] = None,
) -> Optional[dict]:
    """Atomically replace a conversation's messages, never reducing the count.

    Returns None when the conversation is missing or owned by someone else,
    and raises MessageCountWouldShrink when the incoming thread is shorter
    than what is stored. The delete+insert runs in ONE transaction, so a
    failure cannot leave the conversation empty.

    FEEDBACK SURVIVES. This is a DELETE followed by an INSERT, so every row
    gets a new id — which would silently discard the thumbs on a thread the
    client happens to re-push (the offline sync does exactly that whenever the
    tail diverges). Thumbs are carried across BY POSITION, which is sound here
    precisely because of the guarantee above: this function can never reorder
    or shrink a thread, only append to it, so index N before is index N after.
    An explicit `feedback` on an incoming message wins over the carried value.
    """
    now = _now()
    with connection() as con:
        owned = con.execute(
            "SELECT updated_at FROM conversations WHERE id = %s AND user_id = %s FOR UPDATE",
            (conversation_id, user_id),
        ).fetchone()
        if not owned:
            return None
        existing = int(
            con.execute(
                "SELECT COUNT(*) AS n FROM messages WHERE conversation_id = %s",
                (conversation_id,),
            ).fetchone()["n"]
        )
        # V29: a client that says what it last saw only replaces that. An
        # older tab pushing a thread of the same length used to overwrite an
        # answer the server had persisted after the tab last loaded — the
        # count check cannot see a same-length replacement. The row lock
        # above makes the comparison and the write one step.
        if expected_updated_at is not None:
            current = _iso(owned["updated_at"]) if owned.get("updated_at") else None
            if str(expected_updated_at) != str(current):
                raise ThreadMoved(current, existing)
        if len(messages) < existing:
            raise MessageCountWouldShrink(existing, len(messages))
        # Snapshot the thumbs before the rows they belong to are deleted.
        carried = [
            r["feedback"]
            for r in con.execute(
                "SELECT feedback FROM messages WHERE conversation_id = %s ORDER BY id",
                (conversation_id,),
            ).fetchall()
        ]
        con.execute("DELETE FROM messages WHERE conversation_id = %s", (conversation_id,))
        seen_generations = set()
        rows = []
        for index, m in enumerate(messages):
            meta = m.get("meta")
            gen_id = (meta or {}).get("generation_id")
            # The unique index would reject a repeated key; a client sending
            # one twice is a bug on its side, not a reason to 500 — keep the
            # first and store the rest unkeyed.
            if gen_id:
                if gen_id in seen_generations:
                    gen_id = None
                else:
                    seen_generations.add(gen_id)
            feedback = m.get("feedback")
            if feedback not in FEEDBACK_VALUES:
                # Not supplied (or junk) — keep whatever was on this position.
                feedback = carried[index] if index < len(carried) else None
            rows.append(
                (
                    conversation_id,
                    _text(m.get("role", "")),
                    _text(m.get("content", "")),
                    _json_param(meta),
                    now,
                    str(gen_id) if gen_id else None,
                    feedback,
                    now if feedback else None,
                )
            )
        if rows:
            con.cursor().executemany(
                "INSERT INTO messages (conversation_id, role, content, meta, created_at, "
                "generation_id, feedback, feedback_at) "
                "VALUES (%s, %s, %s, %s, %s, %s, %s, %s)",
                rows,
            )
        con.execute(
            "UPDATE conversations SET updated_at = %s WHERE id = %s",
            (now, conversation_id),
        )
    return {"id": conversation_id, "count": len(messages)}


def add_message(
    user_id: int,
    conversation_id: str,
    role: str,
    content: str,
    meta: Optional[dict] = None,
    *,
    replace_existing: bool = False,
) -> Optional[dict]:
    """Append a message to a conversation the user owns; bumps updated_at.

    Returns None when the conversation is missing or owned by someone else.

    IDEMPOTENT per generation: when `meta.generation_id` is present and a
    message from that same generation already exists here, the existing row is
    returned untouched. Two clients attached to one detached generation (a
    second browser opening a running answer) both finalize and both push —
    without this the same reply is stored twice.
    """
    now = _now()
    generation_id = (meta or {}).get("generation_id")
    with connection() as con:
        owned = con.execute(
            "SELECT 1 FROM conversations WHERE id = %s AND user_id = %s",
            (conversation_id, user_id),
        ).fetchone()
        if not owned:
            return None

        # PostgreSQL aborts the whole transaction on a constraint violation, so
        # the SQLite shape (try INSERT / except IntegrityError / SELECT the
        # winner on the same connection) cannot work here — the follow-up
        # SELECT would fail with "current transaction is aborted". A SAVEPOINT
        # scopes the rollback to the INSERT alone.
        inserted = None
        try:
            with con.transaction():
                inserted = con.execute(
                    "INSERT INTO messages (conversation_id, role, content, meta, "
                    "created_at, generation_id) VALUES (%s, %s, %s, %s, %s, %s) "
                    "RETURNING id",
                    (
                        conversation_id,
                        _text(role),
                        _text(content),
                        _json_param(meta),
                        now,
                        str(generation_id) if generation_id else None,
                    ),
                ).fetchone()
        except UniqueViolation:
            # The unique index rejected it: another client stored this exact
            # generation first. Hand back the row that won — no duplicate.
            if not generation_id:
                raise
            if replace_existing:
                # V29: the server's own write of a finished answer wins over a
                # placeholder a client stored under the same generation (a
                # failure record, an interrupted stub): same row, new body.
                con.execute(
                    "UPDATE messages SET content = %s, meta = %s "
                    "WHERE conversation_id = %s AND generation_id = %s",
                    (_text(content), _json_param(meta), conversation_id, str(generation_id)),
                )
            row = con.execute(
                "SELECT id, role, content, meta, created_at FROM messages "
                "WHERE conversation_id = %s AND generation_id = %s",
                (conversation_id, str(generation_id)),
            ).fetchone()
            if row is None:
                raise
            return {
                "id": int(row["id"]),
                "role": row["role"],
                "content": row["content"],
                "meta": row["meta"],
                "created_at": _iso(row["created_at"]),
                "deduplicated": True,
            }

        con.execute(
            "UPDATE conversations SET updated_at = %s WHERE id = %s",
            (now, conversation_id),
        )
        message_id = int(inserted["id"])
    return {
        "id": message_id,
        "role": role,
        "content": content,
        "meta": meta,
        "created_at": now.isoformat(),
    }


# ---------------------------------------------------------------------------
# Phase 2: fetched-page storage (per conversation, so follow-ups don't refetch)
# ---------------------------------------------------------------------------


def save_url_document(conversation_id: str, url: str, title: str, text: str) -> None:
    """Store (or refresh) an extracted page for a conversation."""
    with connection() as con:
        con.execute(
            "INSERT INTO url_documents (conversation_id, url, title, text, fetched_at) "
            "VALUES (%s, %s, %s, %s, %s) "
            "ON CONFLICT (conversation_id, url) DO UPDATE SET "
            "title = excluded.title, text = excluded.text, "
            "fetched_at = excluded.fetched_at",
            (conversation_id, _text(url), _text(title), _text(text), _now()),
        )


def get_url_documents(conversation_id: str) -> List[dict]:
    """All pages stored for a conversation, oldest first."""
    with connection() as con:
        rows = con.execute(
            "SELECT url, title, text FROM url_documents "
            "WHERE conversation_id = %s ORDER BY id",
            (conversation_id,),
        ).fetchall()
    return [{"url": r["url"], "title": r["title"], "text": r["text"]} for r in rows]


def get_url_document_urls(conversation_id: str) -> set:
    """The set of URLs already fetched for a conversation (dupe check)."""
    with connection() as con:
        rows = con.execute(
            "SELECT url FROM url_documents WHERE conversation_id = %s",
            (conversation_id,),
        ).fetchall()
    return {r["url"] for r in rows}


def save_document(
    conversation_id: str, filename: str, text: str, total_pages: int = 0
) -> None:
    """Store (or refresh) an uploaded document's extracted text."""
    with connection() as con:
        con.execute(
            "INSERT INTO documents (conversation_id, filename, text, total_pages, "
            "created_at) VALUES (%s, %s, %s, %s, %s) "
            "ON CONFLICT (conversation_id, filename) DO UPDATE SET "
            "text = excluded.text, total_pages = excluded.total_pages, "
            "created_at = excluded.created_at",
            (conversation_id, _text(filename), _text(text), total_pages, _now()),
        )


def get_documents(conversation_id: str) -> List[dict]:
    """All documents stored for a conversation, oldest first."""
    with connection() as con:
        rows = con.execute(
            "SELECT filename, text, total_pages FROM documents "
            "WHERE conversation_id = %s ORDER BY id",
            (conversation_id,),
        ).fetchall()
    return [
        {"filename": r["filename"], "text": r["text"], "total_pages": r["total_pages"]}
        for r in rows
    ]


# ---------------------------------------------------------------------------
# Phase 3: repo + code-chunk storage (per conversation)
# ---------------------------------------------------------------------------


def save_repo(conversation_id: str, repo_key: str, url: str, sha: str) -> None:
    with connection() as con:
        con.execute(
            "INSERT INTO repos (conversation_id, repo_key, url, sha, cloned_at) "
            "VALUES (%s, %s, %s, %s, %s) "
            "ON CONFLICT (conversation_id, repo_key) DO UPDATE SET "
            "url = excluded.url, sha = excluded.sha, cloned_at = excluded.cloned_at",
            (conversation_id, _text(repo_key), _text(url), _text(sha), _now()),
        )


def get_repo(conversation_id: str, repo_key: str) -> Optional[dict]:
    with connection() as con:
        row = con.execute(
            "SELECT repo_key, url, sha FROM repos "
            "WHERE conversation_id = %s AND repo_key = %s",
            (conversation_id, repo_key),
        ).fetchone()
    return dict(row) if row else None


def get_repo_keys(conversation_id: str) -> List[str]:
    with connection() as con:
        rows = con.execute(
            "SELECT repo_key FROM repos WHERE conversation_id = %s ORDER BY id",
            (conversation_id,),
        ).fetchall()
    return [r["repo_key"] for r in rows]


def replace_repo_chunks(
    conversation_id: str, repo_key: str, chunks: List[dict]
) -> None:
    """Store a repo's code chunks, replacing any previous set for that repo."""
    with connection() as con:
        con.execute(
            "DELETE FROM repo_chunks WHERE conversation_id = %s AND repo_key = %s",
            (conversation_id, repo_key),
        )
        if not chunks:
            return
        # COPY, not executemany: indexing a repo writes thousands of rows in one
        # go, and COPY streams them in a single statement instead of a round
        # trip apiece.
        with con.cursor().copy(
            "COPY repo_chunks (conversation_id, repo_key, path, start_line, end_line, "
            "text) FROM STDIN"
        ) as copy:
            for c in chunks:
                copy.write_row(
                    (
                        conversation_id,
                        repo_key,
                        _text(c["path"]),
                        c["start_line"],
                        c["end_line"],
                        _text(c["text"]),
                    )
                )


def search_repo_chunks(
    conversation_id: str, keywords: List[str], limit: int = 12
) -> List[dict]:
    """Code chunks in the conversation's repos matching any keyword, ranked by
    number of matching keywords (path matches weighted). Returns
    [{path, start_line, end_line, text}]."""
    if not keywords:
        return []
    patterns = [like_contains_pattern(k) for k in keywords]
    # score = matches in text + 2x matches in path (path names are strong signal)
    score_terms = " + ".join(
        "(CASE WHEN text ILIKE %s ESCAPE '\\' THEN 1 ELSE 0 END) + "
        "(CASE WHEN path ILIKE %s ESCAPE '\\' THEN 2 ELSE 0 END)"
        for _ in keywords
    )
    like_any = " OR ".join(
        "text ILIKE %s ESCAPE '\\' OR path ILIKE %s ESCAPE '\\'" for _ in keywords
    )
    # Doc files (README/HISTORY/…) often mention a term in prose; for "where is
    # X handled" the real source file should win, so penalize docs a little.
    doc_penalty = (
        "(CASE WHEN lower(path) LIKE '%%.md' OR lower(path) LIKE '%%.rst' "
        "OR lower(path) LIKE '%%.txt' OR lower(path) LIKE '%%.markdown' "
        "THEN 2 ELSE 0 END)"
    )
    sql = (
        f"SELECT path, start_line, end_line, text, "
        f"(({score_terms}) - {doc_penalty}) AS score "
        "FROM repo_chunks WHERE conversation_id = %s "
        f"AND ({like_any}) ORDER BY score DESC, id LIMIT %s"
    )
    # Bind in the ORDER the %s placeholders appear in the SQL text:
    # score_terms (SELECT) → conversation_id (WHERE) → like_any (AND) → limit.
    params: List[object] = []
    for p in patterns:
        params += [p, p]  # score_terms
    params.append(conversation_id)
    for p in patterns:
        params += [p, p]  # like_any
    params.append(limit)
    with connection() as con:
        rows = con.execute(sql, params).fetchall()
    return [
        {
            "path": r["path"],
            "start_line": r["start_line"],
            "end_line": r["end_line"],
            "text": r["text"],
        }
        for r in rows
    ]


# ---------------------------------------------------------------------------
# Search (V4-DESIGN §2) — one row per conversation, matched on the title or on
# any message body, scoped to the owner like every other accessor here.
# ---------------------------------------------------------------------------

SEARCH_LIMIT_DEFAULT = 50
SEARCH_LIMIT_MAX = 100  # hard cap: a bigger ?limit is clamped, never an error

_LIKE_ESCAPE = "\\"
_SNIPPET_WIDTH = 120
_ELLIPSIS = "…"


def like_contains_pattern(needle: str) -> str:
    """`needle` as a literal LIKE "contains" pattern.

    The user's text is data, not syntax: `%`, `_` and the escape character
    itself are escaped so searching for "50%" or "q_1" matches those literal
    characters instead of turning into a wildcard. Every statement using this
    pattern MUST pair it with the matching ESCAPE clause (see _SEARCH_SQL) —
    without one, PostgreSQL still treats `\\` as the default escape, but being
    explicit is what keeps the behaviour identical if that ever changes.
    """
    escaped = (
        needle.replace(_LIKE_ESCAPE, _LIKE_ESCAPE * 2)
        .replace("%", _LIKE_ESCAPE + "%")
        .replace("_", _LIKE_ESCAPE + "_")
    )
    return f"%{escaped}%"


def snippet_window(content: str, needle: str, width: int = _SNIPPET_WIDTH) -> str:
    """A ~`width`-character window of `content` centered on the first
    case-insensitive occurrence of `needle`.

    Short messages come back whole; a trimmed end gets an ellipsis so the
    palette can show that the message continues. When the hit sits near the
    tail the window is slid back so it stays `width` wide instead of running
    short. `needle` not being found is not an error (SQL's LIKE and Python's
    casefolding can disagree on exotic characters) — the head of the message is
    a reasonable snippet in that case.
    """
    if len(content) <= width:
        return content
    hit = content.lower().find(needle.lower())
    center = 0 if hit < 0 else hit + len(needle) // 2
    start = max(0, center - width // 2)
    end = min(len(content), start + width)
    start = max(0, end - width)  # re-widen when the hit sits near the tail
    snippet = content[start:end]
    if start > 0:
        snippet = _ELLIPSIS + snippet
    if end < len(content):
        snippet = snippet + _ELLIPSIS
    return snippet


# ILIKE, not LIKE. SQLite's LIKE is case-INSENSITIVE for ASCII, so a verbatim
# port silently stops matching anything capitalised — searching "merger" would
# miss a chat titled "Merger". The `gin_trgm_ops` indexes on `messages.content`
# and `conversations.title` serve ILIKE too, so this costs nothing.
# ESCAPE '\' is what makes like_contains_pattern's escaping real.
#
# The QUERY SHAPE is deliberately unchanged from the SQLite original — the
# correlated subquery that looks like it should be rewritten. It was rewritten,
# as a single-pass `DISTINCT ON` CTE, and then reverted, because the rewrite is
# only faster on a corpus small enough for the difference not to matter.
# Measured on 200,000 messages / 10,000 conversations:
#
#                        selective needle   needle matching everything
#   correlated (this)          2.5 ms                80 ms
#   DISTINCT ON CTE            7.8 ms                61 ms
#
# The correlated form wins 3x on the SELECTIVE case — a user searching their
# own history types a distinctive word. EXPLAIN shows why, and it is NOT
# short-circuiting: PostgreSQL de-correlates the EXISTS into a *hashed* SubPlan
# evaluated once against idx_messages_content_trgm. When that hash holds a
# handful of ids the outer walk discards almost everything cheaply and the
# per-row snippet subquery runs only for the survivors. The CTE instead has to
# materialise every match and SORT it for `DISTINCT ON` before it can return a
# single row, which only pays off when nearly everything matches. On the
# 378-message live database the two are within 1 ms, so the small-scale
# benchmark that motivated the rewrite was measuring noise.
#
# Archived conversations are deliberately NOT filtered out — they come back
# flagged so the palette can label them (§2).
_SEARCH_SQL = """
SELECT c.id, c.title, c.updated_at, c.pinned, c.archived,
       (SELECT m.content
          FROM messages m
         WHERE m.conversation_id = c.id
           AND m.content ILIKE %(pattern)s ESCAPE '\\'
         ORDER BY m.id
         LIMIT 1) AS match_content
  FROM conversations c
 WHERE c.user_id = %(user_id)s
   AND (c.title ILIKE %(pattern)s ESCAPE '\\'
        OR EXISTS (SELECT 1
                     FROM messages m2
                    WHERE m2.conversation_id = c.id
                      AND m2.content ILIKE %(pattern)s ESCAPE '\\'))
 ORDER BY c.pinned DESC, c.updated_at DESC, c.seq DESC
 LIMIT %(limit)s
"""


_RECALL_SNIPPET_CHARS = 240


def recall_conversations(
    user_id: int,
    keywords: List[str],
    exclude_conversation_id: Optional[str],
    limit: int = 3,
) -> List[dict]:
    """Cross-chat memory: the user's OTHER conversations whose messages mention
    any of `keywords`, ranked by how many messages match. Returns
    [{id, title, snippet}] — a compact recall context for the model. Scoped to
    the owner like every accessor here; the current conversation is excluded.

    One statement, not the old rank-then-snippet-per-row pair: LATERAL fetches
    each winner's snippet in the same pass, so this no longer issues N+1
    queries (it was 1 + `limit` round trips, each paying the old connect() tax).
    """
    if not keywords:
        return []
    patterns = [like_contains_pattern(k) for k in keywords]
    like_any = " OR ".join("m.content ILIKE %s ESCAPE '\\'" for _ in keywords)
    snippet_any = " OR ".join("s.content ILIKE %s ESCAPE '\\'" for _ in keywords)
    # The FIRST matching message in a conversation is almost always the user's
    # own question ("who is the CEO?"), which carries no information — handing
    # it back as recall told the model nothing. Prefer the message matching the
    # most keywords and, among ties, the most recent: that is where the answer
    # (or the fact the user supplied) actually lives.
    snippet_score = " + ".join(
        "(CASE WHEN s.content ILIKE %s ESCAPE '\\' THEN 1 ELSE 0 END)"
        for _ in keywords
    )
    sql = (
        "WITH ranked AS ("
        "  SELECT c.id, c.title, c.updated_at, COUNT(m.id) AS hits"
        "    FROM conversations c JOIN messages m ON m.conversation_id = c.id"
        f"   WHERE c.user_id = %s AND c.id <> %s AND ({like_any})"
        "   GROUP BY c.id, c.title, c.updated_at"
        "   ORDER BY hits DESC, c.updated_at DESC"
        "   LIMIT %s"
        ") "
        "SELECT ranked.id, ranked.title, snip.role, snip.content "
        "  FROM ranked "
        "  LEFT JOIN LATERAL ("
        "    SELECT s.role, s.content FROM messages s"
        f"    WHERE s.conversation_id = ranked.id AND ({snippet_any})"
        f"     ORDER BY ({snippet_score}) DESC, s.id DESC LIMIT 1"
        "  ) AS snip ON true "
        " ORDER BY ranked.hits DESC, ranked.updated_at DESC"
    )
    params: List[object] = [user_id, exclude_conversation_id or "", *patterns, limit]
    params += patterns  # snippet_any (LATERAL WHERE)
    params += patterns  # snippet_score (LATERAL ORDER BY)
    with connection() as con:
        rows = con.execute(sql, params).fetchall()
    out: List[dict] = []
    for r in rows:
        content = (r["content"] or "").strip().replace("\n", " ")
        if len(content) > _RECALL_SNIPPET_CHARS:
            content = content[:_RECALL_SNIPPET_CHARS] + "…"
        out.append(
            {
                "id": r["id"],
                "title": r["title"],
                "role": r["role"],
                "snippet": content,
            }
        )
    return out


def search_conversations(
    user_id: int, query: str, limit: int = SEARCH_LIMIT_DEFAULT
) -> List[dict]:
    """The user's conversations matching `query` in the title or any message.

    Returns the documented row shape: {id, title, updated_at, pinned, archived,
    snippet, matched_in}. `matched_in` is "message" whenever some message body
    matched (the snippet then windows the FIRST such message) and "title" only
    when the title alone matched — so `snippet is None` exactly when
    `matched_in == "title"`, which is the invariant the palette renders on.
    """
    query = query.strip()
    if not query:  # empty/whitespace query is a no-op, not an error (§2)
        return []
    limit = max(1, min(int(limit), SEARCH_LIMIT_MAX))
    with connection() as con:
        rows = con.execute(
            _SEARCH_SQL,
            {
                "pattern": like_contains_pattern(query),
                "user_id": user_id,
                "limit": limit,
            },
        ).fetchall()
    out: List[dict] = []
    for row in rows:
        match_content = row["match_content"]
        out.append(
            {
                "id": row["id"],
                "title": row["title"],
                "updated_at": _iso(row["updated_at"]),
                "pinned": bool(row["pinned"]),
                "archived": bool(row["archived"]),
                "snippet": (
                    snippet_window(match_content, query)
                    if match_content is not None
                    else None
                ),
                "matched_in": "message" if match_content is not None else "title",
            }
        )
    return out


# ---------------------------------------------------------------------------
# Salesforce Intelligence Mode (migration 5)
#
# Three tables, one job: make a clarifying question survive everything that can
# happen between asking it and getting an answer — a reload, a second tab, a
# reconnect, an orchestrator restart. Payloads are stored whole as jsonb and
# validated by pydantic at the edges (app/core/sf_intel/state.py); this layer
# only moves rows and enforces the two invariants that MUST be atomic:
# one pending clarification per conversation, and first-response-wins.
# ---------------------------------------------------------------------------


def save_sf_intent(
    intent_id: str, conversation_id: str, status: str, payload: dict
) -> None:
    """Insert or update one pending intent."""
    now = _now()
    with connection() as con:
        con.execute(
            "INSERT INTO sf_intents "
            "(intent_id, conversation_id, status, payload, created_at, updated_at) "
            "VALUES (%s, %s, %s, %s, %s, %s) "
            "ON CONFLICT (intent_id) DO UPDATE SET "
            "  status = EXCLUDED.status, payload = EXCLUDED.payload, "
            "  updated_at = EXCLUDED.updated_at",
            (intent_id, conversation_id, status, _json_param(payload), now, now),
        )


def get_sf_intent(intent_id: str) -> Optional[dict]:
    with connection() as con:
        row = con.execute(
            "SELECT intent_id, conversation_id, status, payload FROM sf_intents "
            "WHERE intent_id = %s",
            (intent_id,),
        ).fetchone()
    return _row(row) if row else None


def latest_open_sf_intent(conversation_id: str) -> Optional[dict]:
    """The most recent intent for this conversation that is not finished."""
    with connection() as con:
        row = con.execute(
            "SELECT intent_id, conversation_id, status, payload FROM sf_intents "
            "WHERE conversation_id = %s AND status IN ('open', 'awaiting_clarification') "
            "ORDER BY updated_at DESC LIMIT 1",
            (conversation_id,),
        ).fetchone()
    return _row(row) if row else None


def close_sf_intents(conversation_id: str, status: str = "cancelled") -> int:
    """Finish every open intent for a conversation. Returns how many."""
    with connection() as con:
        cur = con.execute(
            "UPDATE sf_intents SET status = %s, updated_at = %s "
            "WHERE conversation_id = %s AND status IN ('open', 'awaiting_clarification')",
            (status, _now(), conversation_id),
        )
        return cur.rowcount


def create_sf_clarification(
    *,
    clarification_id: str,
    conversation_id: str,
    intent_id: str,
    resume_token: str,
    question_fingerprint: str,
    payload: dict,
) -> bool:
    """Persist a pending clarification. False when one is already pending.

    The conflict target is the PARTIAL unique index, so this is the database
    enforcing "one open question per conversation" rather than a read-then-write
    that two racing sends both win.
    """
    with connection() as con:
        cur = con.execute(
            "INSERT INTO sf_clarifications "
            "(clarification_id, conversation_id, intent_id, state, resume_token, "
            " question_fingerprint, payload, created_at) "
            "VALUES (%s, %s, %s, 'pending', %s, %s, %s, %s) "
            "ON CONFLICT (conversation_id) WHERE state = 'pending' DO NOTHING",
            (
                clarification_id,
                conversation_id,
                intent_id,
                resume_token,
                question_fingerprint,
                _json_param(payload),
                _now(),
            ),
        )
        return cur.rowcount == 1


def _clarification_dict(row: Dict[str, Any]) -> dict:
    out = _row(row) or {}
    return {
        "clarification_id": out.get("clarification_id"),
        "conversation_id": out.get("conversation_id"),
        "intent_id": out.get("intent_id"),
        "state": out.get("state"),
        "resume_token": out.get("resume_token"),
        "question_fingerprint": out.get("question_fingerprint"),
        "payload": out.get("payload") or {},
        "response": out.get("response"),
        "client_message_id": out.get("client_message_id"),
        "created_at": _iso(out.get("created_at")),
        "resolved_at": _iso(out.get("resolved_at")),
    }


_CLARIFICATION_COLUMNS = (
    "clarification_id, conversation_id, intent_id, state, resume_token, "
    "question_fingerprint, payload, response, client_message_id, created_at, resolved_at"
)


def get_sf_clarification(clarification_id: str) -> Optional[dict]:
    with connection() as con:
        row = con.execute(
            f"SELECT {_CLARIFICATION_COLUMNS} FROM sf_clarifications "
            "WHERE clarification_id = %s",
            (clarification_id,),
        ).fetchone()
    return _clarification_dict(row) if row else None


def pending_sf_clarification(conversation_id: str) -> Optional[dict]:
    """The open question for this conversation, or None."""
    with connection() as con:
        row = con.execute(
            f"SELECT {_CLARIFICATION_COLUMNS} FROM sf_clarifications "
            "WHERE conversation_id = %s AND state = 'pending' "
            "ORDER BY created_at DESC LIMIT 1",
            (conversation_id,),
        ).fetchone()
    return _clarification_dict(row) if row else None


def resolve_sf_clarification(
    clarification_id: str,
    *,
    state: str,
    response: dict,
    client_message_id: Optional[str] = None,
) -> Tuple[Optional[dict], bool]:
    """Answer a pending clarification. → (row, was_already_resolved).

    ONE statement decides the race. `WHERE state = 'pending'` inside the UPDATE
    is what makes the first response win: a double-clicked option, or the same
    fetch retried after a timeout, matches zero rows the second time and gets
    the stored answer back instead of starting a second generation.
    """
    with connection() as con:
        row = con.execute(
            f"UPDATE sf_clarifications SET state = %s, response = %s, "
            "client_message_id = %s, resolved_at = %s "
            f"WHERE clarification_id = %s AND state = 'pending' RETURNING {_CLARIFICATION_COLUMNS}",
            (
                state,
                _json_param(response),
                client_message_id,
                _now(),
                clarification_id,
            ),
        ).fetchone()
        if row is not None:
            return _clarification_dict(row), False
        existing = con.execute(
            f"SELECT {_CLARIFICATION_COLUMNS} FROM sf_clarifications "
            "WHERE clarification_id = %s",
            (clarification_id,),
        ).fetchone()
    if existing is None:
        return None, False
    return _clarification_dict(existing), True


def cancel_sf_clarifications(conversation_id: str) -> int:
    """Cancel every pending question for a conversation (source turned off,
    a clear new topic, the conversation deleted). Returns how many."""
    with connection() as con:
        cur = con.execute(
            "UPDATE sf_clarifications SET state = 'cancelled', resolved_at = %s "
            "WHERE conversation_id = %s AND state = 'pending'",
            (_now(), conversation_id),
        )
        return cur.rowcount


def save_sf_conversation_state(conversation_id: str, payload: dict) -> None:
    with connection() as con:
        con.execute(
            "INSERT INTO sf_conversation_state (conversation_id, payload, updated_at) "
            "VALUES (%s, %s, %s) "
            "ON CONFLICT (conversation_id) DO UPDATE SET "
            "  payload = EXCLUDED.payload, updated_at = EXCLUDED.updated_at",
            (conversation_id, _json_param(payload), _now()),
        )


def get_sf_conversation_state(conversation_id: str) -> Optional[dict]:
    with connection() as con:
        row = con.execute(
            "SELECT payload FROM sf_conversation_state WHERE conversation_id = %s",
            (conversation_id,),
        ).fetchone()
    if row is None:
        return None
    return (_row(row) or {}).get("payload") or {}


# --- Cross-chat memory (V6): user facts + message embeddings -----------------


def list_user_facts(user_id: int, limit: int = 500) -> List[dict]:
    """The user's durable facts, most recently updated first."""
    with connection() as con:
        rows = con.execute(
            "SELECT id, fact, source_conversation_id, created_at, updated_at"
            "  FROM user_facts WHERE user_id = %s"
            " ORDER BY updated_at DESC, id DESC LIMIT %s",
            (user_id, limit),
        ).fetchall()
    return [
        {
            "id": int(r["id"]),
            "fact": r["fact"],
            "source_conversation_id": r["source_conversation_id"],
            "created_at": _iso(r["created_at"]),
            "updated_at": _iso(r["updated_at"]),
        }
        for r in rows
    ]


def add_user_fact(
    user_id: int, fact: str, source_conversation_id: Optional[str] = None
) -> dict:
    now = _now()
    with connection() as con:
        row = con.execute(
            "INSERT INTO user_facts"
            " (user_id, fact, source_conversation_id, created_at, updated_at)"
            " VALUES (%s, %s, %s, %s, %s)"
            " ON CONFLICT (user_id, lower(fact)) DO NOTHING RETURNING id",
            (user_id, _text(fact), source_conversation_id, now, now),
        ).fetchone()
        if row is None:  # a concurrent extraction stored the same fact first
            row = con.execute(
                "SELECT id FROM user_facts"
                " WHERE user_id = %s AND lower(fact) = lower(%s)",
                (user_id, _text(fact)),
            ).fetchone()
    return {
        "id": int(row["id"]),
        "fact": fact,
        "source_conversation_id": source_conversation_id,
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
    }


def update_user_fact(user_id: int, fact_id: int, fact: str) -> Optional[dict]:
    """Rewrite one fact. None when the id is missing or another user's (§3c)."""
    now = _now()
    with connection() as con:
        row = con.execute(
            "UPDATE user_facts SET fact = %s, updated_at = %s"
            " WHERE id = %s AND user_id = %s RETURNING id",
            (_text(fact), now, fact_id, user_id),
        ).fetchone()
    if row is None:
        return None
    return {"id": int(row["id"]), "fact": fact, "updated_at": now.isoformat()}


def delete_user_fact(user_id: int, fact_id: int) -> bool:
    with connection() as con:
        row = con.execute(
            "DELETE FROM user_facts WHERE id = %s AND user_id = %s RETURNING id",
            (fact_id, user_id),
        ).fetchone()
    return row is not None


def messages_missing_embeddings(
    user_id: int, model_id: str, limit: int = 64, min_chars: int = 15
) -> List[dict]:
    """Newest stored chat messages that have no embedding row yet.

    Newest-first so fresh conversations become searchable immediately; the
    older backlog drains a batch per request.
    """
    with connection() as con:
        rows = con.execute(
            "SELECT m.id, m.conversation_id, m.role, m.content"
            "  FROM messages m JOIN conversations c ON c.id = m.conversation_id"
            " WHERE c.user_id = %s AND m.role IN ('user', 'assistant')"
            "   AND length(m.content) >= %s"
            "   AND NOT EXISTS (SELECT 1 FROM message_embeddings e"
            "                    WHERE e.message_id = m.id AND e.model_id = %s)"
            " ORDER BY m.id DESC LIMIT %s",
            (user_id, min_chars, model_id, limit),
        ).fetchall()
    return [
        {
            "id": int(r["id"]),
            "conversation_id": r["conversation_id"],
            "role": r["role"],
            "content": r["content"],
        }
        for r in rows
    ]


def store_message_embeddings(
    user_id: int, model_id: str, dim: int, rows: List[dict]
) -> int:
    """Insert packed-float32 vectors; racing duplicates are ignored."""
    if not rows:
        return 0
    now = _now()
    with connection() as con:
        cur = con.cursor()
        cur.executemany(
            "INSERT INTO message_embeddings"
            " (message_id, user_id, conversation_id, model_id, dim, embedding,"
            "  created_at)"
            " VALUES (%s, %s, %s, %s, %s, %s, %s)"
            " ON CONFLICT (message_id, model_id) DO NOTHING",
            [
                (
                    r["message_id"],
                    user_id,
                    r["conversation_id"],
                    model_id,
                    dim,
                    r["embedding"],
                    now,
                )
                for r in rows
            ],
        )
        inserted = cur.rowcount
    return max(inserted, 0)


def fetch_message_embeddings(
    user_id: int,
    model_id: str,
    exclude_conversation_id: Optional[str],
    limit: int = 500,
) -> List[dict]:
    """Embedding candidates from the user's OTHER conversations, newest first.

    Scoped to the owner inside the statement like every accessor here; the
    current conversation is excluded because within-chat context is already
    in the prompt.
    """
    with connection() as con:
        rows = con.execute(
            "SELECT e.message_id, e.conversation_id, e.embedding,"
            "       m.role, m.content, c.title"
            "  FROM message_embeddings e"
            "  JOIN messages m ON m.id = e.message_id"
            "  JOIN conversations c ON c.id = e.conversation_id"
            " WHERE e.user_id = %s AND e.model_id = %s"
            "   AND e.conversation_id <> %s"
            " ORDER BY e.message_id DESC LIMIT %s",
            (user_id, model_id, exclude_conversation_id or "", limit),
        ).fetchall()
    return [
        {
            "message_id": int(r["message_id"]),
            "conversation_id": r["conversation_id"],
            "embedding": bytes(r["embedding"]),
            "role": r["role"],
            "content": r["content"],
            "title": r["title"],
        }
        for r in rows
    ]


def web_corpus_counts() -> dict:
    """Size, embedding backlog and refresh backlog of the public web corpus.

    One query rather than three: this runs on every Prometheus scrape.
    """
    with connection() as con:
        row = con.execute(
            """SELECT count(*) AS pages,
                      count(*) FILTER (WHERE indexed_at IS NULL) AS pending,
                      count(*) FILTER (WHERE next_refresh_at IS NOT NULL
                                         AND next_refresh_at <= now()) AS due
                 FROM web_pages"""
        ).fetchone()
    return {
        "pages": int(row["pages"]) if row else 0,
        "pending": int(row["pending"]) if row else 0,
        "due": int(row["due"]) if row else 0,
    }


# ---------------------------------------------------------------------------
# Conversation sharing (V20)
#
# The public read path is deliberately ONE query against two tables that hold
# nothing private. It never touches `messages`: a public request has no join
# to private data at all, which is a stronger property than any filter.
# ---------------------------------------------------------------------------


def share_for_conversation(conversation_id: str) -> Optional[dict]:
    """The ACTIVE share for a conversation, or None. Owner-facing."""
    with connection() as con:
        row = con.execute(
            """SELECT s.*, v.version_number, v.message_count, v.last_message_id,
                      v.created_at AS version_created_at
                 FROM conversation_shares s
                 LEFT JOIN conversation_share_versions v ON v.id = s.current_version
                WHERE s.conversation_id = %s AND s.status = 'active'""",
            (conversation_id,),
        ).fetchone()
    return dict(row) if row else None


def share_by_public_id(public_id: str) -> Optional[dict]:
    """The row a public link addresses, with its live payload.

    Returns the share whatever its status: the CALLER decides what a revoked
    or expired share means, so that every failure can be answered
    identically. Distinguishing them here would leak which links ever existed.
    """
    with connection() as con:
        row = con.execute(
            """SELECT s.id, s.public_id, s.secret_hash, s.visibility, s.status,
                      s.expires_at, s.workspace_id, s.show_owner_name,
                      s.created_at, v.payload, v.version_number
                 FROM conversation_shares s
                 LEFT JOIN conversation_share_versions v ON v.id = s.current_version
                WHERE s.public_id = %s""",
            (public_id,),
        ).fetchone()
    return dict(row) if row else None


def create_share(
    *,
    conversation_id: str,
    workspace_id: str,
    created_by: int,
    public_id: str,
    secret_hash: str,
    visibility: str,
    expires_at: Optional[datetime],
    show_owner_name: bool,
    payload: dict,
    content_hash: str,
    last_message_id: Optional[int],
    message_count: int,
) -> Optional[dict]:
    """Create a share and its first version, atomically.

    Returns None when an active share already exists — the partial unique
    index decides that, not a prior SELECT, so two clicks racing each other
    cannot both win.
    """
    now = _now()
    with connection() as con:
        try:
            share = con.execute(
                """INSERT INTO conversation_shares
                       (conversation_id, workspace_id, created_by, public_id,
                        secret_hash, visibility, status, show_owner_name,
                        expires_at, created_at, updated_at)
                   VALUES (%s, %s, %s, %s, %s, %s, 'active', %s, %s, %s, %s)
                   ON CONFLICT DO NOTHING
                   RETURNING id""",
                (conversation_id, workspace_id, created_by, public_id, secret_hash,
                 visibility, show_owner_name, expires_at, now, now),
            ).fetchone()
            if share is None:
                return None
            share_id = int(share["id"])
            version = con.execute(
                """INSERT INTO conversation_share_versions
                       (share_id, version_number, payload, content_hash,
                        last_message_id, message_count, created_by, created_at)
                   VALUES (%s, 1, %s, %s, %s, %s, %s, %s)
                   RETURNING id""",
                (share_id, _json_param(payload), content_hash, last_message_id,
                 message_count, created_by, now),
            ).fetchone()
            con.execute(
                "UPDATE conversation_shares SET current_version = %s WHERE id = %s",
                (int(version["id"]), share_id),
            )
        except Exception:
            raise
    return share_for_conversation(conversation_id)


def add_share_version(
    *,
    share_id: int,
    payload: dict,
    content_hash: str,
    last_message_id: Optional[int],
    message_count: int,
    created_by: int,
) -> int:
    """Publish a new version and switch to it in one transaction.

    The switch is the last statement, so a failure anywhere leaves the OLD
    version live. A half-published snapshot is the one outcome that must not
    exist: it would show a page nobody reviewed.
    """
    now = _now()
    with connection() as con:
        row = con.execute(
            """INSERT INTO conversation_share_versions
                   (share_id, version_number, payload, content_hash,
                    last_message_id, message_count, created_by, created_at)
               SELECT %s,
                      coalesce(max(version_number), 0) + 1,
                      %s, %s, %s, %s, %s, %s
                 FROM conversation_share_versions WHERE share_id = %s
               RETURNING id""",
            (share_id, _json_param(payload), content_hash, last_message_id,
             message_count, created_by, now, share_id),
        ).fetchone()
        version_id = int(row["id"])
        con.execute(
            "UPDATE conversation_shares SET current_version = %s, updated_at = %s "
            "WHERE id = %s",
            (version_id, now, share_id),
        )
    return version_id


def update_share_settings(
    share_id: int,
    *,
    visibility: Optional[str] = None,
    expires_at: Optional[datetime] = None,
    clear_expiry: bool = False,
    show_owner_name: Optional[bool] = None,
) -> None:
    sets, params = ["updated_at = %s"], [_now()]
    if visibility is not None:
        sets.append("visibility = %s"); params.append(visibility)
    if clear_expiry:
        sets.append("expires_at = NULL")
    elif expires_at is not None:
        sets.append("expires_at = %s"); params.append(expires_at)
    if show_owner_name is not None:
        sets.append("show_owner_name = %s"); params.append(show_owner_name)
    params.append(share_id)
    with connection() as con:
        con.execute(
            f"UPDATE conversation_shares SET {', '.join(sets)} WHERE id = %s",
            tuple(params),
        )


def revoke_share(share_id: int, *, revoked_by: Optional[int]) -> bool:
    """Stop a link working. Idempotent; returns whether this call did it."""
    now = _now()
    with connection() as con:
        row = con.execute(
            """UPDATE conversation_shares
                  SET status = 'revoked', revoked_at = %s, revoked_by = %s,
                      updated_at = %s
                WHERE id = %s AND status = 'active'
                RETURNING id""",
            (now, revoked_by, now, share_id),
        ).fetchone()
    return row is not None


def touch_share_view(share_id: int) -> None:
    """Count a view. Best-effort and never on the render path's critical
    section — a counter must not be able to fail a page."""
    try:
        with connection() as con:
            con.execute(
                "UPDATE conversation_shares SET view_count = view_count + 1, "
                "last_viewed_at = %s WHERE id = %s",
                (_now(), share_id),
            )
    except Exception:  # noqa: BLE001
        pass


def list_workspace_shares(workspace_id: str, limit: int = 200) -> List[dict]:
    """Admin view. Metadata only — no payload, and never the token."""
    with connection() as con:
        return con.execute(
            """SELECT s.id, s.conversation_id, s.public_id, s.visibility, s.status,
                      s.created_at, s.expires_at, s.revoked_at, s.last_viewed_at,
                      s.view_count, s.created_by,
                      u.display_name, u.username, u.email,
                      c.title, v.message_count
                 FROM conversation_shares s
                 JOIN users u ON u.id = s.created_by
                 LEFT JOIN conversations c ON c.id = s.conversation_id
                 LEFT JOIN conversation_share_versions v ON v.id = s.current_version
                WHERE s.workspace_id = %s
                ORDER BY s.created_at DESC
                LIMIT %s""",
            (workspace_id, limit),
        ).fetchall()


def share_by_id(share_id: int) -> Optional[dict]:
    with connection() as con:
        row = con.execute(
            "SELECT * FROM conversation_shares WHERE id = %s", (share_id,)
        ).fetchone()
    return dict(row) if row else None


def workspace_sharing_policy(workspace_id: str) -> dict:
    with connection() as con:
        row = con.execute(
            "SELECT sharing_policy FROM workspaces WHERE id = %s", (workspace_id,)
        ).fetchone()
    return dict(row["sharing_policy"] or {}) if row else {}


def set_workspace_sharing_policy(workspace_id: str, policy: dict) -> None:
    with connection() as con:
        con.execute(
            "UPDATE workspaces SET sharing_policy = %s WHERE id = %s",
            (_json_param(policy), workspace_id),
        )


def workspace_share_summary(workspace_id: str) -> dict:
    """Counts over the WHOLE workspace, not over a page of it.

    The console derived these from whatever rows the listing happened to
    return, so a workspace past the page limit under-reported, and picking
    "Revoked" in the toolbar made the "Live links" tile read 0 — which in turn
    hid a safety banner that keys off it.

    `active` here means EFFECTIVELY active: `status` only records revocation,
    so a link whose expiry has passed is still 'active' in the column while
    the public endpoint already 404s it. Counting those as live is how a
    governance console ends up being the one surface that lies.
    """
    live = "status = 'active' AND (expires_at IS NULL OR expires_at > now())"
    with connection() as con:
        row = con.execute(
            f"""SELECT
                  count(*) FILTER (WHERE {live})                            AS active,
                  count(*) FILTER (WHERE {live} AND visibility = 'public')   AS public,
                  count(*) FILTER (WHERE {live} AND visibility = 'workspace') AS workspace,
                  count(*) FILTER (WHERE status = 'active'
                                     AND expires_at IS NOT NULL
                                     AND expires_at <= now())               AS expired,
                  count(*) FILTER (WHERE status <> 'active')                AS revoked,
                  count(DISTINCT created_by) FILTER (WHERE {live})          AS authors,
                  coalesce(sum(view_count), 0)                              AS views,
                  count(*)                                                  AS total
                FROM conversation_shares
               WHERE workspace_id = %s""",
            (workspace_id,),
        ).fetchone()
    return {k: int(v or 0) for k, v in dict(row).items()}


def revoke_workspace_public_shares(
    workspace_id: str, *, revoked_by: Optional[int]
) -> List[int]:
    """Revoke every live PUBLIC link in one statement.

    Was a Python loop over a capped listing, which meant "revoke them too"
    could silently leave links serving: revoked and workspace-visibility rows
    consumed the row budget, and nothing paged past the first batch. A number
    reported as a completed job must not be a number that stopped early.
    """
    now = _now()
    with connection() as con:
        rows = con.execute(
            """UPDATE conversation_shares
                  SET status = 'revoked', revoked_at = %s, revoked_by = %s,
                      updated_at = %s
                WHERE workspace_id = %s
                  AND status = 'active'
                  AND visibility = 'public'
                RETURNING id""",
            (now, revoked_by, now, workspace_id),
        ).fetchall()
    return [int(r["id"]) for r in rows]


# ---------------------------------------------------------------------------
# V28: video understanding
# ---------------------------------------------------------------------------

def now() -> datetime:
    """The app-supplied timestamp every row carries (public alias)."""
    return _now()


_VIDEO_COLUMNS = (
    "id", "content_hash", "bytes", "media_type", "filename", "status", "stage",
    "stages", "error", "attempt", "pipeline_version", "duration_ms", "width",
    "height", "has_audio", "has_video", "language", "probe", "counts", "summary",
    "understanding", "artifacts", "indexed_at", "chunk_version", "created_at",
    "updated_at", "started_at", "finished_at", "lease_owner", "lease_expires_at",
)

#: Columns update_video_analysis may touch. Identity, hash and created_at are
#: not on it: they are what a row IS.
_VIDEO_UPDATABLE = frozenset({
    "media_type", "filename", "status", "stage", "stages", "error", "attempt",
    "pipeline_version", "duration_ms", "width", "height", "has_audio",
    "has_video", "language", "probe", "counts", "summary", "understanding",
    "artifacts", "indexed_at", "chunk_version", "started_at", "finished_at",
})
_VIDEO_JSON = frozenset({"stages", "probe", "counts", "understanding", "artifacts"})
_VIDEO_TEXT = frozenset({"media_type", "filename", "status", "stage", "error", "language", "summary"})


def _video_row(r: Any) -> dict:
    out = {k: r[k] for k in _VIDEO_COLUMNS}
    for k in ("created_at", "updated_at", "started_at", "finished_at", "indexed_at", "lease_expires_at"):
        out[k] = _iso(out[k]) if out.get(k) else None
    for k in _VIDEO_JSON:
        value = out.get(k)
        if isinstance(value, str):
            try:
                value = json.loads(value)
            except ValueError:
                value = None
        out[k] = value if value is not None else ({} if k != "artifacts" else [])
    out["id"] = int(out["id"])
    out["bytes"] = int(out["bytes"])
    return out


def upsert_video_analysis(
    content_hash: str, size: int, media_type: str, filename: str
) -> dict:
    """The analysis row for these bytes, created at 'queued' if new.

    Returns the row plus `created`. An existing row is returned untouched
    except that a FAILED one is put back in the queue — a re-upload is the
    natural "try again", and the stages that succeeded last time are cached
    on disk so the retry is cheap.
    """
    ts = _now()
    with connection() as con:
        row = con.execute(
            "SELECT * FROM video_analyses WHERE content_hash = %s", (content_hash,)
        ).fetchone()
        if row is not None:
            created = False
            if row["status"] == "failed":
                row = con.execute(
                    "UPDATE video_analyses SET status = 'queued', error = '', "
                    "updated_at = %s WHERE id = %s RETURNING *",
                    (ts, row["id"]),
                ).fetchone()
        else:
            created = True
            row = con.execute(
                """INSERT INTO video_analyses
                       (content_hash, bytes, media_type, filename, created_at, updated_at)
                   VALUES (%s, %s, %s, %s, %s, %s)
                   ON CONFLICT (content_hash) DO UPDATE SET updated_at = EXCLUDED.updated_at
                   RETURNING *""",
                (content_hash, int(size), _text(media_type or "") or "", _text(filename or "") or "", ts, ts),
            ).fetchone()
    out = _video_row(row)
    out["created"] = created
    return out


def get_video_analysis(analysis_id: int) -> Optional[dict]:
    with connection() as con:
        row = con.execute("SELECT * FROM video_analyses WHERE id = %s", (int(analysis_id),)).fetchone()
    return _video_row(row) if row else None


def get_video_analysis_by_hash(content_hash: str) -> Optional[dict]:
    with connection() as con:
        row = con.execute("SELECT * FROM video_analyses WHERE content_hash = %s", (content_hash,)).fetchone()
    return _video_row(row) if row else None


def update_video_analysis(analysis_id: int, **fields: Any) -> None:
    """Set the given columns (allow-listed) and bump updated_at.

    A None value for `stage` means "leave it"; every other None is written
    as NULL, which is what "not measured" means on this table.
    """
    sets: List[str] = []
    params: List[Any] = []
    for key, value in fields.items():
        if key not in _VIDEO_UPDATABLE:
            raise ValueError(f"video_analyses.{key} is not updatable")
        if key == "stage" and value is None:
            continue
        if key in _VIDEO_JSON:
            value = _json_param(value if value is not None else ({} if key != "artifacts" else []))
        elif key in _VIDEO_TEXT:
            value = _text(value) if value is not None else None
        sets.append(f"{key} = %s")
        params.append(value)
    if not sets:
        return
    sets.append("updated_at = %s")
    params.append(_now())
    params.append(int(analysis_id))
    with connection() as con:
        con.execute(f"UPDATE video_analyses SET {', '.join(sets)} WHERE id = %s", params)


def list_video_analyses(status: str, limit: int = 20) -> List[dict]:
    with connection() as con:
        rows = con.execute(
            "SELECT * FROM video_analyses WHERE status = %s ORDER BY id LIMIT %s",
            (status, int(limit)),
        ).fetchall()
    return [_video_row(r) for r in rows]


def requeue_interrupted_video_analyses() -> int:
    """At startup: a row left 'running' by a restart goes back to the queue.
    Its finished stages are on disk, so the resume costs only the stage that
    was cut off."""
    with connection() as con:
        # V29: only a run whose LEASE has lapsed is interrupted. A row whose
        # owner is still heartbeating belongs to a process that is alive —
        # another instance, or this one before a rolling recreate finished —
        # and requeuing it would start the same video twice.
        rows = con.execute(
            "UPDATE video_analyses SET status = 'queued', updated_at = %s, "
            "lease_owner = '', lease_expires_at = NULL "
            "WHERE status = 'running' "
            "AND (lease_expires_at IS NULL OR lease_expires_at < %s) RETURNING id",
            (_now(), _now()),
        ).fetchall()
    return len(rows)


def claim_video_lease(analysis_id: int, owner: str, ttl_s: float) -> bool:
    """Take (or renew) the run lease; False when another live owner holds it."""
    now = _now()
    with connection() as con:
        row = con.execute(
            "UPDATE video_analyses SET lease_owner = %s, lease_expires_at = %s, updated_at = %s "
            "WHERE id = %s AND (lease_owner = %s OR lease_owner = '' "
            "OR lease_expires_at IS NULL OR lease_expires_at < %s) RETURNING id",
            (owner, now + timedelta(seconds=float(ttl_s)), now, int(analysis_id), owner, now),
        ).fetchone()
    return row is not None


def release_video_lease(analysis_id: int, owner: str) -> None:
    with connection() as con:
        con.execute(
            "UPDATE video_analyses SET lease_owner = '', lease_expires_at = NULL "
            "WHERE id = %s AND lease_owner = %s",
            (int(analysis_id), owner),
        )


def link_video_attachment(
    analysis_id: int,
    conversation_id: str,
    user_id: Optional[int],
    upload_id: str,
    filename: str,
) -> dict:
    """Record that this conversation refers to this analysis. Idempotent per
    (conversation, analysis): attaching the same video twice in one chat is
    one link, with the newest upload id and name."""
    with connection() as con:
        row = con.execute(
            """INSERT INTO video_attachments
                   (analysis_id, conversation_id, user_id, upload_id, filename, created_at)
               VALUES (%s, %s, %s, %s, %s, %s)
               ON CONFLICT (conversation_id, analysis_id) DO UPDATE
                   SET upload_id = EXCLUDED.upload_id, filename = EXCLUDED.filename
               RETURNING id, analysis_id, conversation_id, user_id, upload_id, filename, created_at""",
            (int(analysis_id), conversation_id, user_id, upload_id or "", _text(filename or "") or "video", _now()),
        ).fetchone()
    out = dict(row)
    out["created_at"] = _iso(out["created_at"])
    return out


def get_conversation_videos(conversation_id: str) -> List[dict]:
    """Every analysis this conversation may see, newest attachment first,
    each carrying the name THIS conversation used for it."""
    with connection() as con:
        rows = con.execute(
            """SELECT a.*, l.upload_id AS link_upload_id, l.filename AS link_filename,
                      l.created_at AS attached_at, l.id AS link_id
                 FROM video_attachments l
                 JOIN video_analyses a ON a.id = l.analysis_id
                WHERE l.conversation_id = %s
                ORDER BY l.id DESC""",
            (conversation_id,),
        ).fetchall()
    out = []
    for r in rows:
        row = _video_row(r)
        row["upload_id"] = r["link_upload_id"]
        row["display_name"] = r["link_filename"]
        row["attached_at"] = _iso(r["attached_at"])
        out.append(row)
    return out


def get_video_by_upload(conversation_id: str, upload_id: str) -> Optional[dict]:
    with connection() as con:
        r = con.execute(
            """SELECT a.*, l.upload_id AS link_upload_id, l.filename AS link_filename,
                      l.created_at AS attached_at
                 FROM video_attachments l JOIN video_analyses a ON a.id = l.analysis_id
                WHERE l.conversation_id = %s AND l.upload_id = %s""",
            (conversation_id, upload_id),
        ).fetchone()
    if not r:
        return None
    row = _video_row(r)
    row["upload_id"] = r["link_upload_id"]
    row["display_name"] = r["link_filename"]
    row["attached_at"] = _iso(r["attached_at"])
    return row


def orphan_video_analyses(older_than_hours: int) -> List[dict]:
    """Analyses no conversation refers to, untouched for the grace period."""
    with connection() as con:
        rows = con.execute(
            """SELECT a.* FROM video_analyses a
                WHERE NOT EXISTS (SELECT 1 FROM video_attachments l WHERE l.analysis_id = a.id)
                  AND a.updated_at < %s
                ORDER BY a.id LIMIT 50""",
            (_now() - timedelta(hours=max(1, int(older_than_hours))),),
        ).fetchall()
    return [_video_row(r) for r in rows]


def delete_video_analysis(analysis_id: int) -> bool:
    with connection() as con:
        row = con.execute("DELETE FROM video_analyses WHERE id = %s RETURNING id", (int(analysis_id),)).fetchone()
    return row is not None


# ---------------------------------------------------------------------------
# V29 upload sessions — the chunked rail's durable state
# ---------------------------------------------------------------------------

_UPLOAD_SESSION_COLUMNS = (
    "id", "user_id", "conversation_id", "filename", "purpose", "expected_bytes",
    "expected_parts", "part_size", "accepted_parts", "bytes_received", "status",
    "error", "result", "created_at", "updated_at", "expires_at", "completed_at",
)


def _upload_session_row(r: Any) -> dict:
    out = {k: r[k] for k in _UPLOAD_SESSION_COLUMNS}
    for k in ("created_at", "updated_at", "expires_at", "completed_at"):
        out[k] = _iso(out[k]) if out.get(k) else None
    for k in ("accepted_parts", "result"):
        value = out.get(k)
        if isinstance(value, str):
            try:
                value = json.loads(value)
            except ValueError:
                value = None
        out[k] = value if value is not None else ({} if k == "accepted_parts" else None)
    out["user_id"] = int(out["user_id"])
    return out


def create_upload_session(
    upload_id: str,
    user_id: int,
    conversation_id: str,
    filename: str,
    purpose: str,
    *,
    expected_bytes: Optional[int] = None,
    expected_parts: Optional[int] = None,
    part_size: Optional[int] = None,
    ttl_hours: float = 24.0,
) -> dict:
    ts = _now()
    with connection() as con:
        row = con.execute(
            """INSERT INTO upload_sessions
                   (id, user_id, conversation_id, filename, purpose, expected_bytes,
                    expected_parts, part_size, created_at, updated_at, expires_at)
               VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
               RETURNING *""",
            (
                upload_id, int(user_id), conversation_id, _text(filename) or "upload.bin", purpose,
                None if expected_bytes is None else int(expected_bytes),
                None if expected_parts is None else int(expected_parts),
                None if part_size is None else int(part_size),
                ts, ts, ts + timedelta(hours=float(ttl_hours)),
            ),
        ).fetchone()
    return _upload_session_row(row)


def get_upload_session(upload_id: str) -> Optional[dict]:
    with connection() as con:
        row = con.execute("SELECT * FROM upload_sessions WHERE id = %s", (upload_id,)).fetchone()
    return _upload_session_row(row) if row is not None else None


def list_upload_sessions(conversation_id: str, user_id: int) -> List[dict]:
    with connection() as con:
        rows = con.execute(
            "SELECT * FROM upload_sessions WHERE conversation_id = %s AND user_id = %s "
            "ORDER BY created_at",
            (conversation_id, int(user_id)),
        ).fetchall()
    return [_upload_session_row(r) for r in rows]


def record_upload_part(upload_id: str, index: int, nbytes: int, sha256: Optional[str] = None) -> Optional[dict]:
    """Mark one part ACCEPTED (its file is durable on disk). Re-recording the
    same index replaces the earlier entry — a re-sent part counts once, and
    `bytes_received` is recomputed from the map, never incremented."""
    with connection() as con:
        row = con.execute(
            "SELECT accepted_parts FROM upload_sessions WHERE id = %s FOR UPDATE", (upload_id,)
        ).fetchone()
        if row is None:
            return None
        parts = row["accepted_parts"]
        if isinstance(parts, str):
            parts = json.loads(parts)
        parts = dict(parts or {})
        parts[str(int(index))] = {"bytes": int(nbytes), "sha256": sha256 or None}
        total = sum(int(v.get("bytes") or 0) for v in parts.values())
        row = con.execute(
            "UPDATE upload_sessions SET accepted_parts = %s, bytes_received = %s, updated_at = %s "
            "WHERE id = %s RETURNING *",
            (_json_param(parts), total, _now(), upload_id),
        ).fetchone()
    return _upload_session_row(row)


def try_begin_upload_finalize(upload_id: str) -> Optional[str]:
    """Atomically move uploading -> finalizing. Returns the status the row
    was in BEFORE ('uploading' when this caller won, 'finalizing' or
    'complete' when another request got there first), None when unknown."""
    with connection() as con:
        row = con.execute(
            "SELECT status FROM upload_sessions WHERE id = %s FOR UPDATE", (upload_id,)
        ).fetchone()
        if row is None:
            return None
        before = row["status"]
        if before == "uploading":
            con.execute(
                "UPDATE upload_sessions SET status = 'finalizing', updated_at = %s WHERE id = %s",
                (_now(), upload_id),
            )
    return before


def set_upload_session_status(
    upload_id: str, status: str, *, error: str = "", result: Optional[dict] = None
) -> Optional[dict]:
    ts = _now()
    with connection() as con:
        row = con.execute(
            "UPDATE upload_sessions SET status = %s, error = %s, "
            "result = COALESCE(%s, result), updated_at = %s, "
            "completed_at = CASE WHEN %s = 'complete' THEN %s ELSE completed_at END "
            "WHERE id = %s RETURNING *",
            (status, _text(error) or "", _json_param(result) if result is not None else None, ts, status, ts, upload_id),
        ).fetchone()
    return _upload_session_row(row) if row is not None else None


def reset_stale_finalizing_upload_sessions(older_than_s: float) -> int:
    """A session left `finalizing` by a process that died mid-complete goes
    back to `uploading`, parts intact, so the next `complete` can finish the
    job instead of waiting on a finaliser that no longer exists. Only rows
    untouched for `older_than_s` — a finaliser that is merely slow keeps
    bumping updated_at."""
    cutoff = _now() - timedelta(seconds=float(older_than_s))
    with connection() as con:
        rows = con.execute(
            "UPDATE upload_sessions SET status = 'uploading', updated_at = %s "
            "WHERE status = 'finalizing' AND updated_at < %s RETURNING id",
            (_now(), cutoff),
        ).fetchall()
    return len(rows)


def set_upload_session_status_if(
    upload_id: str, expected: Sequence[str], status: str, *, error: str = ""
) -> Optional[dict]:
    """A conditional transition: only from one of `expected`. Returns the row
    after the write, or None when the row was not in an expected status (the
    caller then reads it and decides). Lets DELETE refuse to cancel a session
    another request is finalising at that very moment."""
    ts = _now()
    with connection() as con:
        row = con.execute(
            "UPDATE upload_sessions SET status = %s, error = %s, updated_at = %s "
            "WHERE id = %s AND status = ANY(%s) RETURNING *",
            (status, _text(error) or "", ts, upload_id, list(expected)),
        ).fetchone()
    return _upload_session_row(row) if row is not None else None


def expired_upload_sessions(limit: int = 50) -> List[dict]:
    """Open sessions past their expiry — the sweep's work list. Complete,
    rejected and cancelled sessions are never returned: their parts are
    already gone or were never a session's responsibility."""
    with connection() as con:
        rows = con.execute(
            "SELECT * FROM upload_sessions WHERE status IN ('uploading', 'finalizing') "
            "AND expires_at < %s ORDER BY expires_at LIMIT %s",
            (_now(), int(limit)),
        ).fetchall()
    return [_upload_session_row(r) for r in rows]


# ---------------------------------------------------------------------------
# V29 chat requests — one row per send intent
# ---------------------------------------------------------------------------

_CHAT_REQUEST_COLUMNS = (
    "intent_id", "user_id", "conversation_id", "generation_id", "status", "attempt",
    "resumable", "request", "error", "created_at", "updated_at", "finished_at",
)


def _chat_request_row(r: Any) -> dict:
    out = {k: r[k] for k in _CHAT_REQUEST_COLUMNS}
    for k in ("created_at", "updated_at", "finished_at"):
        out[k] = _iso(out[k]) if out.get(k) else None
    value = out.get("request")
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            value = {}
    out["request"] = value if value is not None else {}
    out["user_id"] = int(out["user_id"])
    return out


def create_chat_request(
    intent_id: str,
    user_id: int,
    conversation_id: str,
    generation_id: str,
    request: dict,
    *,
    resumable: bool = True,
) -> Optional[dict]:
    """Record acceptance. Returns None when the intent already exists — the
    caller then reads the existing row and attaches or replays."""
    ts = _now()
    with connection() as con:
        row = con.execute(
            """INSERT INTO chat_requests
                   (intent_id, user_id, conversation_id, generation_id, request, resumable,
                    created_at, updated_at)
               VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
               ON CONFLICT (intent_id) DO NOTHING
               RETURNING *""",
            (intent_id, int(user_id), conversation_id, generation_id, _json_param(request), bool(resumable), ts, ts),
        ).fetchone()
    return _chat_request_row(row) if row is not None else None


def get_chat_request(intent_id: str) -> Optional[dict]:
    with connection() as con:
        row = con.execute("SELECT * FROM chat_requests WHERE intent_id = %s", (intent_id,)).fetchone()
    return _chat_request_row(row) if row is not None else None


def latest_chat_request(conversation_id: str) -> Optional[dict]:
    with connection() as con:
        row = con.execute(
            "SELECT * FROM chat_requests WHERE conversation_id = %s ORDER BY created_at DESC LIMIT 1",
            (conversation_id,),
        ).fetchone()
    return _chat_request_row(row) if row is not None else None


def set_chat_request_status(intent_id: str, status: str, *, error: str = "") -> Optional[dict]:
    ts = _now()
    terminal = status in ("completed", "failed", "cancelled")
    with connection() as con:
        row = con.execute(
            "UPDATE chat_requests SET status = %s, error = %s, updated_at = %s, "
            "finished_at = CASE WHEN %s THEN %s ELSE finished_at END "
            "WHERE intent_id = %s RETURNING *",
            (status, _text(error) or "", ts, terminal, ts, intent_id),
        ).fetchone()
    return _chat_request_row(row) if row is not None else None


def resume_chat_request(
    intent_id: str,
    generation_id: str,
    *,
    reopen_finished: bool = False,
    expected_generation_id: Optional[str] = None,
) -> Optional[dict]:
    """A new attempt of an intent under a fresh generation id.

    By default only an 'interrupted' (or still 'accepted'/'running' after a
    lost process) row is resumed; `reopen_finished` also lets a 'failed' or
    'cancelled' one be asked again. `expected_generation_id` makes the
    transition conditional on the generation the caller saw, so two callers
    racing to resume the same intent cannot both win — the loser sees the
    row unchanged and attaches to the winner's generation instead."""
    ts = _now()
    # `queued` (V32): a row parked for a recovering model is open too — the
    # resume sweep and the browser's re-attach both come through here.
    allowed = ["interrupted", "accepted", "running", "queued"] + (["failed", "cancelled"] if reopen_finished else [])
    with connection() as con:
        if expected_generation_id is None:
            row = con.execute(
                "UPDATE chat_requests SET generation_id = %s, attempt = attempt + 1, "
                "status = 'accepted', error = '', updated_at = %s "
                "WHERE intent_id = %s AND status = ANY(%s) RETURNING *",
                (generation_id, ts, intent_id, allowed),
            ).fetchone()
        else:
            row = con.execute(
                "UPDATE chat_requests SET generation_id = %s, attempt = attempt + 1, "
                "status = 'accepted', error = '', updated_at = %s "
                "WHERE intent_id = %s AND status = ANY(%s) AND generation_id = %s RETURNING *",
                (generation_id, ts, intent_id, allowed, expected_generation_id),
            ).fetchone()
        if row is None:
            row = con.execute("SELECT * FROM chat_requests WHERE intent_id = %s", (intent_id,)).fetchone()
    return _chat_request_row(row) if row is not None else None


def get_message_by_generation(conversation_id: str, generation_id: str) -> Optional[dict]:
    """The stored message for a generation, if any — how `answer_persisted`
    is answered without listing the whole thread."""
    with connection() as con:
        row = con.execute(
            "SELECT id, role, content, meta, created_at FROM messages "
            "WHERE conversation_id = %s AND generation_id = %s",
            (conversation_id, str(generation_id)),
        ).fetchone()
    if row is None:
        return None
    meta = row["meta"]
    if isinstance(meta, str):
        try:
            meta = json.loads(meta)
        except ValueError:
            meta = None
    return {"id": int(row["id"]), "role": row["role"], "content": row["content"], "meta": meta, "created_at": _iso(row["created_at"])}


def delete_failure_record(conversation_id: str, generation_id: str) -> bool:
    """Remove the assistant row a FAILED generation left (meta.error), so a
    successful new attempt is not shown under an old failure. Never touches
    a row that holds an answer."""
    with connection() as con:
        row = con.execute(
            "DELETE FROM messages WHERE conversation_id = %s AND generation_id = %s "
            "AND meta ? 'error' RETURNING id",
            (conversation_id, str(generation_id)),
        ).fetchone()
    return row is not None


def interrupt_open_chat_requests() -> int:
    """Startup (or orderly shutdown): every request this process could have
    been running is now 'interrupted'. Returns how many. A `queued` row is
    left as it is: it says the truth about itself whichever process held
    it (waiting for the main model), and the resume sweep reads it by name."""
    with connection() as con:
        rows = con.execute(
            "UPDATE chat_requests SET status = 'interrupted', updated_at = %s "
            "WHERE status IN ('accepted', 'running') RETURNING intent_id",
            (_now(),),
        ).fetchall()
    return len(rows)


def park_chat_request(intent_id: str, generation_id: str) -> Optional[dict]:
    """V32 (CONTRACT §8.3 step 1): the generation is waiting for the main
    model — the row says `queued`. Conditional on the generation the caller
    holds and on the row being live (accepted/running), so a Stop that
    landed meanwhile is never overwritten. Returns the row when it moved."""
    with connection() as con:
        row = con.execute(
            "UPDATE chat_requests SET status = 'queued', updated_at = %s "
            "WHERE intent_id = %s AND generation_id = %s AND status IN ('accepted', 'running') "
            "RETURNING *",
            (_now(), intent_id, generation_id),
        ).fetchone()
    return _chat_request_row(row) if row is not None else None


def resume_queued_chat_request(intent_id: str, generation_id: str, *, new_attempt: bool) -> Optional[dict]:
    """V32 (CONTRACT §8.3 step 4): the SAME generation goes on — the row is
    `running` again under the generation it already names, and, for a
    recovery (not a mere admission wait), `attempt` moves on by one.
    Conditional on `queued` + the generation, so a sweep or a re-attach
    that took the row over meanwhile wins and this caller sees None."""
    with connection() as con:
        row = con.execute(
            "UPDATE chat_requests SET status = 'running', "
            "attempt = attempt + %s, updated_at = %s "
            "WHERE intent_id = %s AND generation_id = %s AND status = 'queued' RETURNING *",
            (1 if new_attempt else 0, _now(), intent_id, generation_id),
        ).fetchone()
    return _chat_request_row(row) if row is not None else None


def list_resumable_chat_requests(statuses: Sequence[str], *, max_age_s: float, limit: int = 200) -> list:
    """Rows the resume sweep may act on (CONTRACT §8.4 v2): in one of
    `statuses` and resumable from their snapshot. Oldest first.

    `max_age_s` bounds `interrupted` rows ONLY, measured from `created_at`
    — the moment the send was accepted: an interrupted row accepted longer
    ago than that is a request nobody is waiting for any more, and
    re-running it would only surprise a thread. A `queued` row is listed
    whatever its age: it was parked on purpose, for exactly this sweep,
    and CONTRACT §2 (DOWN) promises it is never lost — a recovery that
    outlasts the age limit (a budget-exhausted night) must still resume
    every parked request when an operator brings the pair back.
    """
    with connection() as con:
        rows = con.execute(
            "SELECT * FROM chat_requests WHERE status = ANY(%s) AND resumable "
            "AND (status = 'queued' OR created_at > %s - (%s * interval '1 second')) "
            "ORDER BY created_at LIMIT %s",
            (list(statuses), _now(), float(max_age_s), int(limit)),
        ).fetchall()
    return [_chat_request_row(r) for r in rows]


def count_chat_requests(status: str) -> int:
    """How many rows are in `status` right now (the durable half of
    `llm_queued_generations`, app/continuity.py)."""
    with connection() as con:
        row = con.execute(
            "SELECT count(*) AS n FROM chat_requests WHERE status = %s", (status,)
        ).fetchone()
    return int(row["n"]) if row else 0


def generation_streamed(generation_id: str) -> bool:
    """Did this attempt reach a viewer with at least one token? The attempt
    ledger (usage_events, one row per generation_id, written by the chat
    worker's finally — so by an orderly shutdown, not by a crash) records
    `ttft_ms` only when a token was streamed. CONTRACT §8.4: such an
    attempt is never re-run by itself."""
    with connection() as con:
        row = con.execute(
            "SELECT ttft_ms FROM usage_events WHERE generation_id = %s", (str(generation_id),)
        ).fetchone()
    return row is not None and row["ttft_ms"] is not None


def cancel_parked_chat_requests(conversation_id: str, *, keep: Sequence[str]) -> int:
    """A newer send in the conversation supersedes every row still parked
    `queued` for it (CONTRACT §8.3 with the /chat rule "the newest message
    wins"): they are `cancelled` with the same error a replaced live
    generation carries, so the resume sweep never answers an old question
    below the newer exchange. `keep` names the intents that must not be
    touched — the new send itself and any generation this process still
    holds (its own worker writes its terminal status). Returns how many."""
    ts = _now()
    with connection() as con:
        rows = con.execute(
            "UPDATE chat_requests SET status = 'cancelled', error = %s, updated_at = %s, finished_at = %s "
            "WHERE conversation_id = %s AND status = 'queued' AND NOT (intent_id = ANY(%s)) "
            "RETURNING intent_id",
            ("replaced by a newer message", ts, ts, conversation_id, list(keep)),
        ).fetchall()
    return len(rows)


# ---------------------------------------------------------------------------
# Generation-correlated query tracing (V30)
# ---------------------------------------------------------------------------

def start_query_trace(
    trace_id: str,
    conversation_id: str,
    user_id: Optional[int],
    workspace_id: str,
    original_question: str,
    requested_mode: str,
    resolved_mode: str = "",
    request_id: str = "",
    test_case_id: Optional[str] = None,
    versions: Optional[dict] = None,
) -> None:
    """Create the durable root before any routing or retrieval work begins."""
    now = _now()
    with connection() as con:
        con.execute(
            """INSERT INTO query_traces
                   (trace_id, conversation_id, user_id, workspace_id,
                    original_question, requested_mode, resolved_mode,
                    request_id, test_case_id, versions, final_status, started_at)
               VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'running', %s)
               ON CONFLICT (trace_id) DO NOTHING""",
            (
                trace_id,
                conversation_id,
                user_id,
                workspace_id or None,
                _text(original_question or ""),
                _text(requested_mode or ""),
                _text(resolved_mode or ""),
                _text(request_id or ""),
                _text(test_case_id) if test_case_id else None,
                _json_param(versions or {}),
                now,
            ),
        )


def append_query_trace_event(
    trace_id: str,
    sequence_number: int,
    stage: str,
    status: str,
    component: str,
    details: dict,
    duration_ms: Optional[int] = None,
    error_type: str = "",
    error_message: str = "",
    component_version: str = "",
) -> None:
    """Append an ordered checkpoint; retries are idempotent by sequence."""
    completed_at = _now()
    elapsed = max(0, int(duration_ms or 0))
    started_at = completed_at - timedelta(milliseconds=elapsed)
    with connection() as con:
        con.execute(
            """INSERT INTO query_trace_events
                   (trace_id, sequence_number, stage, status, created_at,
                    started_at, completed_at, duration_ms, component,
                    component_version, details, error_type, error_message)
               VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
               ON CONFLICT (trace_id, sequence_number) DO NOTHING""",
            (
                trace_id,
                int(sequence_number),
                _text(stage),
                _text(status),
                completed_at,
                started_at,
                completed_at,
                duration_ms,
                _text(component or ""),
                _text(component_version or ""),
                _json_param(details or {}),
                _text(error_type or ""),
                _text(error_message or ""),
            ),
        )


def finish_query_trace(
    trace_id: str,
    final_status: str,
    total_duration_ms: int,
    *,
    resolved_mode: str = "",
    selected_route: str = "",
    error_stage: str = "",
    error_type: str = "",
    error_message: str = "",
    meta: Optional[dict] = None,
) -> None:
    """Close a trace once; a late duplicate finalizer cannot rewrite it."""
    with connection() as con:
        con.execute(
            """UPDATE query_traces
                  SET final_status = %s, completed_at = %s,
                      total_duration_ms = %s,
                      resolved_mode = CASE WHEN %s = '' THEN resolved_mode ELSE %s END,
                      selected_route = CASE WHEN %s = '' THEN selected_route ELSE %s END,
                      error_stage = %s, error_type = %s, error_message = %s,
                      meta = %s
                WHERE trace_id = %s AND final_status = 'running'""",
            (
                final_status,
                _now(),
                max(0, int(total_duration_ms)),
                resolved_mode,
                resolved_mode,
                selected_route,
                selected_route,
                _text(error_stage or ""),
                _text(error_type or ""),
                _text(error_message or ""),
                _json_param(meta or {}),
                trace_id,
            ),
        )


def get_query_trace(trace_id: str, user_id: int) -> Optional[dict]:
    """Return one trace to its owning user, including ordered checkpoints."""
    with connection() as con:
        root = con.execute(
            "SELECT * FROM query_traces WHERE trace_id = %s AND user_id = %s",
            (trace_id, int(user_id)),
        ).fetchone()
        if root is None:
            return None
        events = con.execute(
            """SELECT sequence_number, stage, status, created_at, started_at,
                      completed_at, duration_ms, component, component_version,
                      details, error_type, error_message
                 FROM query_trace_events
                WHERE trace_id = %s
                ORDER BY sequence_number""",
            (trace_id,),
        ).fetchall()
    trace = dict(root)
    for key in ("started_at", "completed_at"):
        trace[key] = _iso(trace.get(key))
    trace["events"] = []
    for item in events:
        event = dict(item)
        for key in ("created_at", "started_at", "completed_at"):
            event[key] = _iso(event.get(key))
        trace["events"].append(event)
    return trace


# ---------------------------------------------------------------------------
# V34: the developer platform — projects, service accounts, keys, responses,
# idempotency, usage ledgers, webhooks, model overrides, platform secrets
#
# TWO RULES HOLD FOR EVERY FUNCTION BELOW, and both are about tenancy.
#
# 1. A read that takes a caller-supplied id ALSO takes the workspace (or the
#    project) that must own it, and the owner goes in the WHERE clause rather
#    than into an `if` after the fetch. OWASP API1 is explicit that the check
#    belongs inside the function that does the lookup: a handler that forgets
#    to call a guard is the single most common way one tenant reads another's
#    row, and a predicate cannot be forgotten by a handler that does not know
#    it exists. A row that belongs to somebody else is therefore
#    indistinguishable here from a row that does not exist — which is also the
#    404-not-403 rule the public surface needs (CONTRACT-3 §9).
# 2. A write that attaches a child to a parent derives the parent's tenancy
#    from the parent row IN THE SAME STATEMENT (`INSERT ... SELECT ... FROM
#    api_projects p WHERE p.id = %s AND p.workspace_id = %s`), so a caller
#    cannot create a key in project A carrying workspace B's id, and there is
#    no window between a check and an insert for the project to be deleted.
#
# `api_key_by_public_id` is the one CALLER-REACHABLE read with no tenant
# argument, and it is the exception that proves the rule: `public_id` IS the
# credential the caller presented, not an id it chose, and resolving it is how
# the tenant gets decided in the first place (CONTRACT-3 §4).
#
# Three more functions take no tenant, and none of them is reachable from a
# request: `due_webhook_deliveries` and `expire_rotated_keys` are the server's
# own sweeps over its own queues, and `prune_api_platform` is retention. They
# are deployment-scheduled, they take no caller-supplied id at all, and each
# says so in its docstring. A sweep with no tenant is only safe if every row
# it acts on decides its OWN fate: `expire_rotated_keys` once joined one key
# to another by a public id a different workspace could write, and revoked
# the other workspace's key (2026-09-13); it now reads a deadline off the
# very row it revokes. `touch_api_key` takes a bare key id as well, and is
# safe for a different reason — the id it is given is the one the RESOLVER
# just proved by verifying the presented secret, never one a caller named;
# no console route may call it. `record_webhook_attempt` sits between the two
# worlds — the sweep calls it with a bare delivery id, a console retry button
# must pass `project_id` — so the predicate is optional there and the
# docstring says which caller owes it. This paragraph used to claim there was
# exactly one unscoped accessor, which the 2026-09-12 verifier read as a
# promise and found untrue; a rule stated more simply than the code follows it
# is worse than no rule, because the next author trusts it.
# ---------------------------------------------------------------------------


def _api_id(prefix: str) -> str:
    """`proj_<24 hex>` — the id shapes SCHEMA-V34 fixes for each table.

    CSPRNG, not a sequence: these ids travel in customer code, request logs
    and webhook payloads, and a guessable one turns every path parameter into
    an enumeration oracle (OWASP API1). `secrets` is imported here rather than
    at module scope for the same reason `anyio` is in `run_in_thread` — this
    module is imported by everything and its import list is deliberately flat.
    """
    import secrets

    return f"{prefix}_{secrets.token_hex(12)}"


def _api_row(row: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """`_row`, plus the daily ledger's `day`.

    psycopg returns a `date` for a `date` column, which `_iso` leaves alone
    because it is not a `datetime`; every caller of the usage API wants the
    same ISO string it gets for every other temporal column.
    """
    if row is None:
        return None
    out = _row(row) or {}
    day = out.get("day")
    if day is not None and not isinstance(day, str) and hasattr(day, "isoformat"):
        out["day"] = day.isoformat()
    return out


def _api_rows(rows: Sequence[Any]) -> List[dict]:
    return [_api_row(row) for row in rows]  # type: ignore[misc]


def _minute_bucket(at: Optional[datetime] = None) -> datetime:
    """The minute a usage bump belongs to, truncated in Python.

    Truncated here rather than with `date_trunc(... now())` so a test can pin
    a bucket and so two statements in one request cannot straddle a minute
    boundary between them.
    """
    moment = at or _now()
    return moment.replace(second=0, microsecond=0)


def _as_day(value: Any) -> Any:
    """A `date` from a date, a datetime or an ISO string; ValueError otherwise."""
    if isinstance(value, datetime):
        return value.date()
    if hasattr(value, "isoformat") and not isinstance(value, str):
        return value
    return datetime.fromisoformat(str(value)[:10]).date()


#: What `_json_array` will accept. A `str` is deliberately absent even though
#: it is iterable: `list("techsara-35b")` is a 12-element allowlist of single
#: characters, and that is not a typo anybody catches by reading the row back.
_JSON_ARRAY_TYPES = (list, tuple, set, frozenset)
#: The bound on every allow-list column. The entry count matches the CHECK in
#: `_MIGRATION_V34`; change both or neither.
_JSON_ARRAY_MAX_ITEMS = 256
_JSON_ARRAY_MAX_ITEM_CHARS = 512


def _json_array(column: str, value: Any) -> Jsonb:
    """A jsonb ARRAY of strings, or ValueError — never a reshaped value.

    Every column this guards is an allow-list that an authorization decision
    is read from: `allowed_models`, `allowed_origins`, `ip_allowlist`,
    `scopes`, `events`. The generic `_json_param` is wrong for all of them,
    because its job is to keep arbitrary metadata addressable — a string that
    will not parse as JSON becomes `{"raw": …}` rather than being lost. Doing
    that to an allowlist turns `model in row["allowed_models"]` into a test
    against an object's KEYS, and doing `list(value)` to it turns a model id
    into its letters. The 2026-09-12 verifier measured both. The DDL now
    refuses a non-array too; this is the half that gives the caller a sentence
    naming the column instead of an IntegrityError naming a constraint.

    A set is accepted because `apiplatform.scopes.parse_scopes` returns a
    frozenset and making every caller remember `scope_names()` would be a
    trap, but it is SORTED on the way in: a console that renders scopes must
    not reorder them between two page loads, and a test that asserts on the
    stored row must not depend on a hash seed.

    The types are checked BEFORE the sort (2026-09-13): `sorted({"a", 1})`
    raises TypeError, so a mixed set used to escape as a 500 instead of the
    ValueError a route maps to 400. The size is bounded too — at most
    `_JSON_ARRAY_MAX_ITEMS` entries of `_JSON_ARRAY_MAX_ITEM_CHARS` characters
    — because 5,000 thousand-character model ids were accepted and the
    resolver reads the project row on every `/v1` request. The DDL holds the
    entry count as well; only the per-entry length lives here alone.
    """
    if not isinstance(value, _JSON_ARRAY_TYPES):
        raise ValueError(
            f"{column} must be a list of strings, not {type(value).__name__} — "
            "an allowlist is read as an array on every request path"
        )
    raw = list(value)
    for item in raw:
        if not isinstance(item, str):
            raise ValueError(
                f"{column} may only contain strings; got {type(item).__name__}"
            )
        if len(item) > _JSON_ARRAY_MAX_ITEM_CHARS:
            raise ValueError(
                f"{column} entries may be at most {_JSON_ARRAY_MAX_ITEM_CHARS} characters"
            )
    if len(raw) > _JSON_ARRAY_MAX_ITEMS:
        raise ValueError(
            f"{column} may hold at most {_JSON_ARRAY_MAX_ITEMS} entries; got {len(raw)}"
        )
    items = sorted(raw) if isinstance(value, (set, frozenset)) else raw
    return Jsonb([str(item) for item in items], dumps=_dumps_jsonb)


def _json_object(column: str, value: Any) -> Jsonb:
    """A jsonb OBJECT, or ValueError. The mirror of `_json_array` for the
    columns the schema declares as objects (`metadata`, `payload`): a list
    stored in one of them is a KeyError in whichever page reads it next, and
    a non-string key is a TypeError inside `json.dumps` — a 500 at write time
    for a value the caller could have been told about."""
    if not isinstance(value, dict):
        raise ValueError(
            f"{column} must be an object, not {type(value).__name__}"
        )
    for key in value:
        if not isinstance(key, str):
            raise ValueError(
                f"{column} keys must be strings; got {type(key).__name__}"
            )
    return Jsonb(value, dumps=_dumps_jsonb)


def _insert_optional(
    columns: List[str], params: List[Any], values: Dict[str, Any]
) -> None:
    """Append the values a caller actually supplied.

    A column the caller left as None is omitted from the INSERT so the DDL's
    DEFAULT applies. Spelling the defaults again in Python would mean two
    places to change the day a limit moves, and the one that is wrong is
    always the one that is not in the migration.
    """
    for column, value in values.items():
        if value is None:
            continue
        columns.append(column)
        params.append(value)


#: Columns the console may change on a project. `environment` is deliberately
#: absent: keys are minted `tsk_live_` / `tsk_test_` from it, and flipping it
#: under issued keys would make a live key present itself as a test key
#: (CONTRACT-3 §5). `workspace_id` is absent for the obvious reason.
_API_PROJECT_UPDATABLE = frozenset({
    "name", "status", "allowed_models", "allowed_origins", "ip_allowlist",
    "rpm", "input_tpm", "output_tpm", "max_concurrency", "daily_token_quota",
    "max_input_tokens", "max_output_tokens", "retention_days", "metadata",
})
#: Split by SHAPE, not just by "this one is jsonb": the three allow-lists are
#: arrays an authorization decision is read from and `metadata` is a free-form
#: object, so they are validated by different guards.
_API_PROJECT_JSON_ARRAYS = frozenset({"allowed_models", "allowed_origins", "ip_allowlist"})
_API_PROJECT_JSON_OBJECTS = frozenset({"metadata"})
_API_PROJECT_JSON = _API_PROJECT_JSON_ARRAYS | _API_PROJECT_JSON_OBJECTS

_API_RESPONSE_UPDATABLE = frozenset({
    "status", "streamed", "input_tokens", "output_tokens", "ttft_ms",
    "duration_ms", "error_code", "error_message", "output_text",
    "cancel_requested", "metadata", "started_at", "completed_at", "expires_at",
})
_API_RESPONSE_JSON = frozenset({"metadata"})
_API_RESPONSE_TEXT = frozenset({"error_code", "error_message", "output_text"})
_API_RESPONSE_TERMINAL = ("completed", "failed", "cancelled")

#: The columns a LIST read of `api_keys` returns. Spelled out rather than
#: `SELECT *` because `key_hash` must not be in it: it is the HMAC digest the
#: resolver compares against, and the 2026-09-12 verifier found every row of
#: `list_api_keys` carrying it under a docstring that claimed "no secret
#: material beyond last_four is ever readable". Nothing leaked, because no
#: route consumed the function yet — the finding is that the layer was telling
#: the next wave's author it was safe to serialise the dict straight out to a
#: console page.
#:
#: An explicit list is also the safer failure: the day somebody adds a column
#: to this table, forgetting to add it here shows up as a missing field in a
#: page, while a `SELECT *` would have published it. `api_key_by_public_id`
#: keeps the full row, because verifying a presented secret against the digest
#: is the one thing that genuinely needs it.
_API_KEY_PUBLIC_COLUMNS = (
    "id", "public_id", "last_four", "project_id", "service_account_id",
    "workspace_id", "environment", "name", "scopes", "allowed_models", "rpm",
    "max_concurrency", "status", "expires_at", "created_by", "created_at",
    "last_used_at", "last_used_ip", "revoked_at", "revoked_by", "rotated_from",
    "rotation_expires_at",
)

#: The same rule for webhook endpoints, and here the column really is a live
#: secret rather than a digest: `secret` and `previous_secret` are stored in
#: clear because the SERVER signs every delivery with them (SCHEMA-V34.md says
#: of that column "it is shown once in the console and returned by no API",
#: which `list_webhook_endpoints` was contradicting). `previous_secret_expires_at`
#: stays — a date is not a credential, and the console has to show when an
#: overlap ends. `due_webhook_deliveries` keeps the full read, because it is
#: the sweep that computes the signature; it is the ONLY accessor that returns
#: a secret, and create/update project through this list too (2026-09-13).
#: A consumer reads `has_secret` / `has_previous_secret`, never
#: `row.get("secret")` — which is falsy on every row this module returns.
_WEBHOOK_ENDPOINT_PUBLIC_COLUMNS = (
    "id", "project_id", "workspace_id", "url", "events", "status",
    "previous_secret_expires_at", "include_output", "created_by", "created_at",
    "last_delivery_at", "last_delivery_status", "consecutive_failures",
    "disabled_at",
)

#: …plus the FACT of a secret, which is not the secret. The console shows
#: "this endpoint is signed" and "a rotation is in flight" without any page
#: ever holding a forgery primitive — a signing secret in a response body lets
#: whoever reads it post a perfectly signed "your job finished" event to the
#: customer's endpoint. Derived in SQL rather than in Python precisely so that
#: the value itself never leaves PostgreSQL on this path.
_WEBHOOK_ENDPOINT_SECRET_FLAGS = (
    "(secret IS NOT NULL AND secret <> '') AS has_secret, "
    "(previous_secret IS NOT NULL AND previous_secret <> '') AS has_previous_secret"
)
_WEBHOOK_ENDPOINT_PUBLIC_SELECT = (
    ", ".join(_WEBHOOK_ENDPOINT_PUBLIC_COLUMNS) + ", " + _WEBHOOK_ENDPOINT_SECRET_FLAGS
)

_WEBHOOK_ENDPOINT_UPDATABLE = frozenset({
    "url", "events", "status", "secret", "previous_secret",
    "previous_secret_expires_at", "include_output",
})
_WEBHOOK_ENDPOINT_JSON = frozenset({"events"})

_API_ENVIRONMENTS = ("test", "live")


# --- projects ---------------------------------------------------------------


def create_api_project(
    workspace_id: str,
    name: str,
    environment: str = "live",
    *,
    project_id: Optional[str] = None,
    created_by: Optional[int] = None,
    allowed_models: Optional[Sequence[str]] = None,
    allowed_origins: Optional[Sequence[str]] = None,
    ip_allowlist: Optional[Sequence[str]] = None,
    rpm: Optional[int] = None,
    input_tpm: Optional[int] = None,
    output_tpm: Optional[int] = None,
    max_concurrency: Optional[int] = None,
    daily_token_quota: Optional[int] = None,
    max_input_tokens: Optional[int] = None,
    max_output_tokens: Optional[int] = None,
    retention_days: Optional[int] = None,
    metadata: Optional[dict] = None,
    is_playground: bool = False,
) -> dict:
    """Create a project in `workspace_id`; returns the stored row.

    Raises ValueError for an unknown environment and db.IntegrityError for a
    name already taken in this workspace (unique on `lower(name)`), a second
    playground row in the same workspace, or a workspace that does not exist.

    `is_playground=True` marks the workspace's console-playground allowance
    row (V34 `api_projects.is_playground`). Only server code that mints that
    row may pass it: it is a keyword a route has to spell out, it is not in
    `_API_PROJECT_UPDATABLE`, so no PATCH body can set or clear it, and the
    row it marks is outside the name index, so a customer project's name can
    never collide with it.
    """
    if environment not in _API_ENVIRONMENTS:
        raise ValueError(f"api_projects.environment must be one of {_API_ENVIRONMENTS}")
    columns = ["id", "workspace_id", "name", "environment"]
    params: List[Any] = [
        project_id or _api_id("proj"), workspace_id, _text(name), environment,
    ]
    _insert_optional(columns, params, {
        "allowed_models":
            _json_array("api_projects.allowed_models", allowed_models)
            if allowed_models is not None else None,
        "allowed_origins":
            _json_array("api_projects.allowed_origins", allowed_origins)
            if allowed_origins is not None else None,
        "ip_allowlist":
            _json_array("api_projects.ip_allowlist", ip_allowlist)
            if ip_allowlist is not None else None,
        "rpm": None if rpm is None else int(rpm),
        "input_tpm": None if input_tpm is None else int(input_tpm),
        "output_tpm": None if output_tpm is None else int(output_tpm),
        "max_concurrency": None if max_concurrency is None else int(max_concurrency),
        "daily_token_quota": None if daily_token_quota is None else int(daily_token_quota),
        "max_input_tokens": None if max_input_tokens is None else int(max_input_tokens),
        "max_output_tokens": None if max_output_tokens is None else int(max_output_tokens),
        "retention_days": None if retention_days is None else int(retention_days),
        "metadata":
            _json_object("api_projects.metadata", metadata)
            if metadata is not None else None,
        "created_by": None if created_by is None else int(created_by),
        "is_playground": True if is_playground is True else None,
    })
    placeholders = ", ".join(["%s"] * len(columns))
    with connection() as con:
        row = con.execute(
            f"INSERT INTO api_projects ({', '.join(columns)}) "
            f"VALUES ({placeholders}) RETURNING *",
            params,
        ).fetchone()
    return _api_row(row)  # type: ignore[return-value]


def get_api_project(project_id: str, workspace_id: str) -> Optional[dict]:
    """One project, or None — including when it belongs to another workspace."""
    with connection() as con:
        row = con.execute(
            "SELECT * FROM api_projects WHERE id = %s AND workspace_id = %s",
            (project_id, workspace_id),
        ).fetchone()
    return _api_row(row)


def list_api_projects(
    workspace_id: str,
    *,
    include_disabled: bool = True,
    include_playground: bool = True,
    limit: int = 100,
) -> List[dict]:
    """A workspace's projects, newest first. `limit` is clamped server-side:
    a client-supplied page size is a denial-of-service primitive (OWASP API4).

    `include_playground=False` leaves out the console-playground allowance
    row, filtered in SQL so the page size counts customer projects only. The
    default stays True so no existing caller's result changes."""
    bounded = max(1, min(int(limit), 500))
    with connection() as con:
        rows = con.execute(
            "SELECT * FROM api_projects WHERE workspace_id = %s "
            "AND (%s OR status = 'active') AND (%s OR NOT is_playground) "
            "ORDER BY created_at DESC, id LIMIT %s",
            (workspace_id, bool(include_disabled), bool(include_playground), bounded),
        ).fetchall()
    return _api_rows(rows)


def get_playground_project(workspace_id: str) -> Optional[dict]:
    """The workspace's console-playground allowance row, or None before its
    first run. At most one exists (`idx_api_projects_one_playground`)."""
    with connection() as con:
        row = con.execute(
            "SELECT * FROM api_projects WHERE workspace_id = %s AND is_playground",
            (workspace_id,),
        ).fetchone()
    return _api_row(row)


def update_api_project(project_id: str, workspace_id: str, /, **fields: Any) -> Optional[dict]:
    """Change allow-listed project columns; None when it is not this
    workspace's project.

    Raises ValueError for a column that may not be set, and for a value whose
    SHAPE is wrong — an `allowed_models` that is not a list of strings, a
    `metadata` that is not an object. `**fields` is what a route builds from a
    request body, so "it arrived as a string" is the normal case rather than
    the exotic one, and the old behaviour (store `{"raw": "techsara-35b"}` and
    carry on) left the project with an allowlist no reader can evaluate.
    Raises db.IntegrityError for a value the schema refuses — a negative
    `retention_days` or `rpm` — which is the constraint answering, not this
    function, so the same refusal holds for psql.
    """
    # The tenancy arguments are POSITIONAL-ONLY on purpose. `**fields` is what
    # a caller builds from a request body, and a body carrying its own
    # `workspace_id` would otherwise collide with the argument that scopes the
    # statement — a TypeError at best, and at worst a reviewer believing the
    # tenancy value came from the caller's session when it came from the body.
    # After the `/`, such a key lands in `fields` and is refused as not
    # updatable, which is the honest answer.
    sets: List[str] = []
    params: List[Any] = []
    for key, value in fields.items():
        if key not in _API_PROJECT_UPDATABLE:
            raise ValueError(f"api_projects.{key} is not updatable")
        if key in _API_PROJECT_JSON_ARRAYS:
            # None means "clear it", which is not the same as a bad shape: an
            # explicit null from a PATCH empties the list, which each reader
            # already has a defined meaning for (CONTRACT-3 §3: an empty
            # `allowed_origins` restricts nothing). A string or an object has
            # no defined meaning at all, which is why one is refused and the
            # other is not.
            value = _json_array(f"api_projects.{key}", value if value is not None else [])
        elif key in _API_PROJECT_JSON_OBJECTS:
            value = _json_object(f"api_projects.{key}", value if value is not None else {})
        elif key == "name":
            value = _text(value)
        sets.append(f"{key} = %s")
        params.append(value)
    if not sets:
        return get_api_project(project_id, workspace_id)
    if "status" in fields:
        # The moment of disabling is evidence, so it is recorded here rather
        # than left to whichever caller remembers; re-disabling keeps the
        # first timestamp.
        sets.append(
            "disabled_at = CASE WHEN %s = 'disabled' "
            "THEN COALESCE(disabled_at, now()) ELSE NULL END"
        )
        params.append(fields["status"])
    params.extend([project_id, workspace_id])
    with connection() as con:
        row = con.execute(
            f"UPDATE api_projects SET {', '.join(sets)} "
            "WHERE id = %s AND workspace_id = %s RETURNING *",
            params,
        ).fetchone()
    return _api_row(row)


# --- service accounts -------------------------------------------------------


def create_service_account(
    project_id: str,
    workspace_id: str,
    name: str,
    *,
    description: str = "",
    scopes: Optional[Sequence[str]] = None,
    allowed_models: Optional[Sequence[str]] = None,
    created_by: Optional[int] = None,
    service_account_id: Optional[str] = None,
) -> dict:
    """Create a service account inside a project this workspace owns.

    The workspace on the new row is copied from the project row in the same
    statement, so the two can never disagree. Raises ValueError when the
    project is not this workspace's.
    """
    columns = ["id", "project_id", "workspace_id", "name", "description"]
    selects = ["%s", "p.id", "p.workspace_id", "%s", "%s"]
    params: List[Any] = [
        service_account_id or _api_id("svc"), _text(name), _text(description) or "",
    ]
    optional = {
        "scopes":
            _json_array("api_service_accounts.scopes", scopes)
            if scopes is not None else None,
        "allowed_models":
            _json_array("api_service_accounts.allowed_models", allowed_models)
            if allowed_models is not None else None,
        "created_by": None if created_by is None else int(created_by),
    }
    for column, value in optional.items():
        if value is None:
            continue
        columns.append(column)
        selects.append("%s")
        params.append(value)
    params.extend([project_id, workspace_id])
    with connection() as con:
        row = con.execute(
            f"INSERT INTO api_service_accounts ({', '.join(columns)}) "
            f"SELECT {', '.join(selects)} FROM api_projects p "
            "WHERE p.id = %s AND p.workspace_id = %s RETURNING *",
            params,
        ).fetchone()
    if row is None:
        raise ValueError(
            f"create_service_account: no api_project {project_id!r} in this workspace"
        )
    return _api_row(row)  # type: ignore[return-value]


def list_service_accounts(project_id: str, workspace_id: str) -> List[dict]:
    """A project's service accounts, oldest first. Both predicates are load
    bearing: `project_id` alone would show another workspace's accounts to
    anybody who could guess a project id."""
    with connection() as con:
        rows = con.execute(
            "SELECT * FROM api_service_accounts WHERE project_id = %s AND workspace_id = %s "
            "ORDER BY created_at, id",
            (project_id, workspace_id),
        ).fetchall()
    return _api_rows(rows)


def get_service_account(service_account_id: str, workspace_id: str) -> Optional[dict]:
    """One service account, or None — including when it is another
    workspace's."""
    with connection() as con:
        row = con.execute(
            "SELECT * FROM api_service_accounts WHERE id = %s AND workspace_id = %s",
            (service_account_id, workspace_id),
        ).fetchone()
    return _api_row(row)


def set_service_account_status(
    service_account_id: str, workspace_id: str, status: str
) -> Optional[dict]:
    """Disable or re-enable a service account; None when it is not this
    workspace's.

    This is the switch an operator reaches for when an integration misbehaves
    at three in the morning: CONTRACT-3 §4 resolves the service account on
    every single `/v1` request and answers 401 when it is disabled, so the
    flip stops every key that hangs off the account at once, with no cached
    state anywhere and nothing to restart. It does NOT revoke those keys, and
    that is the point — re-enabling brings the same integration back without
    a customer having to redeploy a new credential. A COMPROMISE is the other
    operation: revoke each key (`revoke_api_key`), because a disabled account
    whose keys are still valid is one careless re-enable away from being live
    again.

    `disabled_at` is stamped here rather than left to the caller, and a second
    disable keeps the first timestamp — the same rule `update_api_project`
    follows, because the moment it happened is evidence.
    """
    if status not in ("active", "disabled"):
        raise ValueError(
            "set_service_account_status: status must be 'active' or 'disabled'"
        )
    with connection() as con:
        row = con.execute(
            "UPDATE api_service_accounts SET status = %s, "
            "    disabled_at = CASE WHEN %s = 'disabled' "
            "                       THEN COALESCE(disabled_at, now()) ELSE NULL END "
            "WHERE id = %s AND workspace_id = %s RETURNING *",
            (status, status, service_account_id, workspace_id),
        ).fetchone()
    return _api_row(row)


# --- keys -------------------------------------------------------------------


def create_api_key(
    project_id: str,
    workspace_id: str,
    name: str,
    public_id: str,
    key_hash: str,
    last_four: str,
    *,
    service_account_id: Optional[str] = None,
    scopes: Optional[Sequence[str]] = None,
    allowed_models: Optional[Sequence[str]] = None,
    rpm: Optional[int] = None,
    max_concurrency: Optional[int] = None,
    expires_at: Optional[datetime] = None,
    created_by: Optional[int] = None,
    key_id: Optional[str] = None,
    environment: Optional[str] = None,
    rotated_from: Optional[str] = None,
) -> dict:
    """Store a minted key. `key_hash` is HMAC-SHA256(pepper, secret) — the
    plaintext secret is never passed to this module, let alone stored.

    The environment is taken from the PROJECT, not from the caller: a key
    whose prefix says `tsk_test_` while its project is live would be a lie
    told by whichever caller assembled the string. Passing `environment`
    asserts what the caller believes it to be and raises ValueError if the
    project disagrees. A service account, when given, must belong to the same
    project (ValueError otherwise).

    `rotated_from`, when given, must be the public id of a key IN THE SAME
    PROJECT, checked in the INSERT's own WHERE clause exactly like the service
    account (rule 2 above); ValueError otherwise. On 2026-09-13 the verifier
    minted a key in workspace B naming workspace A's public id — which CONTRACT
    §5 calls safe to log — and the rotation sweep revoked A's live key. The
    sweep no longer reads this column at all, and this check is what keeps the
    history it records honest.

    THERE IS NO `rotation_expires_at` ARGUMENT, and its absence is the fix.
    That column is the deadline of the row that carries it (the resolver reads
    it that way), so the only row a rotation may date is the OLD one — through
    `update_api_key_rotation`. Written here, onto the replacement, a zero-
    overlap rotation would have refused the brand-new key the instant it was
    minted. A caller that still passes it gets a TypeError, not a silent
    success.

    The returned row carries no `key_hash` (see `_API_KEY_PUBLIC_COLUMNS`):
    this is the row a show-once console flow is most likely to serialise, and
    the caller already holds the plaintext it needs to show.
    """
    if environment is not None and environment not in _API_ENVIRONMENTS:
        raise ValueError(f"api_keys.environment must be one of {_API_ENVIRONMENTS}")
    columns = [
        "id", "public_id", "key_hash", "last_four", "project_id",
        "workspace_id", "environment", "name", "service_account_id",
    ]
    selects = ["%s", "%s", "%s", "%s", "p.id", "p.workspace_id", "p.environment", "%s", "%s"]
    params: List[Any] = [
        key_id or _api_id("key"), public_id, key_hash, _text(last_four) or "",
        _text(name), service_account_id,
    ]
    optional = {
        "scopes":
            _json_array("api_keys.scopes", scopes) if scopes is not None else None,
        "allowed_models":
            _json_array("api_keys.allowed_models", allowed_models)
            if allowed_models is not None else None,
        "rpm": None if rpm is None else int(rpm),
        "max_concurrency": None if max_concurrency is None else int(max_concurrency),
        "expires_at": expires_at,
        "created_by": None if created_by is None else int(created_by),
        "rotated_from": rotated_from,
    }
    for column, value in optional.items():
        if value is None:
            continue
        columns.append(column)
        selects.append("%s")
        params.append(value)
    params.extend([
        project_id, workspace_id,
        environment, environment,
        service_account_id, service_account_id,
        rotated_from, rotated_from,
    ])
    with connection() as con:
        row = con.execute(
            f"INSERT INTO api_keys ({', '.join(columns)}) "
            f"SELECT {', '.join(selects)} FROM api_projects p "
            "WHERE p.id = %s AND p.workspace_id = %s "
            "  AND (%s::text IS NULL OR p.environment = %s) "
            "  AND (%s::text IS NULL OR EXISTS ("
            "        SELECT 1 FROM api_service_accounts sa "
            "         WHERE sa.id = %s AND sa.project_id = p.id)) "
            "  AND (%s::text IS NULL OR EXISTS ("
            "        SELECT 1 FROM api_keys prev "
            "         WHERE prev.public_id = %s AND prev.project_id = p.id "
            "           AND prev.workspace_id = p.workspace_id)) "
            f"RETURNING {', '.join(_API_KEY_PUBLIC_COLUMNS)}",
            params,
        ).fetchone()
    if row is None:
        project = get_api_project(project_id, workspace_id)
        if project is None:
            raise ValueError(
                f"create_api_key: no api_project {project_id!r} in this workspace"
            )
        if environment is not None and environment != project["environment"]:
            raise ValueError(
                f"create_api_key: project {project_id!r} is "
                f"{project['environment']!r}, not {environment!r}"
            )
        account = (
            get_service_account(service_account_id, workspace_id)
            if service_account_id is not None else None
        )
        if service_account_id is not None and (
            account is None or account.get("project_id") != project_id
        ):
            raise ValueError(
                f"create_api_key: service account {service_account_id!r} does not "
                f"belong to project {project_id!r}"
            )
        # The same sentence whether the public id belongs to another project,
        # another workspace or nobody: which of the three it is would be an
        # existence oracle for another tenant's key.
        raise ValueError(
            f"create_api_key: rotated_from {rotated_from!r} is not a key of "
            f"project {project_id!r}"
        )
    return _api_row(row)  # type: ignore[return-value]


def api_key_by_public_id(public_id: str) -> Optional[dict]:
    """The resolver's read: one key by the id its bearer presented, with the
    project and service account it hangs off already attached under
    `project` / `service_account`.

    No tenant argument, because this call is what DECIDES the tenant
    (CONTRACT-3 §4). It returns revoked and expired keys too: the caller must
    answer 401 identically for unknown, revoked and expired, and it cannot do
    that if this function hides two of the three.

    The three reads see ONE SNAPSHOT. This docstring promised that from the
    start, and on 2026-09-13 the verifier pointed out that the pool runs READ
    COMMITTED, where every statement takes a fresh snapshot — a project
    disabled between the key read and the project read was half seen. The
    transaction is now REPEATABLE READ, set as its first statement, so the
    key, its project and its service account are the state of one instant. A
    change committed a moment later is seen by the NEXT request, which is the
    immediacy CONTRACT §5 promises; what this rules out is a principal
    assembled from two different moments.
    """
    with connection() as con:
        con.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY")
        row = con.execute(
            "SELECT * FROM api_keys WHERE public_id = %s", (public_id,)
        ).fetchone()
        if row is None:
            return None
        project = con.execute(
            "SELECT * FROM api_projects WHERE id = %s", (row["project_id"],)
        ).fetchone()
        service_account = None
        if row["service_account_id"]:
            service_account = con.execute(
                "SELECT * FROM api_service_accounts WHERE id = %s",
                (row["service_account_id"],),
            ).fetchone()
    out = _api_row(row) or {}
    out["project"] = _api_row(project)
    out["service_account"] = _api_row(service_account)
    return out


def list_api_keys(
    project_id: str, workspace_id: str, *, include_revoked: bool = True
) -> List[dict]:
    """A project's keys, newest first, WITHOUT `key_hash`.

    The plaintext secret is never stored at all (CONTRACT-3 §5), and the
    digest that is stored is not selected here — see
    `_API_KEY_PUBLIC_COLUMNS`. So the rows this returns are safe to hand to a
    console page whole, which is what the console will do, and `last_four` is
    the only thing in them that is about the credential itself.
    """
    with connection() as con:
        rows = con.execute(
            f"SELECT {', '.join(_API_KEY_PUBLIC_COLUMNS)} FROM api_keys "
            "WHERE project_id = %s AND workspace_id = %s "
            "AND (%s OR status = 'active') ORDER BY created_at DESC, id",
            (project_id, workspace_id, bool(include_revoked)),
        ).fetchall()
    return _api_rows(rows)


def touch_api_key(key_id: str, ip: Optional[str] = None) -> None:
    """Record that a key was used, and from where.

    Written once per request, never per token. `last_used_ip` is the single
    reason the platform can answer "where is this leaked key being used
    from"; a None leaves the previous value rather than erasing it. The
    service account's own `last_used_at` moves with it so the console can
    show a dormant integration.
    """
    with connection() as con:
        row = con.execute(
            "UPDATE api_keys SET last_used_at = now(), "
            "last_used_ip = COALESCE(%s, last_used_ip) WHERE id = %s "
            "RETURNING service_account_id",
            (_text(ip), key_id),
        ).fetchone()
        if row is not None and row["service_account_id"]:
            con.execute(
                "UPDATE api_service_accounts SET last_used_at = now() WHERE id = %s",
                (row["service_account_id"],),
            )


def revoke_api_key(
    key_id: str, workspace_id: str, *, revoked_by: Optional[int] = None
) -> Optional[dict]:
    """Revoke a key, idempotently; None when it is not this workspace's key.

    The first revocation's timestamp and actor are kept: a second call is a
    no-op that still answers 200 at the surface (RFC 7009), and rewriting
    `revoked_by` would destroy the only record of who actually did it. The
    resolver reads the row on every request, so this takes effect at once —
    there is no cached key state anywhere (CONTRACT-3 §5).

    Returns the same columns as `list_api_keys`, digest excluded: this row
    goes back to a console that has just pressed "revoke", and there is no
    version of that page which needs the HMAC of a key it is destroying.
    """
    with connection() as con:
        row = con.execute(
            "UPDATE api_keys SET status = 'revoked', "
            "revoked_at = COALESCE(revoked_at, now()), "
            "revoked_by = COALESCE(revoked_by, %s) "
            "WHERE id = %s AND workspace_id = %s "
            f"RETURNING {', '.join(_API_KEY_PUBLIC_COLUMNS)}",
            (None if revoked_by is None else int(revoked_by), key_id, workspace_id),
        ).fetchone()
    return _api_row(row)


def update_api_key_rotation(
    key_id: str, workspace_id: str, rotation_expires_at: Optional[datetime]
) -> Optional[dict]:
    """Date a rotated-out key: after `rotation_expires_at` it stops working.

    Written on the OLD key — the one the deadline is about. The resolver
    refuses a key whose own `rotation_expires_at` has passed, and
    `expire_rotated_keys` turns that refusal into a revocation, so this one
    UPDATE is the whole of "rotate with an overlap window" (CONTRACT-3 §5).
    Until 2026-09-13 no accessor could write it, and a rotated-out key lived
    until somebody remembered to revoke it by hand.

    None CLEARS the deadline (an operator cancelling a planned cut-over). The
    status is never touched: dating a revoked key does not bring it back, and
    a deadline in the past on an active key is refused at the very next
    request by the resolver even before the sweep runs.

    Scoped like `revoke_api_key`: None when the key is not this workspace's.
    Returns the digest-free public columns.
    """
    with connection() as con:
        row = con.execute(
            "UPDATE api_keys SET rotation_expires_at = %s "
            "WHERE id = %s AND workspace_id = %s "
            f"RETURNING {', '.join(_API_KEY_PUBLIC_COLUMNS)}",
            (rotation_expires_at, key_id, workspace_id),
        ).fetchone()
    return _api_row(row)


def expire_rotated_keys(
    *, now: Optional[datetime] = None, limit: int = 500
) -> List[dict]:
    """Revoke every active key whose own rotation deadline has passed; returns
    what it revoked.

    WHICH ROW CARRIES THE DEADLINE. `rotation_expires_at` is written on the
    OLD key by `update_api_key_rotation` and read off that same row here and
    by the resolver. The previous version of this sweep read it off the
    SUCCESSOR and joined `successor.rotated_from = previous.public_id` across
    the whole table, which had two consequences found on 2026-09-13: it
    disagreed with the resolver, so nothing it looked for was ever written and
    no overlap was ever enforced; and a key created in workspace B naming
    workspace A's public id got A's live key revoked. With no join, every row
    decides only its own fate, and the only way to put a deadline on a row is
    the workspace-scoped accessor above — so the sweep needs no tenant
    argument to be tenant-safe.

    WHY IT HAS TO EXIST AT ALL. An overlap is two live credentials by
    construction — that is what makes a rotation deployable without an outage
    — and the resolver already refuses a key past its deadline. What the sweep
    adds is the RECORD: the key shows as revoked in the console and in
    `list_api_keys(include_revoked=False)` instead of looking live forever.

    Idempotent: a second run finds nothing because the first one moved the
    rows to `revoked`. `revoked_by` is left NULL, which is the honest record —
    no person did this — and `revoked_at` is stamped like any other
    revocation.
    """
    moment = now or _now()
    bounded = max(1, min(int(limit), 5000))
    with connection() as con:
        rows = con.execute(
            "UPDATE api_keys SET status = 'revoked', "
            "    revoked_at = COALESCE(revoked_at, now()) "
            " WHERE id IN ("
            "        SELECT id FROM api_keys "
            "         WHERE status = 'active' "
            "           AND rotation_expires_at IS NOT NULL "
            "           AND rotation_expires_at <= %s "
            "         ORDER BY rotation_expires_at "
            "         LIMIT %s) "
            "   AND status = 'active' "
            f"RETURNING {', '.join(_API_KEY_PUBLIC_COLUMNS)}",
            (moment, bounded),
        ).fetchall()
    return _api_rows(rows)


# --- responses --------------------------------------------------------------


def create_api_response(
    project_id: str,
    workspace_id: str,
    model: str,
    request_id: str,
    *,
    response_id: Optional[str] = None,
    key_id: Optional[str] = None,
    status: str = "queued",
    background: bool = False,
    streamed: bool = False,
    fingerprint: str = "",
    instructions_present: bool = False,
    metadata: Optional[dict] = None,
    expires_at: Optional[datetime] = None,
) -> dict:
    """The durable row a `/v1/responses` request gets BEFORE any expensive
    work, so a background request survives the client that asked for it.

    `expires_at` defaults to the project's own retention window, computed from
    the project row in the same statement — retention that depends on a
    caller remembering to pass a date is not retention.
    """
    columns = [
        "id", "project_id", "workspace_id", "key_id", "model", "status",
        "background", "streamed", "request_id", "fingerprint",
        "instructions_present", "expires_at",
    ]
    selects = [
        "%s", "p.id", "p.workspace_id", "%s", "%s", "%s", "%s", "%s", "%s",
        "%s", "%s",
        "COALESCE(%s::timestamptz, now() + make_interval(days => p.retention_days))",
    ]
    params: List[Any] = [
        response_id or _api_id("resp"), key_id, _text(model), status,
        bool(background), bool(streamed), _text(request_id) or "",
        _text(fingerprint) or "", bool(instructions_present), expires_at,
    ]
    if metadata is not None:
        columns.append("metadata")
        selects.append("%s")
        params.append(_json_object("api_responses.metadata", metadata))
    params.extend([project_id, workspace_id])
    with connection() as con:
        row = con.execute(
            f"INSERT INTO api_responses ({', '.join(columns)}) "
            f"SELECT {', '.join(selects)} FROM api_projects p "
            "WHERE p.id = %s AND p.workspace_id = %s RETURNING *",
            params,
        ).fetchone()
    if row is None:
        raise ValueError(
            f"create_api_response: no api_project {project_id!r} in this workspace"
        )
    return _api_row(row)  # type: ignore[return-value]


def get_api_response(response_id: str, project_id: str) -> Optional[dict]:
    """One response, scoped to the project whose key asked for it. Another
    project's id reads as missing, which is exactly the 404 the surface owes
    (`response_not_found`)."""
    with connection() as con:
        row = con.execute(
            "SELECT * FROM api_responses WHERE id = %s AND project_id = %s",
            (response_id, project_id),
        ).fetchone()
    return _api_row(row)


def update_api_response(response_id: str, project_id: str, /, **fields: Any) -> Optional[dict]:
    """Advance a response row; None when it is not this project's.

    `started_at` and `completed_at` follow the status unless the caller sets
    them explicitly, because a duration computed from a timestamp somebody
    forgot to write is worse than no duration at all. Raises ValueError for a
    column that may not be set — `project_id`, `workspace_id` and `key_id`
    are not among them: nothing in a request body may move a response between
    tenants.
    """
    sets: List[str] = []
    params: List[Any] = []
    for key, value in fields.items():
        if key not in _API_RESPONSE_UPDATABLE:
            raise ValueError(f"api_responses.{key} is not updatable")
        if key in _API_RESPONSE_JSON:
            value = _json_object(
                f"api_responses.{key}", value if value is not None else {}
            )
        elif key in _API_RESPONSE_TEXT:
            value = _text(value) if value is not None else None
        sets.append(f"{key} = %s")
        params.append(value)
    if not sets:
        return get_api_response(response_id, project_id)
    status = fields.get("status")
    if status == "in_progress" and "started_at" not in fields:
        sets.append("started_at = COALESCE(started_at, now())")
    if status in _API_RESPONSE_TERMINAL and "completed_at" not in fields:
        sets.append("completed_at = COALESCE(completed_at, now())")
    params.extend([response_id, project_id])
    with connection() as con:
        row = con.execute(
            f"UPDATE api_responses SET {', '.join(sets)} "
            "WHERE id = %s AND project_id = %s RETURNING *",
            params,
        ).fetchone()
    return _api_row(row)


def list_api_responses(
    project_id: str, *, status: Optional[str] = None, limit: int = 50
) -> List[dict]:
    """A project's recent responses, newest first, page size clamped."""
    bounded = max(1, min(int(limit), 200))
    with connection() as con:
        rows = con.execute(
            "SELECT * FROM api_responses WHERE project_id = %s "
            "AND (%s::text IS NULL OR status = %s) "
            "ORDER BY created_at DESC, id LIMIT %s",
            (project_id, status, status, bounded),
        ).fetchall()
    return _api_rows(rows)


# --- idempotency ------------------------------------------------------------


#: The claim, as ONE statement on the DATABASE clock. Every time comparison
#: in it is against `now()`, which PostgreSQL fixes at the start of the
#: transaction — so a `get_idempotency` run in the SAME transaction (see
#: `claim_or_get_idempotency`) compares against the identical instant.
_CLAIM_IDEMPOTENCY_SQL = (
    "INSERT INTO api_idempotency "
    "    (project_id, endpoint, idem_key, fingerprint, expires_at) "
    "VALUES (%(project)s, %(endpoint)s, %(key)s, %(fingerprint)s, "
    "        now() + make_interval(secs => %(ttl)s)) "
    "ON CONFLICT (project_id, endpoint, idem_key) DO UPDATE SET "
    # A NEW id for the new holder, so `claim_id` on finish/release tells the
    # request that crashed apart from the one that took its key over; keeping
    # the old id would make them the same claim.
    "    id = nextval(pg_get_serial_sequence('api_idempotency', 'id')), "
    "    fingerprint = excluded.fingerprint, "
    "    state = 'in_flight', "
    "    response_id = NULL, "
    "    created_at = now(), "
    "    expires_at = excluded.expires_at "
    "WHERE api_idempotency.expires_at <= now() "
    "   OR (api_idempotency.fingerprint = excluded.fingerprint "
    "       AND ((%(lease)s::double precision IS NOT NULL "
    "             AND api_idempotency.state = 'in_flight' "
    "             AND api_idempotency.created_at "
    "                 <= now() - make_interval(secs => %(lease)s::double precision)) "
    "         OR (%(reclaim_failed)s "
    "             AND api_idempotency.state = 'completed' "
    "             AND api_idempotency.response_id IS NULL))) "
    "RETURNING *"
)

_GET_IDEMPOTENCY_SQL = (
    "SELECT * FROM api_idempotency "
    "WHERE project_id = %s AND endpoint = %s AND idem_key = %s "
    "  AND expires_at > now()"
)


def _claim_params(
    project_id: str,
    endpoint: str,
    idem_key: str,
    fingerprint: str,
    ttl_hours: float,
    lease_seconds: Optional[float],
    reclaim_failed: bool,
) -> Dict[str, Any]:
    return {
        "project": project_id,
        "endpoint": _text(endpoint),
        "key": _text(idem_key),
        "fingerprint": _text(fingerprint) or "",
        "ttl": float(ttl_hours) * 3600.0,
        "lease": None if lease_seconds is None else max(0.0, float(lease_seconds)),
        "reclaim_failed": bool(reclaim_failed),
    }


def claim_idempotency(
    project_id: str,
    endpoint: str,
    idem_key: str,
    fingerprint: str,
    *,
    ttl_hours: float = 24.0,
    lease_seconds: Optional[float] = None,
    reclaim_failed: bool = False,
    con: Optional[psycopg.Connection] = None,
) -> Optional[dict]:
    """Claim `(project, endpoint, key)` for this request, or None.

    `INSERT ... ON CONFLICT` is the whole point: zero rows back means somebody
    else holds the claim, decided by the unique index rather than by a
    SELECT-then-INSERT with a window in the middle for a retry to get the
    model invoked twice (CONTRACT-3 §13). The loser reads `get_idempotency`
    and either replays the stored response or answers 409 when the
    fingerprint differs — prefer `claim_or_get_idempotency`, which does both
    on one connection and one clock.

    AN EXPIRED CLAIM IS NOT A CLAIM (2026-09-13). The conflict used to be DO
    NOTHING whatever the existing row's age, and nothing but an unscheduled
    prune ever removed one — so a request that crashed between claim and
    finish pinned its Idempotency-Key at 429 "still running" forever, and the
    "retained 24 h" of §13 had no end. The conflict now TAKES OVER a row whose
    `expires_at` has passed, resetting it to a fresh in-flight claim for this
    caller. The takeover is still a single statement: ON CONFLICT DO UPDATE
    locks the conflicting row, and a second claimant that queued behind that
    lock re-evaluates the WHERE against the row the first one just renewed,
    finds it unexpired and gets zero rows — exactly one winner, which
    `test_api_platform_db.py` proves with twelve concurrent claimants.

    THE TWO OTHER TAKEOVERS the request path needs (`apiplatform/idempotency.py`
    decides them), both only for the SAME fingerprint, both off by default:
    `lease_seconds` — an `in_flight` claim created longer ago than this has
    outlived any generation its owner could still be running; and
    `reclaim_failed` — a `completed` claim with no response is an original
    that failed and left nothing to replay.

    ONE CLOCK (2026-09-13). Every comparison here and in `get_idempotency` is
    against the DATABASE's `now()`. The request path used to decide the
    takeover against a Python moment and read the survivor against `now()`:
    a row expiring between the two was neither taken over nor visible, the
    retry reused the stale moment, and the request answered 500. Pass `con`
    to run inside the caller's transaction, where `now()` is one instant.
    """
    with _on(con) as c:
        row = c.execute(
            _CLAIM_IDEMPOTENCY_SQL,
            _claim_params(
                project_id, endpoint, idem_key, fingerprint, ttl_hours,
                lease_seconds, reclaim_failed,
            ),
        ).fetchone()
    return _api_row(row)


def claim_or_get_idempotency(
    project_id: str,
    endpoint: str,
    idem_key: str,
    fingerprint: str,
    *,
    ttl_hours: float = 24.0,
    lease_seconds: Optional[float] = None,
    reclaim_failed: bool = False,
    con: Optional[psycopg.Connection] = None,
) -> Tuple[bool, Optional[dict]]:
    """Claim the key, or read who holds it — `(claimed, row)` — on ONE
    connection, in ONE transaction, against ONE `now()`.

    `(True, row)`: this call owns the work; `row["id"]` is the `claim_id` to
    pass to `finish_idempotency` / `release_idempotency`, so a request whose
    claim was later taken over cannot finish or release the new holder's.
    `(False, row)`: the live claim somebody else holds — compare its
    fingerprint (409) and replay or attach. `(False, None)` only when the
    store neither accepted the claim nor shows a holder twice in a row,
    which is a broken store, not a race.

    WHY ONE TRANSACTION (2026-09-13). PostgreSQL's `now()` is the start of
    the transaction, so the claim's "is it expired" and the read's "is it
    live" are the exact complement of each other: a row the claim declined to
    take over is, by construction, a row the read returns. Two autocommitted
    statements each had their own `now()`, and the request path's own Python
    moment made the gap wide enough to answer 500 (reverify-database, wave 3).
    The one case the read can still miss is a row DELETED between the two
    statements (a release or a prune committed in between); the claim is then
    retried once in the same transaction, where the INSERT simply succeeds.

    One pooled connection for the whole exchange — never a second one while
    the first is held (the 2026-09-13 pool-exhaustion rule).
    """
    params = _claim_params(
        project_id, endpoint, idem_key, fingerprint, ttl_hours,
        lease_seconds, reclaim_failed,
    )
    with _on(con) as c:
        for _attempt in range(2):
            won = c.execute(_CLAIM_IDEMPOTENCY_SQL, params).fetchone()
            if won is not None:
                return True, _api_row(won)
            held = c.execute(
                _GET_IDEMPOTENCY_SQL,
                (project_id, _text(endpoint), _text(idem_key)),
            ).fetchone()
            if held is not None:
                return False, _api_row(held)
    return False, None


def finish_idempotency(
    project_id: str,
    endpoint: str,
    idem_key: str,
    response_id: Optional[str],
    *,
    claim_id: Optional[int] = None,
) -> Optional[dict]:
    """Attach the finished response to its claim so a retry can replay it.

    Only a LIVE claim can be finished: once `expires_at` has passed the claim
    may already belong to somebody else (see `claim_idempotency`), and a
    request that woke up late must not stamp its response onto the new
    holder's key. Pass `claim_id` — the `id` of the row `claim_idempotency`
    returned — to pin the write to exactly the claim this request won; None
    when the claim is gone, expired or not this project's.
    """
    with connection() as con:
        row = con.execute(
            "UPDATE api_idempotency SET state = 'completed', response_id = %s "
            "WHERE project_id = %s AND endpoint = %s AND idem_key = %s "
            "  AND expires_at > now() "
            "  AND (%s::bigint IS NULL OR id = %s) "
            "RETURNING *",
            (
                response_id, project_id, _text(endpoint), _text(idem_key),
                claim_id, claim_id,
            ),
        ).fetchone()
    return _api_row(row)


def release_idempotency(
    project_id: str,
    endpoint: str,
    idem_key: str,
    *,
    claim_id: Optional[int] = None,
) -> bool:
    """Give an IN-FLIGHT claim back, for the failure path; True if one was
    released.

    A request that fails before it produces anything worth replaying (a
    validation error after the claim, a quota refusal, an engine that never
    answered) should not make the client wait out the 24 hours to retry with
    the same key. A COMPLETED claim is never released: deleting it would let
    the same key invoke the model a second time, which is the one thing §13
    exists to prevent. `claim_id` pins the release to the claim this request
    won, so a late failure handler cannot release a claim another request has
    since taken over.
    """
    with connection() as con:
        row = con.execute(
            "DELETE FROM api_idempotency "
            "WHERE project_id = %s AND endpoint = %s AND idem_key = %s "
            "  AND state = 'in_flight' "
            "  AND (%s::bigint IS NULL OR id = %s) "
            "RETURNING id",
            (project_id, _text(endpoint), _text(idem_key), claim_id, claim_id),
        ).fetchone()
    return row is not None


def get_idempotency(
    project_id: str,
    endpoint: str,
    idem_key: str,
    *,
    con: Optional[psycopg.Connection] = None,
) -> Optional[dict]:
    """The existing LIVE claim, scoped to its project: one tenant's
    idempotency key must never resolve to another tenant's response.

    An expired claim reads as absent (2026-09-13), for the same reason
    `claim_idempotency` takes one over: §13 retains a key for 24 hours, and a
    read that ignored `expires_at` turned "retained 24 h" into "retained until
    a prune nobody schedules" — including a crashed request's claim answering
    429 "still running" indefinitely.

    "Expired" is decided by the DATABASE clock, the same `now()` the claim
    uses; a caller that decided anything against its own clock and then reads
    here has two clocks and a gap between them (the wave-3 500). Pass `con`
    to read in the transaction that claimed, or use
    `claim_or_get_idempotency`, which does exactly that."""
    with _on(con) as c:
        row = c.execute(
            _GET_IDEMPOTENCY_SQL,
            (project_id, _text(endpoint), _text(idem_key)),
        ).fetchone()
    return _api_row(row)


# --- usage ledgers ----------------------------------------------------------


@contextmanager
def _on(con: Optional[psycopg.Connection]) -> Iterator[psycopg.Connection]:
    """The caller's transaction when it passes one, a pooled one otherwise.

    What lets the quota engine compose the ledger accessors below inside ONE
    transaction that holds `lock_api_project_usage` — read the window, decide,
    bump — instead of each accessor committing on its own connection with a
    window between them (CONTRACT-3 §12; the 2026-09-13 burst of 12 concurrent
    requests through an rpm=1 project was exactly that window)."""
    if con is not None:
        yield con
        return
    with connection() as own:
        yield own


#: THE one advisory-lock key form for "usage decisions of one project". Every
#: path that reads a project's window and then bumps its ledgers takes THIS
#: lock and no other, because two different key derivations for the same
#: project do not exclude each other: on 2026-09-13 the re-verifier found
#: `quotas.reserve` locking a two-int4 key while this module locked a bigint
#: one, so a caller mixing the two re-opened the burst race the lock exists to
#: close. Single-bigint space (objsubid 1), derived in SQL so no Python hash
#: has to agree with it; it cannot collide with a two-int4 lock at all.
API_PROJECT_USAGE_LOCK_SQL = (
    "SELECT pg_advisory_xact_lock(hashtextextended('api_project_usage:' || %s, 0))"
)

#: Process-local serialisation per project, taken BEFORE a pooled connection is
#: checked out. Refcounted so the dict holds only projects someone is using.
_usage_locks: Dict[str, List[Any]] = {}
_usage_locks_guard = threading.Lock()


@contextmanager
def api_project_usage_process_lock(
    project_id: str, *, timeout: Optional[float] = None
) -> Iterator[None]:
    """Serialise this process's usage decisions for one project WITHOUT
    holding a database connection while waiting.

    THE POOL RULE (2026-09-13). The app has one psycopg pool (16) shared with
    chat. A request that checks out a connection and THEN waits on
    `pg_advisory_xact_lock` parks that connection for as long as the queue in
    front of it: 40 requests for one busy project park all 16, and every chat
    turn, login and history read in the process waits behind them — and if
    the lock holder needs a second pooled connection for anything, nobody
    ever gets one until PoolTimeout (reverify-console-api, wave 3: 9 of 24
    requests failed after 10 s). Waiting HERE first means at most one
    connection per project is ever parked on the advisory lock from this
    process; the advisory lock still serialises against OTHER processes.

    Different projects never wait for each other. `timeout` (seconds) raises
    TimeoutError instead of waiting longer — the caller's cue for a 429.
    """
    with _usage_locks_guard:
        entry = _usage_locks.get(project_id)
        if entry is None:
            entry = [threading.Lock(), 0]
            _usage_locks[project_id] = entry
        entry[1] += 1
    lock: threading.Lock = entry[0]
    try:
        acquired = lock.acquire(timeout=-1 if timeout is None else max(0.0, float(timeout)))
        if not acquired:
            raise TimeoutError(f"usage lock for project {project_id!r} not acquired in time")
        try:
            yield
        finally:
            lock.release()
    finally:
        with _usage_locks_guard:
            entry[1] -= 1
            if entry[1] <= 0 and _usage_locks.get(project_id) is entry:
                del _usage_locks[project_id]


def lock_api_project_usage(
    project_or_con: Any = None,
    project_id: Optional[str] = None,
    *,
    con: Optional[psycopg.Connection] = None,
) -> None:
    """Serialise every usage decision for one project until `con` commits.

    Call it INSIDE the one connection that does all the work:

        with db.api_project_usage_process_lock(pid):   # before the checkout
            with db.connection() as con:
                db.lock_api_project_usage(pid, con=con)
                ...read the window, decide, bump — every statement on `con`

    or simply `with db.api_project_usage_transaction(pid) as con:`, which is
    exactly that. The original `lock_api_project_usage(con, pid)` spelling is
    still accepted.

    `pg_advisory_xact_lock` inside the caller's transaction: a second request
    for the same project blocks here until the first has read the window,
    decided and bumped the counters, and then reads the counters the first
    one wrote. Different projects never wait for each other. Released by
    COMMIT or ROLLBACK — there is no unlock to forget, and a crashed request
    cannot leave a project locked.

    WITHOUT A CONNECTION THIS REFUSES (TypeError) rather than open one: a
    transaction-scoped lock on a connection of its own would be released the
    moment this function returned, and the caller would believe it held a
    lock that no longer exists.
    """
    if isinstance(project_or_con, psycopg.Connection):
        if con is not None:
            raise TypeError("lock_api_project_usage: pass the connection once")
        con, pid = project_or_con, project_id
    elif project_or_con is None:
        pid = project_id  # lock_api_project_usage(project_id=..., con=...)
    else:
        if project_id is not None:
            raise TypeError("lock_api_project_usage(project_id, con=con)")
        pid = project_or_con
    if con is None:
        raise TypeError(
            "lock_api_project_usage needs the connection that does the work "
            "(con=...); use db.api_project_usage_transaction(project_id) to "
            "get one safely"
        )
    if not isinstance(pid, str) or not pid:
        raise TypeError("lock_api_project_usage: project_id must be a non-empty str")
    con.execute(API_PROJECT_USAGE_LOCK_SQL, (pid,))


@contextmanager
def api_project_usage_transaction(
    project_id: str, *, timeout: Optional[float] = None
) -> Iterator[psycopg.Connection]:
    """One connection, one transaction, holding the project's usage lock.

    In this order, which is the whole point: the process-local lock (no
    connection held while waiting), then ONE pooled connection, then the
    advisory lock on it (correctness across processes). Do every read and
    write of the decision on the yielded connection — pass it as `con=` to
    `usage_window`, `bump_usage_minute`, `bump_usage_daily`. Never call an
    accessor without `con=` inside the block: that checks out a second pooled
    connection while this one is held, which is the stall this exists to
    prevent. Commits on a clean exit, rolls back on an exception.
    """
    with api_project_usage_process_lock(project_id, timeout=timeout):
        with connection() as con:
            lock_api_project_usage(project_id, con=con)
            yield con


def _increments(fn: str, **values: Any) -> List[int]:
    """Ledger increments as ints, refusing a negative one.

    The ledgers are additive, so the CHECK on the running total cannot see a
    partial refund that leaves it positive — `requests=-5` against a total of
    40 passes any row CHECK and hands five requests back. On 2026-09-13
    `bump_usage_daily(requests=-100, input_tokens=-1_000_000)` was measured
    leaving the day at -90 requests. A counter only ever moves up; a
    correction is a different operation that nobody has needed yet."""
    out: List[int] = []
    for name, value in values.items():
        number = int(value)
        if number < 0:
            raise ValueError(f"{fn}: {name} may not be negative (got {number})")
        out.append(number)
    return out


def bump_usage_minute(
    project_id: str,
    key_id: str,
    *,
    requests: int = 0,
    input_tokens: int = 0,
    output_tokens: int = 0,
    at: Optional[datetime] = None,
    con: Optional[psycopg.Connection] = None,
) -> dict:
    """Add to this minute's counters for a project+key, atomically.

    ONE statement, no read first. Two requests finishing in the same minute
    from two threads would each read 7 and each write 8 if this were a SELECT
    followed by an UPDATE — the classic lost update, and the lost one is
    always somebody's quota. `excluded` carries the values this call brought
    and the row keeps the running total, so the increment happens inside the
    row lock PostgreSQL already takes.

    ValueError for a negative increment. Pass `con` to bump inside the
    caller's transaction (see `lock_api_project_usage`).
    """
    counts = _increments(
        "bump_usage_minute",
        requests=requests, input_tokens=input_tokens, output_tokens=output_tokens,
    )
    with _on(con) as c:
        row = c.execute(
            "INSERT INTO api_usage_minute "
            "    (project_id, key_id, bucket, requests, input_tokens, output_tokens) "
            "VALUES (%s, %s, %s, %s, %s, %s) "
            "ON CONFLICT (project_id, key_id, bucket) DO UPDATE SET "
            "    requests = api_usage_minute.requests + excluded.requests, "
            "    input_tokens = api_usage_minute.input_tokens + excluded.input_tokens, "
            "    output_tokens = api_usage_minute.output_tokens + excluded.output_tokens "
            "RETURNING *",
            (project_id, key_id, _minute_bucket(at), *counts),
        ).fetchone()
    return _api_row(row)  # type: ignore[return-value]


def bump_usage_daily(
    project_id: str,
    *,
    requests: int = 0,
    input_tokens: int = 0,
    output_tokens: int = 0,
    errors: int = 0,
    rate_limited: int = 0,
    day: Optional[Any] = None,
    con: Optional[psycopg.Connection] = None,
) -> dict:
    """Add to today's project counters, atomically — the same single-statement
    upsert as `bump_usage_minute`, and for the same reason. This is the ledger
    the daily quota and `/v1/usage` read, so it must survive a restart and a
    concurrent writer identically. ValueError for a negative increment."""
    counts = _increments(
        "bump_usage_daily",
        requests=requests, input_tokens=input_tokens, output_tokens=output_tokens,
        errors=errors, rate_limited=rate_limited,
    )
    with _on(con) as c:
        row = c.execute(
            "INSERT INTO api_usage_daily "
            "    (project_id, day, requests, input_tokens, output_tokens, errors, rate_limited) "
            "VALUES (%s, %s, %s, %s, %s, %s, %s) "
            "ON CONFLICT (project_id, day) DO UPDATE SET "
            "    requests = api_usage_daily.requests + excluded.requests, "
            "    input_tokens = api_usage_daily.input_tokens + excluded.input_tokens, "
            "    output_tokens = api_usage_daily.output_tokens + excluded.output_tokens, "
            "    errors = api_usage_daily.errors + excluded.errors, "
            "    rate_limited = api_usage_daily.rate_limited + excluded.rate_limited "
            "RETURNING *",
            (
                project_id, _as_day(day) if day is not None else _now().date(),
                *counts,
            ),
        ).fetchone()
    return _api_row(row)  # type: ignore[return-value]


def _counters(row: Optional[Dict[str, Any]]) -> Dict[str, int]:
    return {
        "requests": int(row["requests"]) if row else 0,
        "input_tokens": int(row["input_tokens"]) if row else 0,
        "output_tokens": int(row["output_tokens"]) if row else 0,
    }


def usage_window(
    project_id: str,
    key_id: str,
    *,
    at: Optional[datetime] = None,
    con: Optional[psycopg.Connection] = None,
) -> dict:
    """What the quota gate needs: this minute and the one before it for the
    key AND for the whole project, and today for the project.

    A counter with no row is reported as 0, not None. That is the opposite of
    `api_responses.input_tokens`, where NULL means "the engine did not tell
    us" — here the absence of a row is positive knowledge that nothing has
    been spent in this window yet.

    THE PROJECT TOTALS (`project_minute`, `project_previous`) ARE THE LIMIT.
    Limits are enforced per project and a key may only tighten its own share
    (CONTRACT-3 §12). On 2026-09-13 ten keys in one rpm=60 project were
    measured admitting 600 requests in a minute, because the only minute
    counters this returned were the calling key's. The project figures are
    summed over every key's row for the two buckets, in the same statement
    that reads the key's own, so the two can never come from different
    moments.

    THE PREVIOUS BUCKET IS WHAT MAKES THE WINDOW SLIDE. CONTRACT-3 §12 says
    the per-minute limits are enforced as a "sliding window, durable", and V34
    stores fixed minute buckets — which look like a disagreement and are not.
    The standard approximation reads both buckets and weights the older one by
    how much of it is still inside the window:

        elapsed  = seconds since the current bucket started
        estimate = current.requests
                 + previous.requests * (60 - elapsed) / 60

    The weighting belongs in the quota engine, not here: this function
    reports what was spent, and policy decides what that means. Pass `con` to
    read inside the caller's locked transaction.
    """
    moment = at or _now()
    bucket = _minute_bucket(moment)
    earlier = bucket - timedelta(minutes=1)
    with _on(con) as c:
        rows = c.execute(
            "WITH spent AS ("
            "    SELECT bucket, (key_id = %s) AS mine, requests, input_tokens, output_tokens "
            "      FROM api_usage_minute "
            "     WHERE project_id = %s AND bucket IN (%s, %s)) "
            "SELECT bucket, mine, sum(requests) AS requests, "
            "       sum(input_tokens) AS input_tokens, sum(output_tokens) AS output_tokens "
            "  FROM spent GROUP BY bucket, mine",
            (key_id, project_id, bucket, earlier),
        ).fetchall()
        daily = c.execute(
            "SELECT requests, input_tokens, output_tokens, errors, rate_limited "
            "FROM api_usage_daily WHERE project_id = %s AND day = %s",
            (project_id, moment.date()),
        ).fetchone()
    key_rows: Dict[Any, Dict[str, Any]] = {}
    project_totals: Dict[Any, Dict[str, int]] = {}
    for row in rows:
        if row["mine"]:
            key_rows[row["bucket"]] = row
        total = project_totals.setdefault(
            row["bucket"], {"requests": 0, "input_tokens": 0, "output_tokens": 0}
        )
        for name, value in _counters(row).items():
            total[name] += value
    empty = {"requests": 0, "input_tokens": 0, "output_tokens": 0}
    return {
        "project_id": project_id,
        "key_id": key_id,
        "bucket": _iso(bucket),
        "previous_bucket": _iso(earlier),
        # How far into the current bucket `at` falls, which is the only other
        # number the sliding-window estimate needs. Reported rather than left
        # to the caller because the caller would have to re-derive the bucket
        # boundary to compute it, and the two must agree.
        "elapsed_seconds": (moment - bucket).total_seconds(),
        "day": moment.date().isoformat(),
        "minute": _counters(key_rows.get(bucket)),
        "previous": _counters(key_rows.get(earlier)),
        "project_minute": dict(project_totals.get(bucket, empty)),
        "project_previous": dict(project_totals.get(earlier, empty)),
        "daily": {
            "requests": int(daily["requests"]) if daily else 0,
            "input_tokens": int(daily["input_tokens"]) if daily else 0,
            "output_tokens": int(daily["output_tokens"]) if daily else 0,
            "errors": int(daily["errors"]) if daily else 0,
            "rate_limited": int(daily["rate_limited"]) if daily else 0,
        },
    }


def read_usage_daily(
    project_id: str, start_day: Any, end_day: Any, *, max_days: int = 93
) -> List[dict]:
    """A project's daily rows over a BOUNDED, inclusive range, oldest first.

    The bound is not politeness: `/v1/usage` and the console both put this
    range on the wire, and an unbounded one is a client-supplied result size
    — the denial-of-service shape OWASP API4 names directly. Raises ValueError
    for a reversed range or one longer than `max_days`.
    """
    first, last = _as_day(start_day), _as_day(end_day)
    if last < first:
        raise ValueError("read_usage_daily: end_day is before start_day")
    span = (last - first).days + 1
    if span > int(max_days):
        raise ValueError(
            f"read_usage_daily: {span} days requested, the maximum is {int(max_days)}"
        )
    with connection() as con:
        rows = con.execute(
            "SELECT * FROM api_usage_daily WHERE project_id = %s AND day BETWEEN %s AND %s "
            "ORDER BY day",
            (project_id, first, last),
        ).fetchall()
    return _api_rows(rows)


# --- webhooks ---------------------------------------------------------------


def create_webhook_endpoint(
    project_id: str,
    workspace_id: str,
    url: str,
    events: Sequence[str],
    secret: str,
    *,
    include_output: bool = False,
    created_by: Optional[int] = None,
    endpoint_id: Optional[str] = None,
) -> dict:
    """Register a delivery target for a project's events.

    HTTPS only, refused here as well as at delivery time: a plaintext target
    would put the signed payload — and the fact that a particular customer is
    calling this API at all — on the wire in clear. The SSRF checks that
    matter run per delivery, against the RESOLVED address, because a hostname
    that is safe today can point at 169.254.169.254 tomorrow (CONTRACT-3 §14).

    The returned row carries NO `secret` or `previous_secret`, like every
    other read of this table except the delivery sweep (2026-09-13). An
    earlier version argued the creator "already holds it" and returned the
    value; the review's answer is that a row which sometimes carries the
    forgery primitive is a row nobody can safely serialise, and the caller
    that generated the secret has it in a local variable for the show-once
    response. The ONE rule is now: no accessor that returns a row to a
    request path returns a secret.

    `has_secret` and `has_previous_secret` ride along on EVERY path — this
    one, the update, the list and the scoped read — so a console page has one
    spelling for "is this endpoint signed / is a rotation in flight", rather
    than a truth test on a value that is present here and absent there.
    """
    if not str(url).lower().startswith("https://"):
        raise ValueError("create_webhook_endpoint: the url must be https://")
    columns = ["id", "project_id", "workspace_id", "url", "events", "secret", "include_output"]
    selects = ["%s", "p.id", "p.workspace_id", "%s", "%s", "%s", "%s"]
    params: List[Any] = [
        endpoint_id or _api_id("whe"), _text(url),
        _json_array("api_webhook_endpoints.events", events),
        secret, bool(include_output),
    ]
    if created_by is not None:
        columns.append("created_by")
        selects.append("%s")
        params.append(int(created_by))
    params.extend([project_id, workspace_id])
    with connection() as con:
        row = con.execute(
            f"INSERT INTO api_webhook_endpoints ({', '.join(columns)}) "
            f"SELECT {', '.join(selects)} FROM api_projects p "
            "WHERE p.id = %s AND p.workspace_id = %s "
            f"RETURNING {_WEBHOOK_ENDPOINT_PUBLIC_SELECT}",
            params,
        ).fetchone()
    if row is None:
        raise ValueError(
            f"create_webhook_endpoint: no api_project {project_id!r} in this workspace"
        )
    return _api_row(row)  # type: ignore[return-value]


def list_webhook_endpoints(project_id: str, workspace_id: str) -> List[dict]:
    """A project's endpoints, oldest first, WITHOUT the signing secrets.

    `secret` and `previous_secret` are excluded at the SELECT (see
    `_WEBHOOK_ENDPOINT_PUBLIC_COLUMNS`), so no console route can leak one by
    serialising these rows — which is what a route does with a list by
    default. Both tenancy predicates are load bearing: `project_id` alone
    would list another workspace's endpoints, secrets or not.
    """
    with connection() as con:
        rows = con.execute(
            f"SELECT {_WEBHOOK_ENDPOINT_PUBLIC_SELECT} "
            "FROM api_webhook_endpoints "
            "WHERE project_id = %s AND workspace_id = %s ORDER BY created_at, id",
            (project_id, workspace_id),
        ).fetchall()
    return _api_rows(rows)


def get_webhook_endpoint(endpoint_id: str, workspace_id: str) -> Optional[dict]:
    """One endpoint, or None — including when it is another workspace's.
    Scrubbed of the signing secrets exactly like `list_webhook_endpoints`."""
    with connection() as con:
        row = con.execute(
            f"SELECT {_WEBHOOK_ENDPOINT_PUBLIC_SELECT} "
            "FROM api_webhook_endpoints WHERE id = %s AND workspace_id = %s",
            (endpoint_id, workspace_id),
        ).fetchone()
    return _api_row(row)


def update_webhook_endpoint(
    endpoint_id: str, workspace_id: str, /, **fields: Any
) -> Optional[dict]:
    """Change an endpoint, including rotating its secret with an overlap
    (`previous_secret` + `previous_secret_expires_at`). None when it is not
    this workspace's endpoint; ValueError for a column that may not be set.

    NO CHANGES REQUESTED IS NOT NOT-FOUND. This used to return None for both,
    so a route mapping None to 404 would have 404'd an endpoint that exists
    and is owned by the caller, purely because the PATCH body happened to be
    empty — the sibling `update_api_project` has always fallen through to a
    scoped read instead, and the 2026-09-12 verifier found the pair disagreeing
    with neither branch tested. The empty case now answers exactly what
    `get_webhook_endpoint` would: the current row, secrets excluded. It is
    therefore not a back door to the signing secret.

    NO PATH RETURNS THE SECRET (2026-09-13). This docstring used to say only a
    rotation echoed it back, while the statement was `RETURNING *` — so a
    PATCH of `status` or `events` handed out the live signing secret and the
    previous one, which is the forgery primitive for every delivery to that
    endpoint. Every update now returns `_WEBHOOK_ENDPOINT_PUBLIC_SELECT`; a
    rotation's caller generated the new value and already holds it.

    `url` is refused unless it is https://, here as well as at creation: a
    PATCH is the obvious way around a check that only guards the POST.
    """
    sets: List[str] = []
    params: List[Any] = []
    for key, value in fields.items():
        if key not in _WEBHOOK_ENDPOINT_UPDATABLE:
            raise ValueError(f"api_webhook_endpoints.{key} is not updatable")
        if key == "url" and value is not None and not str(value).lower().startswith("https://"):
            raise ValueError("update_webhook_endpoint: the url must be https://")
        if key in _WEBHOOK_ENDPOINT_JSON:
            value = _json_array(
                f"api_webhook_endpoints.{key}", value if value is not None else []
            )
        elif key == "url":
            value = _text(value)
        sets.append(f"{key} = %s")
        params.append(value)
    if not sets:
        return get_webhook_endpoint(endpoint_id, workspace_id)
    if "status" in fields:
        sets.append(
            "disabled_at = CASE WHEN %s = 'disabled' "
            "THEN COALESCE(disabled_at, now()) ELSE NULL END"
        )
        params.append(fields["status"])
    params.extend([endpoint_id, workspace_id])
    with connection() as con:
        row = con.execute(
            f"UPDATE api_webhook_endpoints SET {', '.join(sets)} "
            "WHERE id = %s AND workspace_id = %s "
            f"RETURNING {_WEBHOOK_ENDPOINT_PUBLIC_SELECT}",
            params,
        ).fetchone()
    return _api_row(row)


def delete_webhook_endpoint(endpoint_id: str, workspace_id: str) -> bool:
    """Remove an endpoint and its delivery history (FK CASCADE). False when
    it is not this workspace's endpoint — including when it never existed."""
    with connection() as con:
        row = con.execute(
            "DELETE FROM api_webhook_endpoints WHERE id = %s AND workspace_id = %s "
            "RETURNING id",
            (endpoint_id, workspace_id),
        ).fetchone()
    return row is not None


def enqueue_webhook_delivery(
    endpoint_id: str,
    project_id: str,
    event_type: str,
    event_id: str,
    payload: Optional[dict] = None,
    *,
    response_id: Optional[str] = None,
    max_attempts: int = 6,
    delivery_id: Optional[str] = None,
    next_attempt_at: Optional[datetime] = None,
) -> Optional[dict]:
    """Queue one delivery; None when this `event_id` is already queued to this
    endpoint.

    The duplicate case is a normal outcome, not an error: the same event may
    be enqueued twice by a retried caller, and the unique index is what makes
    the consumer's idempotency promise true. Raises ValueError only when the
    endpoint is not this project's.
    """
    with connection() as con:
        row = con.execute(
            "INSERT INTO api_webhook_deliveries "
            "    (id, event_id, endpoint_id, project_id, event_type, response_id, "
            "     payload, max_attempts, next_attempt_at) "
            "SELECT %s, %s, e.id, e.project_id, %s, %s, %s, %s, COALESCE(%s::timestamptz, now()) "
            "  FROM api_webhook_endpoints e "
            " WHERE e.id = %s AND e.project_id = %s "
            "ON CONFLICT (endpoint_id, event_id) DO NOTHING "
            "RETURNING *",
            (
                delivery_id or _api_id("whd"), _text(event_id), _text(event_type),
                response_id,
                _json_object(
                    "api_webhook_deliveries.payload",
                    payload if payload is not None else {},
                ),
                int(max_attempts), next_attempt_at, endpoint_id, project_id,
            ),
        ).fetchone()
        if row is None:
            known = con.execute(
                "SELECT 1 FROM api_webhook_endpoints WHERE id = %s AND project_id = %s",
                (endpoint_id, project_id),
            ).fetchone()
    if row is None and known is None:
        raise ValueError(
            f"enqueue_webhook_delivery: no webhook endpoint {endpoint_id!r} in "
            f"project {project_id!r}"
        )
    return _api_row(row)


def due_webhook_deliveries(limit: int = 20, *, now: Optional[datetime] = None) -> List[dict]:
    """The deliveries whose next attempt is due, oldest first, each with the
    endpoint it must be sent to attached under `endpoint`.

    Not tenant-scoped, and could not be: this is the server's own sweep, not
    a caller's read. A delivery whose endpoint has been disabled is skipped
    rather than dropped, so re-enabling an endpoint resumes its queue instead
    of losing it.
    """
    bounded = max(1, min(int(limit), 200))
    with connection() as con:
        rows = con.execute(
            "SELECT d.*, e.url AS endpoint_url, e.secret AS endpoint_secret, "
            "       e.previous_secret AS endpoint_previous_secret, "
            "       e.previous_secret_expires_at AS endpoint_previous_secret_expires_at, "
            "       e.include_output AS endpoint_include_output, "
            "       e.events AS endpoint_events "
            "  FROM api_webhook_deliveries d "
            "  JOIN api_webhook_endpoints e ON e.id = d.endpoint_id "
            " WHERE d.status = 'pending' AND e.status = 'active' "
            "   AND d.attempt < d.max_attempts "
            "   AND (d.next_attempt_at IS NULL OR d.next_attempt_at <= %s) "
            " ORDER BY d.next_attempt_at NULLS FIRST, d.created_at, d.id "
            " LIMIT %s",
            (now or _now(), bounded),
        ).fetchall()
    out: List[dict] = []
    for row in rows:
        delivery = _api_row(row) or {}
        endpoint = {
            "id": delivery["endpoint_id"],
            "url": delivery.pop("endpoint_url"),
            "secret": delivery.pop("endpoint_secret"),
            "previous_secret": delivery.pop("endpoint_previous_secret"),
            "previous_secret_expires_at": delivery.pop("endpoint_previous_secret_expires_at"),
            "include_output": delivery.pop("endpoint_include_output"),
            "events": delivery.pop("endpoint_events"),
        }
        delivery["endpoint"] = endpoint
        out.append(delivery)
    return out


def record_webhook_attempt(
    delivery_id: str,
    *,
    status: str,
    http_status: Optional[int] = None,
    error: str = "",
    next_attempt_at: Optional[datetime] = None,
    project_id: Optional[str] = None,
) -> Optional[dict]:
    """Record the outcome of one attempt and schedule (or stop) the next.

    The attempt counter moves here and nowhere else, so a retry loop cannot
    run forever by forgetting to increment it. The endpoint's own health
    columns move with it: `consecutive_failures` is what lets the console
    show a dead endpoint and what an auto-disable policy would read, and it
    is reset by a delivery rather than by time.

    PASS `project_id` FROM ANY REQUEST HANDLER. Without it this is a write
    addressed by a bare id, which rule 1 at the top of this section says
    should not exist. The delivery sweep is allowed to call it that way
    because the sweep is the server acting on its own queue, not a caller
    acting on a row it named; a console "retry this delivery" button IS a
    caller naming a row, and it must pass the project the session already
    proved, so that another tenant's delivery id reads as missing (None)
    instead of being retried. Delivery ids are CSPRNG (`_api_id`), which makes
    the difference hard to exploit and does not make it correct.
    """
    if status not in ("pending", "delivered", "failed", "dropped"):
        raise ValueError(
            "record_webhook_attempt: status must be pending, delivered, failed or dropped"
        )
    with connection() as con:
        row = con.execute(
            "UPDATE api_webhook_deliveries SET attempt = attempt + 1, status = %s, "
            "    http_status = %s, error = %s, next_attempt_at = %s, "
            "    delivered_at = CASE WHEN %s = 'delivered' THEN now() ELSE delivered_at END "
            "WHERE id = %s AND (%s::text IS NULL OR project_id = %s) RETURNING *",
            (
                status, None if http_status is None else int(http_status),
                _text(error) or "", next_attempt_at, status, delivery_id,
                project_id, project_id,
            ),
        ).fetchone()
        if row is None:
            return None
        con.execute(
            "UPDATE api_webhook_endpoints SET last_delivery_at = now(), "
            "    last_delivery_status = %s, "
            "    consecutive_failures = CASE WHEN %s = 'delivered' THEN 0 "
            "                                ELSE consecutive_failures + 1 END "
            "WHERE id = %s",
            (status, status, row["endpoint_id"]),
        )
    return _api_row(row)


# --- public model overrides -------------------------------------------------


def _workspace_arg(fn: str, workspace_id: Any) -> str:
    """The workspace a model override belongs to, or TypeError.

    Both model accessors took no tenant until 2026-09-13, and the old call
    shapes are still plausible — `public_model_overrides(declared_ids)` would
    otherwise pass a tuple where the workspace goes and quietly match
    nothing. A loud TypeError at the first call is the migration path."""
    if not isinstance(workspace_id, str) or not workspace_id:
        raise TypeError(
            f"{fn}: the first argument is the workspace id (a non-empty str), "
            f"not {type(workspace_id).__name__} — model overrides are per workspace"
        )
    return workspace_id


def public_model_overrides(
    workspace_id: str, declared: Optional[Sequence[str]] = None
) -> Dict[str, bool]:
    """One workspace's view of which public models are enabled.

    PER WORKSPACE (2026-09-13). The table used to hold one row per model for
    the whole deployment, so a super admin of one workspace disabling a model
    disabled it for every customer. The `/v1` path passes the CALLER's
    workspace and the console passes the principal's; another workspace's
    rows are invisible to both.

    WITH `declared` (the ids the code-level registry actually declares), the
    result carries ONLY entries that DISABLE one of them: a row for an id the
    code does not declare is dropped, and a row that merely re-enables a
    declared model is a no-op that is dropped too. That is the narrowing rule
    of CONTRACT-3 §15 expressed where it cannot be skipped — with this
    argument, no row in this table and no amount of database access can make
    a model public that the code did not publish.

    Without it, the raw mapping is returned for the console, which has to be
    able to see a row before it can fix it.
    """
    workspace = _workspace_arg("public_model_overrides", workspace_id)
    with connection() as con:
        rows = con.execute(
            "SELECT id, enabled FROM public_models WHERE workspace_id = %s ORDER BY id",
            (workspace,),
        ).fetchall()
    stored = {str(row["id"]): bool(row["enabled"]) for row in rows}
    if declared is None:
        return stored
    allowed = set(declared)
    return {
        model_id: False
        for model_id, enabled in stored.items()
        if model_id in allowed and not enabled
    }


def set_public_model_enabled(
    workspace_id: str,
    model_id: str,
    enabled: bool,
    *,
    updated_by: Optional[int] = None,
) -> dict:
    """Record one workspace administrator's decision about one public model
    id, for THAT workspace only. db.IntegrityError when the workspace does not
    exist."""
    workspace = _workspace_arg("set_public_model_enabled", workspace_id)
    with connection() as con:
        row = con.execute(
            "INSERT INTO public_models (workspace_id, id, enabled, updated_by, updated_at) "
            "VALUES (%s, %s, %s, %s, now()) "
            "ON CONFLICT (workspace_id, id) DO UPDATE SET enabled = excluded.enabled, "
            "    updated_by = excluded.updated_by, updated_at = excluded.updated_at "
            "RETURNING *",
            (
                workspace, _text(model_id), bool(enabled),
                None if updated_by is None else int(updated_by),
            ),
        ).fetchone()
    return _api_row(row)  # type: ignore[return-value]


# --- platform secrets -------------------------------------------------------


def get_platform_secret(name: str) -> Optional[str]:
    """The stored value, or None. Never logged, never returned by any API."""
    with connection() as con:
        row = con.execute(
            "SELECT value FROM platform_secrets WHERE name = %s", (name,)
        ).fetchone()
    return None if row is None else str(row["value"])


def set_platform_secret(name: str, value: str) -> str:
    """Store a secret ONCE and return whatever is stored — which may be
    somebody else's value.

    This is write-once by design, and the design is the whole safety
    property. The API-key pepper is generated on first use when
    `API_KEY_PEPPER` is unset (CONTRACT-3 §5); if two workers generate one at
    the same moment and the second overwrote the first, every key digest
    already written under the first pepper would stop verifying and every
    customer's key would 401 with nothing in the logs to explain it. `ON
    CONFLICT DO NOTHING` plus a read-back makes the loser adopt the winner's
    value instead.
    """
    with connection() as con:
        con.execute(
            "INSERT INTO platform_secrets (name, value) VALUES (%s, %s) "
            "ON CONFLICT (name) DO NOTHING",
            (name, value),
        )
        row = con.execute(
            "SELECT value FROM platform_secrets WHERE name = %s", (name,)
        ).fetchone()
    return str(row["value"])


# --- retention --------------------------------------------------------------


def prune_api_platform(
    *,
    now: Optional[datetime] = None,
    minute_retention_days: int = 7,
    delivery_retention_days: int = 30,
    batch_size: int = 5000,
    max_batches: int = 200,
) -> Dict[str, int]:
    """Enforce retention across the platform tables; returns what it removed.

    Six separate jobs, deliberately in one function so a deployment has one
    thing to schedule:

      * idempotency claims past `expires_at` — they are a 24 h promise, not a
        record (reads already treat an expired claim as absent; this reclaims
        the space);
      * minute counters older than `minute_retention_days` — the daily ledger
        is the durable one, and the minute table exists to answer "right now";
      * responses past their own `expires_at`, which was computed from the
        project's `retention_days` when the row was created;
      * generated text on responses that are still inside their retention
        window but whose PROJECT has since shortened it — the text goes, the
        metadata row stays, because the usage record must outlive the content
        (CONTRACT-3 §16);
      * FINISHED webhook deliveries older than `delivery_retention_days`. A
        `pending` delivery is never pruned, however old: it is a promise to a
        customer that has not been kept yet, and deleting it is the silent
        drop the delivery history exists to rule out;
      * active keys past their own `rotation_expires_at`, revoked by
        `expire_rotated_keys` so the console's record matches what the
        resolver already refuses (`api_keys_rotated_out`).

    BATCHED, ONE TRANSACTION PER BATCH (2026-09-13). All five used to run as
    unbounded statements inside one transaction under the 15 s
    `statement_timeout`; on a table large enough to need pruning, one timeout
    rolled every job back and retention silently never made progress. Each
    job now deletes `batch_size` rows at a time by `ctid`, commits, and goes
    again until a batch comes back short, so a slow table costs only its own
    last batch and every earlier commit stands. `max_batches` bounds one run;
    the next scheduled run continues where this one stopped.

    `rowcount` rather than RETURNING: a prune can touch a great many rows and
    there is no reason to bring any of them back.
    """
    moment = now or _now()
    size = max(1, int(batch_size))
    batches = max(1, int(max_batches))
    jobs: Tuple[Tuple[str, str, Tuple[Any, ...]], ...] = (
        (
            "api_idempotency",
            # The DATABASE clock unless a caller drives it (2026-09-13): the
            # claim and the read decide "expired" against `now()`, and a
            # Python moment ahead of it could delete a claim both of them
            # still consider live.
            "DELETE FROM api_idempotency WHERE ctid IN ("
            " SELECT ctid FROM api_idempotency "
            "  WHERE expires_at < COALESCE(%s::timestamptz, now()) LIMIT %s)",
            (now,),
        ),
        (
            "api_usage_minute",
            "DELETE FROM api_usage_minute WHERE ctid IN ("
            " SELECT ctid FROM api_usage_minute WHERE bucket < %s LIMIT %s)",
            (moment - timedelta(days=int(minute_retention_days)),),
        ),
        (
            "api_responses",
            "DELETE FROM api_responses WHERE ctid IN ("
            " SELECT ctid FROM api_responses "
            "  WHERE expires_at IS NOT NULL AND expires_at < %s LIMIT %s)",
            (moment,),
        ),
        (
            "api_responses_output_text",
            "UPDATE api_responses SET output_text = NULL WHERE ctid IN ("
            " SELECT r.ctid FROM api_responses r JOIN api_projects p ON p.id = r.project_id "
            "  WHERE r.output_text IS NOT NULL "
            "    AND r.created_at < %s - make_interval(days => p.retention_days) "
            "  LIMIT %s)",
            (moment,),
        ),
        (
            "api_webhook_deliveries",
            "DELETE FROM api_webhook_deliveries WHERE ctid IN ("
            " SELECT ctid FROM api_webhook_deliveries "
            "  WHERE status IN ('delivered', 'failed', 'dropped') AND created_at < %s "
            "  LIMIT %s)",
            (moment - timedelta(days=int(delivery_retention_days)),),
        ),
    )
    counts: Dict[str, int] = {}
    for name, statement, params in jobs:
        total = 0
        for _ in range(batches):
            with connection() as con:
                touched = con.execute(statement, (*params, size)).rowcount
            total += max(0, int(touched))
            if touched < size:
                break
        counts[name] = total
    # The rotation sweep rides along (2026-09-13). `expire_rotated_keys` was
    # fixed and never scheduled — main.py schedules only this function — so a
    # rotated-out key past its deadline was refused by the resolver but listed
    # as `active` forever. This function is the one thing a deployment
    # schedules, so the record is kept here, in bounded batches like the rest.
    rotated = 0
    for _ in range(batches):
        revoked = len(expire_rotated_keys(now=now, limit=size))
        rotated += revoked
        if revoked < min(size, 5000):
            break
    counts["api_keys_rotated_out"] = rotated
    return counts
